    !isAgentRemoteInstructionPositiveControlField(field) &&
    /(?:^|[_\W])(secret|token|credential|api[_-]?key|password|vault|key[_\s-]?vault|authorization|oauth|secret[_\s-]?lookup)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
