function hasInboundTriggerApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /approval|required[_-]?approval|human[_-]?approval|confirm|confirmation|moderation|review/iu.test(field.path) &&
    truthyConfigValue(field.value)
  );
}

function isInboundTriggerSecurityField(fieldPath: string): boolean {
  return /provider|source|input|event|trigger|webhook|listener|receiver|callback|signature|signing|hmac|timestamp|freshness|replay|nonce|dedupe|idempotency|mail|email|message|chat|ticket|issue|comment|payload|body|attachment|file|upload|document|extract|parser|sandbox|scan|malware|virus|sanitize|instruction|agent|assistant|bot|tool|mcp|browser|database|secret|memory|reply|respond|send|write|post|publish|approval|auth|token|credential|scope|permission|url|host|endpoint|queue|topic|subscription/iu.test(
    fieldPath
  );
}

function classifyHostedAssistantConfig(value: unknown, filePath: string): HostedAssistantPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const provider = inferHostedAssistantProvider([filePath, ...fields.map((field) => field.path), ...stringValues]);
  const toolCategories = collectHostedAssistantToolCategories(fields);
  const privilegedToolCategoryCount = countHostedAssistantPrivilegedToolCategories(toolCategories);
  const parallelToolCalls = hasHostedAssistantParallelToolCalls(fields);
  const vectorStoreCount = countHostedAssistantVectorStoreRefs(fields);
  const fileCount = countHostedAssistantFileRefs(fields);
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    hosted_assistant_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isHostedAssistantSecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    hosted_assistant_provider: provider,
    hosted_assistant_definition_detected: hasHostedAssistantDefinitionSignal(fields, provider),
    hosted_assistant_model_redacted: hasHostedAssistantModelSignal(fields),
    hosted_assistant_instructions_redacted: hasHostedAssistantInstructionSignal(fields),
    hosted_assistant_tool_names_redacted: toolCategories.length > 0 || hasHostedAssistantToolNameSignal(fields),
    hosted_assistant_tool_count: countHostedAssistantToolEntries(value, fields),
    hosted_assistant_tool_categories: toolCategories,
    hosted_assistant_privileged_tools: isHostedAssistantPrivileged(toolCategories),
    hosted_assistant_privileged_tool_category_count: privilegedToolCategoryCount,
    hosted_assistant_code_interpreter_enabled: toolCategories.includes("code_interpreter"),
    hosted_assistant_file_search_enabled: toolCategories.includes("file_search"),
    hosted_assistant_function_tools_enabled: toolCategories.includes("function_tool"),
    hosted_assistant_mcp_tools_enabled: toolCategories.includes("mcp_connector"),
    hosted_assistant_web_search_enabled: toolCategories.includes("web_search"),
    hosted_assistant_computer_use_enabled: toolCategories.includes("computer_use"),
    hosted_assistant_external_tool_authority: hasHostedAssistantExternalToolAuthority(toolCategories),
    hosted_assistant_write_tool_authority: hasHostedAssistantWriteToolAuthority(fields, toolCategories),
    hosted_assistant_memory_write: hasHostedAssistantMemoryWriteSignal(fields, vectorStoreCount),
    hosted_assistant_tool_choice_auto: hasHostedAssistantAutomaticToolChoice(fields, toolCategories),
    hosted_assistant_parallel_tool_calls: parallelToolCalls,
    hosted_assistant_parallel_privileged_tool_fanout: parallelToolCalls && privilegedToolCategoryCount > 1,
    hosted_assistant_tool_resources_redacted: hasHostedAssistantToolResourceSignal(fields),
    hosted_assistant_vector_store_redacted: vectorStoreCount > 0,
    hosted_assistant_vector_store_count: vectorStoreCount,
    hosted_assistant_file_ids_redacted: fileCount > 0,
    hosted_assistant_file_count: fileCount,
    hosted_assistant_sensitive_context: hasHostedAssistantSensitiveContextSignal(fields),
    hosted_assistant_pii_context: hasHostedAssistantPiiContextSignal(fields),
    hosted_assistant_secret_context: hasHostedAssistantSecretContextSignal(fields) || envKeys.some(isCredentialLikeKeyName) || secretRefKeys.length > 0,
    hosted_assistant_untrusted_input: hasHostedAssistantUntrustedInputSignal(fields),
    hosted_assistant_guardrails_disabled: hasHostedAssistantGuardrailsDisabledSignal(fields),
    hosted_assistant_approval_required: hasHostedAssistantApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function inferHostedAssistantProvider(candidates: string[]): string | undefined {
  const text = candidates.join(" ").toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
  const providers: Array<[string, RegExp]> = [
    ["openai_assistants", /\b(openai|assistant_id|assistants?\.create|assistant[_-]?api|responses?[_-]?api)\b/iu],
    ["azure_openai_assistants", /\b(azure[_\s-]?openai|aoai)\b/iu],
    ["anthropic_agent", /\b(anthropic|claude|tool_use)\b/iu],
    ["bedrock_agent", /\b(bedrock|amazon[_\s-]?bedrock)\b/iu],
    ["vertex_agent", /\b(vertex|google[_\s-]?cloud[_\s-]?ai|gemini)\b/iu],
    ["langgraph_cloud", /\b(langgraph[_\s-]?cloud|langsmith)\b/iu],
    ["hosted_assistant", /\b(hosted[_\s-]?assistant|hosted[_\s-]?agent|assistant[_\s-]?definition)\b/iu]
  ];
  return providers.find(([, pattern]) => pattern.test(text))?.[0];
}

function hasHostedAssistantDefinitionSignal(fields: RuntimeField[], provider: string | undefined): boolean {
  if (provider !== undefined) return true;
  const hasModel = hasHostedAssistantModelSignal(fields);
  const hasInstructions = hasHostedAssistantInstructionSignal(fields);
  const hasTools = countHostedAssistantToolEntries(undefined, fields) > 0 || collectHostedAssistantToolCategories(fields).length > 0;
  return hasModel && (hasInstructions || hasTools);
}

function hasHostedAssistantModelSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(model|model_id|modelId|deployment|deployment_id|deploymentId)$/iu.test(field.path));
}

function hasHostedAssistantInstructionSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(instructions?|system_prompt|systemPrompt|developer_message|developerMessage|prompt)$/iu.test(field.path));
}

function hasHostedAssistantToolNameSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(name|tool_name|toolName|function\.name)$/iu.test(field.path) && /\btools?\b/iu.test(field.path));
}

function countHostedAssistantToolEntries(value: unknown, fields: RuntimeField[]): number {
  const entries = new Set<string>();
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const record = value as Record<string, unknown>;
    for (const key of ["tools", "functions", "capabilities"]) {
      const candidate = record[key];
      if (Array.isArray(candidate)) return candidate.length;
      if (candidate && typeof candidate === "object") return Object.keys(candidate as Record<string, unknown>).length;
    }
  }
  for (const field of fields) {
    const match = field.path.match(/(?:^|\.)(tools?|functions?|capabilities)\.(\d+|[A-Za-z][\w-]*)/u);
    if (match?.[1] && match[2]) entries.add(`${match[1]}.${match[2]}`);
  }
  return entries.size;
}

function collectHostedAssistantToolCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase();
    if (!/\b(tool|tools|function|functions|capability|capabilities|tool_resources|toolresources|code_interpreter|file_search|web_search|computer|mcp)\b/iu.test(text)) {
      continue;
    }
    if (/\b(code[_\s-]?interpreter|python|sandbox|repl|notebook)\b/iu.test(text)) categories.add("code_interpreter");
    if (/\b(file[_\s-]?search|retrieval|vector[_\s-]?store|knowledge[_\s-]?base|documents?)\b/iu.test(text)) categories.add("file_search");
    if (/\b(function|function[_\s-]?call|json[_\s-]?schema|tool[_\s-]?schema)\b/iu.test(text)) categories.add("function_tool");
    if (/\b(mcp|model[_\s-]?context[_\s-]?protocol)\b/iu.test(text)) categories.add("mcp_connector");
    if (/\b(web[_\s-]?search|browser[_\s-]?search|search[_\s-]?the[_\s-]?web)\b/iu.test(text)) categories.add("web_search");
    if (/\b(computer[_\s-]?use|browser|click|form|screen|desktop)\b/iu.test(text)) categories.add("computer_use");
    if (/\b(slack|email|webhook|ticket|jira|zendesk|github|comment|reply|respond|send|post|publish)\b/iu.test(text)) {
      categories.add("external_response");
    }
    if (/\b(database|db|sql|query|support_db|warehouse|crm)\b/iu.test(text)) categories.add("database_access");
    if (/(?:^|[_\W])(vault|secret|secrets|secret[_\s-]?manager|credential|api[_\s-]?key)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/\b(write|update|create|delete|close|assign|escalate|approve|refund|commit|push|merge)\b/iu.test(text)) {
      categories.add("state_write");
    }
    if (/(?:^|[_\W])(memory|remember|persist|store|vector[_\s-]?store)(?:[_\W]|$)/iu.test(text)) categories.add("memory_write");
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function isHostedAssistantPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "code_interpreter",
      "computer_use",
      "database_access",
      "external_response",
      "function_tool",
      "mcp_connector",
      "secret_manager_access",
      "state_write"
    ].includes(category)
  );
}

function countHostedAssistantPrivilegedToolCategories(categories: string[]): number {
  return categories.filter((category) =>
    [
      "code_interpreter",
      "computer_use",
      "database_access",
      "external_response",
      "function_tool",
      "mcp_connector",
      "secret_manager_access",
      "state_write"
    ].includes(category)
  ).length;
}

function hasHostedAssistantExternalToolAuthority(categories: string[]): boolean {
  return categories.some((category) => ["computer_use", "external_response", "mcp_connector", "web_search"].includes(category));
}

function hasHostedAssistantWriteToolAuthority(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) =>
    ["code_interpreter", "computer_use", "database_access", "external_response", "state_write"].includes(category)
  ) || fields.some((field) =>
    /\b(write|update|create|delete|reply|respond|send|post|publish|comment|close|assign|escalate|approve|refund|commit|push|merge)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasHostedAssistantMemoryWriteSignal(fields: RuntimeField[], vectorStoreCount: number): boolean {
  return vectorStoreCount > 0 || fields.some((field) =>
    /(?:^|[_\W])(memory|remember|persist|store|vector[_\s-]?store|thread[_\s-]?state)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasHostedAssistantAutomaticToolChoice(fields: RuntimeField[], categories: string[]): boolean {
  if (categories.length === 0) return false;
  const toolChoiceFields = fields.filter((field) => /(?:^|\.)(tool_choice|toolChoice|tool_selection|toolSelection)(?:\.|$)?/iu.test(field.path));
  if (toolChoiceFields.length === 0) return true;
  if (toolChoiceFields.some((field) => /\b(none|disabled|disable|off|manual|read[_-]?only|read-only)\b/iu.test(fieldValueText(field)))) {
    return false;
  }
  return toolChoiceFields.some((field) => /\b(auto|required|any|automatic|enabled|on|true)\b/iu.test(fieldValueText(field)) || truthyConfigValue(field.value));
}

function hasHostedAssistantParallelToolCalls(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|\.)(parallel_tool_calls|parallelToolCalls|parallel_tools|parallelTools)(?:\.|$)?/iu.test(field.path) &&
    truthyConfigValue(field.value)
  );
}

function hasHostedAssistantToolResourceSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /\b(tool_resources|toolResources|resources|attachments|file_ids|fileIds|vector_store_ids|vectorStoreIds)\b/iu.test(field.path));
}

function countHostedAssistantVectorStoreRefs(fields: RuntimeField[]): number {
  return countHostedAssistantResourceRefs(fields, /vector[_-]?store[_-]?ids?|vectorStoreIds|vector[_-]?stores?|knowledge[_-]?base/iu);
}

function countHostedAssistantFileRefs(fields: RuntimeField[]): number {
  return countHostedAssistantResourceRefs(fields, /file[_-]?ids?|fileIds|attachments?|documents?/iu);
}

function countHostedAssistantResourceRefs(fields: RuntimeField[], pathPattern: RegExp): number {
  const refs = new Set<string>();
  for (const field of fields) {
    if (!pathPattern.test(field.path)) continue;
    if (Array.isArray(field.value)) {
      for (const value of field.value) refs.add(String(value));
      continue;
    }
    if (typeof field.value === "string" || typeof field.value === "number") {
      refs.add(String(field.value));
      continue;
    }
    refs.add(field.path);
  }
  return refs.size;
}

function hasHostedAssistantSensitiveContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|order|record|case|profile|note|incident|file[_\s-]?search|vector[_\s-]?store|knowledge[_\s-]?base)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasHostedAssistantPiiContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date[_\s-]?of[_\s-]?birth|customer[_-]?id|user[_-]?id|account[_-]?id)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasHostedAssistantSecretContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(secret|token|credential|api[_-]?key|password|vault|key[_\s-]?vault|authorization|bearer)\b/iu.test(`${field.path} ${fieldValueText(field)}`)
  );
}

function hasHostedAssistantUntrustedInputSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(untrusted|user|customer|client|ticket|support|issue|comment|message|prompt|retrieved|rag|document|email|chat|inbound|web[_-]?page|browser[_-]?output|tool[_-]?output|external|thread[_\s-]?message)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasHostedAssistantGuardrailsDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = `${field.path} ${fieldValueText(field)}`;
    if (!/\b(guardrail|safety|moderation|validation|sanitize|sanitiz|redaction|prompt[_\s-]?injection|jailbreak)\b/iu.test(text)) {
      return false;
    }
    if (/(^|\.)(enabled|enforced|required|active)$/iu.test(field.path)) return disabledConfigValue(field.value);
    return /\b(disabled|disable|off|none|bypass|skip|raw|passthrough|allow[_\s-]?all|warn[_\s-]?only|monitor[_\s-]?only)\b/iu.test(text);
  });
}

function hasHostedAssistantApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|confirm|confirmation|review|human in the loop|requires action)\b/iu.test(
      field.path.replaceAll("_", " ").replaceAll("-", " ")
    ) && truthyConfigValue(field.value)
  );
}

function isHostedAssistantSecurityField(fieldPath: string): boolean {
  return /provider|assistant|agent|model|deployment|instructions?|prompt|developer|system|tools?|function|code[_-]?interpreter|file[_-]?search|web[_-]?search|computer|mcp|tool[_-]?resources|resources|attachments?|file[_-]?ids?|vector[_-]?store|knowledge|thread|message|input|customer|ticket|email|account|pii|sensitive|secret|token|credential|auth|api[_-]?key|approval|review|tool[_-]?choice|parallel|guardrail|safety|moderation|sanitize|redact|validation|output/iu.test(
    fieldPath
  );
}

function classifyRealtimeAgentSessionConfig(value: unknown, filePath: string): RealtimeAgentSessionPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const provider = inferRealtimeAgentProvider([filePath, ...fields.map((field) => field.path), ...stringValues]);
  const destinations = classifyRealtimeAgentDestinations(fields, provider);
  const toolAuthorityCategories = collectRealtimeAgentToolAuthorityCategories(fields);
  const toolCallsEnabled =
    !hasRealtimeAgentToolCallsDisabledSignal(fields) && (toolAuthorityCategories.length > 0 || hasRealtimeAgentToolCallSignal(fields));
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    realtime_agent_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isRealtimeAgentSecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    realtime_agent_provider: provider,
    realtime_agent_session_detected: hasRealtimeAgentSessionSignal(fields, provider),
    realtime_agent_destination_redacted: destinations.destinationCount > 0,
    realtime_agent_destination_count: destinations.destinationCount,
    realtime_agent_destination_kinds: destinations.destinationKinds,
    realtime_agent_external_caller: hasRealtimeAgentExternalCallerSignal(fields, provider),
    realtime_agent_voice_or_audio_input: hasRealtimeAgentVoiceOrAudioInputSignal(fields, provider),
    realtime_agent_transcript_capture: hasRealtimeAgentTranscriptCaptureSignal(fields),
    realtime_agent_recording_enabled: hasRealtimeAgentRecordingSignal(fields),
    realtime_agent_recording_redaction_disabled: hasRealtimeAgentRecordingRedactionDisabledSignal(fields),
    realtime_agent_transcript_sanitization_disabled: hasRealtimeAgentTranscriptSanitizationDisabledSignal(fields),
    realtime_agent_prompt_injection_filter_disabled: hasRealtimeAgentPromptInjectionFilterDisabledSignal(fields),
    realtime_agent_tool_calls_enabled: toolCallsEnabled,
    realtime_agent_tool_authority_categories: toolAuthorityCategories,
    realtime_agent_privileged_tool_authority: isRealtimeAgentPrivileged(toolAuthorityCategories),
    realtime_agent_write_authority: hasRealtimeAgentWriteAuthoritySignal(fields, toolAuthorityCategories),
    realtime_agent_external_response: hasRealtimeAgentExternalResponseSignal(fields, toolAuthorityCategories),
    realtime_agent_memory_write: hasRealtimeAgentMemoryWriteSignal(fields, toolAuthorityCategories),
    realtime_agent_sensitive_context: hasRealtimeAgentSensitiveContextSignal(fields),
    realtime_agent_pii_context: hasRealtimeAgentPiiContextSignal(fields),
    realtime_agent_secret_exposure: hasRealtimeAgentSecretSignal(fields) || envKeys.some(isCredentialLikeKeyName) || secretRefKeys.length > 0,
    realtime_agent_approval_required: hasRealtimeAgentApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function inferRealtimeAgentProvider(candidates: string[]): string | undefined {
  const text = candidates.join(" ").toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
  const providers: Array<[string, RegExp]> = [
    ["azure_openai_realtime", /\b(azure openai realtime|aoai realtime)\b/iu],
    ["openai_realtime", /\b(openai realtime|realtime api|responses realtime|gpt realtime|openai)\b/iu],
    ["livekit", /\blivekit\b/iu],
    ["twilio", /\btwilio\b/iu],
    ["daily", /\bdaily\.co|daily\b/iu],
    ["webrtc", /\bwebrtc|rtc\b/iu],
    ["websocket", /\bwebsocket|web socket|wss:\/\/|ws:\/\//iu],
    ["sip", /\b(sip|telephony|phone call|voice call)\b/iu]
  ];
  return providers.find(([, pattern]) => pattern.test(text))?.[0];
}

function hasRealtimeAgentSessionSignal(fields: RuntimeField[], provider: string | undefined): boolean {
  if (provider !== undefined) return true;
  return fields.some((field) =>
    /\b(realtime|real\s?time|voice\s?agent|call\s?agent|audio\s?session|streaming\s?agent|webrtc|websocket|livekit|twilio)\b/iu.test(
      realtimeSignalText(field)
    )
  );
}

function classifyRealtimeAgentDestinations(
  fields: RuntimeField[],
  provider: string | undefined
): { destinationCount: number; destinationKinds: string[] } {
  const kinds = new Set<string>();
  const destinations = new Set<string>();
  if (provider) kinds.add(provider.includes("twilio") || provider === "sip" ? "telephony_provider" : "realtime_provider");
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`;
    if (/wss?:\/\//iu.test(text) || /\b(websocket|web[_\s-]?socket)\b/iu.test(text)) kinds.add("websocket_endpoint");
    if (/https?:\/\//iu.test(text) || fieldStringValues(field).some(parseRemoteHttpUrl)) kinds.add("http_realtime_endpoint");
    if (/\b(webrtc|rtc|sdp|ice[_\s-]?server|turn[_\s-]?server|stun)\b/iu.test(text)) kinds.add("webrtc_session");
    if (/\b(twilio|sip|phone|pstn|call[_\s-]?sid|from_number|to_number|caller)\b/iu.test(text)) kinds.add("telephony_provider");
    if (/\b(room|channel|participant|livekit|daily)\b/iu.test(text)) kinds.add("voice_room");
    if (/\+?[0-9][0-9().\-\s]{6,}/u.test(text) && /\b(phone|caller|from|to|number)\b/iu.test(text)) kinds.add("phone_number");
    if (kinds.size > 0 && /url|uri|endpoint|host|room|channel|phone|number|sip|ws|websocket|webrtc|livekit|twilio|daily/iu.test(field.path)) {
      destinations.add(field.path);
    }
  }
  return {
    destinationCount: destinations.size,
    destinationKinds: [...kinds].sort((a, b) => a.localeCompare(b))
  };
}

function hasRealtimeAgentExternalCallerSignal(fields: RuntimeField[], provider: string | undefined): boolean {
  if (provider && ["daily", "livekit", "sip", "twilio"].includes(provider)) return true;
  return fields.some((field) =>
    !hasRealtimeInternalOnlyCallerSignal(field) &&
    /\b(external|public|anonymous|callers?|customer|client|phone|pstn|sip|twilio|inbound\s?call|incoming\s?call|web\s?visitor|participant)\b/iu.test(
      realtimeSignalText(field)
    )
  );
}

function hasRealtimeInternalOnlyCallerSignal(field: RuntimeField): boolean {
  return /\b(internal\s?callers?\s?only|internal\s?only|trusted\s?callers?\s?only|private\s?callers?\s?only)\b/iu.test(
    realtimeSignalText(field)
  ) && truthyConfigValue(field.value);
}

function hasRealtimeAgentVoiceOrAudioInputSignal(fields: RuntimeField[], provider: string | undefined): boolean {
  if (provider && ["daily", "livekit", "openai_realtime", "sip", "twilio", "webrtc"].includes(provider)) return true;
  return fields.some((field) =>
    /\b(voice|audio|microphone|mic|call|phone|speech|transcription|transcribe|realtime|webrtc|websocket|streaming)\b/iu.test(
      realtimeSignalText(field)
    )
  );
}

function hasRealtimeAgentTranscriptCaptureSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(transcript|transcription|caption|conversation\s?log|call\s?log|summary)\b/iu.test(realtimeSignalText(field)) &&
    truthyConfigValue(field.value)
  );
}

function hasRealtimeAgentRecordingSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(recording|record\s?audio|record\s?call|audio\s?archive|store\s?audio)\b/iu.test(realtimeSignalText(field)) &&
    truthyConfigValue(field.value)
  );
}

function hasRealtimeAgentRecordingRedactionDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = realtimeSignalText(field);
    return /\b(recording|audio|call)\b/iu.test(text) && /\b(redact|mask|sanitize|scrub|retention|privacy)\b/iu.test(text) && disabledConfigValue(field.value);
  });
}

function hasRealtimeAgentTranscriptSanitizationDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = realtimeSignalText(field);
    return /\b(transcript|transcription|conversation|captions?)\b/iu.test(text) && /\b(sanitize|sanitiz|redact|mask|filter|scrub)\b/iu.test(text) && disabledConfigValue(field.value);
  });
}

function hasRealtimeAgentPromptInjectionFilterDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = realtimeSignalText(field);
    if (!/\b(prompt\s+injection|jailbreak|instruction\s+override|safety|guardrail)\b/iu.test(text)) return false;
    if (/(^|\.)(enabled|enforced|required|active)$/iu.test(field.path)) return disabledConfigValue(field.value);
    return /\b(disabled|disable|off|none|bypass|skip|raw|passthrough|allow\s+all|monitor\s+only)\b/iu.test(text);
  });
}

function realtimeSignalText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.replaceAll("_", " ").replaceAll("-", " ");
}

function collectRealtimeAgentToolAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = realtimeSignalText(field).toLowerCase();
    if (/\b(tool|tools|function|function call|mcp|capability|action)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(database|db|sql|query|crm|support\s?db|warehouse)\b/iu.test(text)) categories.add("database_access");
    if (/\b(slack|email|sms|message|webhook|ticket|jira|zendesk|reply|respond|send|post|publish)\b/iu.test(text)) {
      categories.add("external_response");
    }
    if (/\b(browser|computer\s?use|click|form|navigate|screen)\b/iu.test(text)) categories.add("browser_action");
    if (/(?:^|[_\W])(vault|secret|secrets|secret\s?manager|credential|api\s?key)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/(?:^|[_\W])(memory|remember|persist|store|conversation\s?state|call\s?summary)(?:[_\W]|$)/iu.test(text)) {
      categories.add("memory_write");
    }
    if (/\b(write|update|create|delete|close|assign|escalate|approve|refund|commit|push|merge)\b/iu.test(text)) {
      categories.add("state_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasRealtimeAgentToolCallSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(tool\s?calls?|function\s?calls?|call\s?tools?|mcp|actions?|capabilities|tool\s?choice)\b/iu.test(realtimeSignalText(field)) &&
    truthyConfigValue(field.value)
  );
}

function hasRealtimeAgentToolCallsDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = realtimeSignalText(field);
    const fieldPath = field.path.replaceAll("_", " ").replaceAll("-", " ");
    if (!/\b(tool|tools|tool choice|function call|mcp|actions|capabilities)\b/iu.test(text)) return false;
    if (/\b(tool choice|mode|enabled|allow|allowed|auto|automatic)\b/iu.test(fieldPath)) {
      return disabledConfigValue(field.value);
    }
    return /\b(no tools|tool choice none|tools disabled|disable tools|read only tools|readonly tools)\b/iu.test(text);
  });
}

function isRealtimeAgentPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    ["browser_action", "database_access", "external_response", "secret_manager_access", "state_write", "tool_call"].includes(category)
  );
}

function hasRealtimeAgentWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) => ["database_access", "external_response", "state_write"].includes(category)) ||
    fields.some((field) =>
      /\b(write|update|create|delete|reply|respond|send|post|publish|comment|close|assign|escalate|approve|refund)\b/iu.test(
        realtimeSignalText(field)
      )
    );
}

function hasRealtimeAgentExternalResponseSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) => /\b(reply|respond|send|post|publish|comment|email|slack|sms|message|webhook)\b/iu.test(realtimeSignalText(field)));
}

function hasRealtimeAgentMemoryWriteSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("memory_write") ||
    fields.some((field) =>
      /(?:^|[_\W])(memory|remember|persist|store|conversation\s?state|call\s?summary|transcript\s?store)(?:[_\W]|$)/iu.test(
        realtimeSignalText(field)
      )
    );
}

function hasRealtimeAgentSensitiveContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|order|record|case|profile|note|incident|transcript|recording)\b/iu.test(
      realtimeSignalText(field)
    )
  );
}

function hasRealtimeAgentPiiContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|caller|address|ssn|passport|dob|date\s?of\s?birth|customer\s?id|user\s?id|account\s?id)(?:[_\W]|$)/iu.test(
      realtimeSignalText(field)
    )
  );
}

function hasRealtimeAgentSecretSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(secret|token|credential|api\s?key|password|vault|key\s?vault|authorization|bearer|twilio\s?auth)\b/iu.test(
      realtimeSignalText(field)
    )
  );
}

function hasRealtimeAgentApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|confirm|confirmation|review|human in the loop|requires action)\b/iu.test(
      field.path.replaceAll("_", " ").replaceAll("-", " ")
    ) && truthyConfigValue(field.value)
  );
}

function isRealtimeAgentSecurityField(fieldPath: string): boolean {
  return /provider|realtime|real[_-]?time|voice|audio|call|phone|caller|participant|room|channel|session|stream|websocket|webrtc|twilio|livekit|daily|sip|transcript|recording|conversation|input|message|customer|ticket|email|account|pii|sensitive|secret|token|credential|auth|api[_-]?key|tools?|function|mcp|action|database|browser|memory|reply|respond|send|write|approval|review|guardrail|safety|prompt[_-]?injection|sanitize|redact|filter|moderation/iu.test(
    fieldPath
  );
}

function classifyAgentOrchestrationConfig(value: unknown, filePath: string): AgentOrchestrationPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const framework = inferAgentOrchestrationFramework([filePath, ...fields.map((field) => field.path), ...stringValues]);
  const agentCount = countConfiguredAgents(value, fields);
  const delegationCategories = collectAgentOrchestrationDelegationCategories(fields);
  const toolAuthorityCategories = collectAgentOrchestrationToolAuthorityCategories(fields);
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    agent_orchestration_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isAgentOrchestrationSecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    agent_orchestration_framework: framework,
    agent_orchestration_multi_agent: agentCount >= 2 || hasMultiAgentSignal(fields),
    agent_orchestration_agent_count: agentCount,
    agent_orchestration_agent_names_redacted: agentCount > 0 || hasAgentNameSignal(fields),
    agent_orchestration_delegation_enabled: delegationCategories.length > 0,
    agent_orchestration_delegation_categories: delegationCategories,
    agent_orchestration_untrusted_input: hasAgentOrchestrationUntrustedInputSignal(fields),
    agent_orchestration_shared_memory: hasAgentOrchestrationSharedMemorySignal(fields),
    agent_orchestration_memory_redacted: hasAgentOrchestrationMemoryReferenceSignal(fields),
    agent_orchestration_invokes_tools: toolAuthorityCategories.length > 0 || hasAgentOrchestrationToolSignal(fields),
    agent_orchestration_tool_authority_categories: toolAuthorityCategories,
    agent_orchestration_privileged_agent: isAgentOrchestrationPrivileged(toolAuthorityCategories),
    agent_orchestration_write_authority: hasAgentOrchestrationWriteAuthoritySignal(fields, toolAuthorityCategories),
    agent_orchestration_external_authority: hasAgentOrchestrationExternalAuthoritySignal(fields, toolAuthorityCategories),
    agent_orchestration_secret_authority: toolAuthorityCategories.includes("secret_manager_access") || hasAgentOrchestrationSecretSignal(fields),
    agent_orchestration_sensitive_data: hasAgentOrchestrationSensitiveDataSignal(fields),
    agent_orchestration_pii_data: hasAgentOrchestrationPiiDataSignal(fields),
    agent_orchestration_approval_required: hasAgentOrchestrationApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function inferAgentOrchestrationFramework(candidates: string[]): string | undefined {
  const text = candidates.join(" ").toLowerCase();
  const frameworks: Array<[string, RegExp]> = [
    ["crewai", /\b(crewai|crew ai|crew)\b/iu],
    ["autogen", /\b(autogen|auto gen|autogenstudio)\b/iu],
    ["langgraph", /\blanggraph\b/iu],
    ["semantic_kernel", /\b(semantic[-_\s]?kernel|sk[-_\s]?agent)\b/iu],
    ["openai_swarm", /\bswarm\b/iu],
    ["langchain_agents", /\b(langchain|agentexecutor|agent executor)\b/iu]
  ];
  return frameworks.find(([, pattern]) => pattern.test(text))?.[0];
}

function countConfiguredAgents(value: unknown, fields: RuntimeField[]): number {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const record = value as Record<string, unknown>;
    for (const key of ["agents", "workers", "subagents", "team", "crew", "roles", "nodes"]) {
      const candidate = record[key];
      if (Array.isArray(candidate)) return candidate.length;
      if (candidate && typeof candidate === "object") return Object.keys(candidate as Record<string, unknown>).length;
    }
  }

  const pathPrefixes = new Set<string>();
  for (const field of fields) {
    const match = field.path.match(/(?:^|\.)(agents?|workers?|subagents?|team|crew|roles?|nodes?)\.(\d+|[A-Za-z][\w-]*)/u);
    if (match?.[1] && match[2]) pathPrefixes.add(`${match[1]}.${match[2]}`);
  }
  return pathPrefixes.size;
}

function hasMultiAgentSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(multi[-_\s]?agent|crew|team|subagent|worker|supervisor|manager|router|orchestrator)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentNameSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(agents?|workers?|subagents?|team|crew|roles?|nodes?)\.[^.]+\.name$/iu.test(field.path));
}

function collectAgentOrchestrationDelegationCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase();
    if (/\b(delegate|delegation|can[_\s-]?delegate|handoff|hand[-_\s]?off|transfer)\b/iu.test(text)) categories.add("agent_delegation");
    if (/\b(supervisor|manager|router|planner|coordinator|orchestrator)\b/iu.test(text)) categories.add("supervisor_routing");
    if (/\b(peer|worker|subagent|specialist|role)\b/iu.test(text)) categories.add("peer_handoff");
    if (/\b(auto|automatic|without[_\s-]?approval|no[_\s-]?approval|autonomous)\b/iu.test(text)) categories.add("automatic_delegation");
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasAgentOrchestrationUntrustedInputSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(untrusted|user|customer|client|ticket|support|issue|comment|message|prompt|retrieved|rag|document|email|chat|inbound|web[_-]?page|external)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentOrchestrationSharedMemorySignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(shared[_\s-]?memory|memory[_\s-]?shared|team[_\s-]?memory|crew[_\s-]?memory|cross[-_\s]?agent|global[_\s-]?memory|persistent[_\s-]?memory)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    ) || (/memory/iu.test(field.path) && truthyConfigValue(field.value))
  );
}

function hasAgentOrchestrationMemoryReferenceSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(memory|vector|state|scratchpad|transcript|summary|session|history|store|namespace)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function collectAgentOrchestrationToolAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase();
    if (/\b(tool|tools|function|mcp|connector|capability)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(browser|playwright|puppeteer|web[_\s-]?agent|click|form|navigate)\b/iu.test(text)) categories.add("browser_action");
    if (/\b(database|db|sql|query|support_db|warehouse)\b/iu.test(text)) categories.add("database_access");
    if (/(?:^|[_\W])(vault|secret|secrets|secret[_\s-]?manager|key[_\s-]?vault|credential)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/\b(slack|email|webhook|message|ticket|issue|comment|reply|send|post|publish)\b/iu.test(text)) categories.add("external_response");
    if (/(?:^|[_\W])(memory|remember|store|persist|session[_\s-]?state)(?:[_\W]|$)/iu.test(text)) categories.add("memory_write");
    if (/\b(shell|bash|command|exec|terminal|python|node|subprocess)\b/iu.test(text)) categories.add("shell_execution");
    if (/\b(filesystem|file[_\s-]?write|workspace|repo|repository|github|gitlab|pull[_\s-]?request)\b/iu.test(text)) {
      categories.add("repo_or_filesystem_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasAgentOrchestrationToolSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(call[_\s-]?tools?|invoke[_\s-]?tools?|tool[_\s-]?access|mcp|function[_\s-]?call|browser|database|vault|shell)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function isAgentOrchestrationPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "browser_action",
      "database_access",
      "external_response",
      "repo_or_filesystem_write",
      "secret_manager_access",
      "shell_execution",
      "tool_call"
    ].includes(category)
  );
}

function hasAgentOrchestrationWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) => ["database_access", "external_response", "repo_or_filesystem_write", "shell_execution"].includes(category)) ||
    fields.some((field) =>
      /\b(write|update|create|delete|reply|respond|send|post|publish|comment|commit|push|merge|deploy|remember|persist)\b/iu.test(
        `${field.path} ${fieldValueText(field)}`
      )
    );
}

function hasAgentOrchestrationExternalAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) => /\b(slack|email|webhook|send|post|publish|reply|respond|ticket|issue|external)\b/iu.test(`${field.path} ${fieldValueText(field)}`));
}

function hasAgentOrchestrationSecretSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /\b(secret|token|credential|api[_-]?key|password|vault|key[_\s-]?vault)\b/iu.test(`${field.path} ${fieldValueText(field)}`));
}

function hasAgentOrchestrationSensitiveDataSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|order|record|case|profile|note|incident)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentOrchestrationPiiDataSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date[_\s-]?of[_\s-]?birth|customer[_-]?id|user[_-]?id|account[_-]?id)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentOrchestrationApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /approval|required[_-]?approval|human[_-]?approval|confirm|confirmation|review|human[_-]?in[_-]?the[_-]?loop/iu.test(field.path) &&
    truthyConfigValue(field.value)
  );
}

function isAgentOrchestrationSecurityField(fieldPath: string): boolean {
  return /framework|provider|agent|agents|subagent|crew|team|worker|role|task|graph|node|edge|handoff|delegate|delegation|supervisor|manager|router|tool|mcp|browser|database|secret|memory|input|source|customer|ticket|email|chat|write|send|reply|approval|auth|token|credential|env|scope|permission|state|vector|namespace/iu.test(
    fieldPath
  );
}

function classifyAgentAutonomousLoopConfig(value: unknown, filePath: string): AgentAutonomousLoopPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const goalSourceCategories = collectAgentAutonomousLoopGoalSourceCategories(fields);
  const toolAuthorityCategories = collectAgentAutonomousLoopToolAuthorityCategories(fields);
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    agent_autonomous_loop_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isAgentAutonomousLoopSecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    agent_autonomous_loop_enabled: hasAgentAutonomousLoopEnabledSignal(fields) || hasAgentAutonomousLoopModeSignal(fields),
    agent_autonomous_loop_autonomous_mode: hasAgentAutonomousLoopModeSignal(fields),
    agent_autonomous_loop_loop_enabled: hasAgentAutonomousLoopLoopSignal(fields),
    agent_autonomous_loop_auto_execute: hasAgentAutonomousLoopAutoExecuteSignal(fields),
    agent_autonomous_loop_goal_source_redacted: goalSourceCategories.length > 0,
    agent_autonomous_loop_goal_source_categories: goalSourceCategories,
    agent_autonomous_loop_untrusted_goal: hasAgentAutonomousLoopUntrustedGoalSignal(fields) || goalSourceCategories.some((category) =>
      ["customer_goal", "external_message", "retrieved_context", "untrusted_prompt"].includes(category)
    ),
    agent_autonomous_loop_tool_authority_categories: toolAuthorityCategories,
    agent_autonomous_loop_privileged_tool_authority: isAgentAutonomousLoopPrivileged(toolAuthorityCategories),
    agent_autonomous_loop_write_authority: hasAgentAutonomousLoopWriteAuthoritySignal(fields, toolAuthorityCategories),
    agent_autonomous_loop_external_authority: hasAgentAutonomousLoopExternalAuthoritySignal(fields, toolAuthorityCategories),
    agent_autonomous_loop_secret_authority:
      toolAuthorityCategories.includes("secret_manager_access") ||
      hasAgentAutonomousLoopSecretSignal(fields) ||
      envKeys.some(isCredentialLikeKeyName) ||
      secretRefKeys.length > 0,
    agent_autonomous_loop_shell_authority: toolAuthorityCategories.includes("shell_execution"),
    agent_autonomous_loop_memory_feedback: hasAgentAutonomousLoopMemoryFeedbackSignal(fields, toolAuthorityCategories),
    agent_autonomous_loop_tool_output_feedback: hasAgentAutonomousLoopToolOutputFeedbackSignal(fields),
    agent_autonomous_loop_unbounded_iterations: hasAgentAutonomousLoopUnboundedIterationSignal(fields),
    agent_autonomous_loop_iteration_limit_redacted: hasAgentAutonomousLoopIterationLimitSignal(fields),
    agent_autonomous_loop_iteration_limit_high: hasAgentAutonomousLoopHighIterationLimitSignal(fields),
    agent_autonomous_loop_runtime_budget_missing: hasAgentAutonomousLoopRuntimeBudgetMissingSignal(fields),
    agent_autonomous_loop_stop_condition_missing: hasAgentAutonomousLoopStopConditionMissingSignal(fields),
    agent_autonomous_loop_kill_switch_disabled: hasAgentAutonomousLoopKillSwitchDisabledSignal(fields),
    agent_autonomous_loop_dry_run_disabled: hasAgentAutonomousLoopDryRunDisabledSignal(fields),
    agent_autonomous_loop_sensitive_context: hasAgentAutonomousLoopSensitiveContextSignal(fields),
    agent_autonomous_loop_pii_context: hasAgentAutonomousLoopPiiContextSignal(fields),
    agent_autonomous_loop_approval_required: hasAgentAutonomousLoopApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function collectAgentAutonomousLoopGoalSourceCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (isAgentAutonomousLoopControlField(field.path)) continue;
    const text = agentAutonomousLoopText(field);
    if (!/\b(goal|objective|task|request|source|input|prompt|message|ticket|issue|comment|event|selector)\b/iu.test(text)) continue;
    if (/\b(customer|client|support|ticket|case|account|portal)\b/iu.test(text)) categories.add("customer_goal");
    if (/\b(email|slack|chat|message|webhook|github|issue|pull request|comment|external|public)\b/iu.test(text)) {
      categories.add("external_message");
    }
    if (/\b(retrieved|retrieval|rag|document|browser|web page|tool output|tool result)\b/iu.test(text)) {
      categories.add("retrieved_context");
    }
    if (/\b(untrusted|user prompt|prompt|freeform|natural language|model selected)\b/iu.test(text)) {
      categories.add("untrusted_prompt");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function collectAgentAutonomousLoopToolAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (isAgentAutonomousLoopControlField(field.path)) continue;
    if (disabledConfigValue(field.value)) continue;
    const text = agentAutonomousLoopText(field);
    if (!/\b(tool|tools|function|mcp|capability|action|command|executor|remediation|browser|database|vault|slack|email|shell|filesystem|memory)\b/iu.test(text)) {
      continue;
    }
    if (/\b(tool|tools|function|mcp|capability|action|executor)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(database|db|sql|query|crm|support db|warehouse|record)\b/iu.test(text)) categories.add("database_write");
    if (/\b(slack|email|sms|message|webhook|ticket|jira|zendesk|reply|respond|send|post|publish)\b/iu.test(text)) {
      categories.add("external_response");
    }
    if (/\b(browser|playwright|puppeteer|click|form|navigate|refund form)\b/iu.test(text)) categories.add("browser_action");
    if (/(?:^|[_\W])(vault|secret|secrets|secret manager|key vault|credential|api key)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/(?:^|[_\W])(memory|remember|store|persist|session state|scratchpad)(?:[_\W]|$)/iu.test(text)) {
      categories.add("memory_write");
    }
    if (/\b(shell|bash|command|exec|terminal|python|node|subprocess)\b/iu.test(text)) categories.add("shell_execution");
    if (/\b(filesystem|file write|workspace|repo|repository|github|gitlab|commit|push|merge)\b/iu.test(text)) {
      categories.add("repo_or_filesystem_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasAgentAutonomousLoopEnabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|\.)(enabled|active|autonomy|autonomous|agent_loop|control_loop)(?:\.|$)/iu.test(field.path) &&
    truthyConfigValue(field.value)
  );
}

function hasAgentAutonomousLoopModeSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(autonomous|autonomy|self directed|self-directed|agent loop|control loop|planner executor|autopilot)\b/iu.test(
      agentAutonomousLoopText(field)
    ) && truthyConfigValue(field.value)
  );
}

function hasAgentAutonomousLoopLoopSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(loop|while|iterate|iterations|planner loop|execution loop|control loop|run until done|continue until)\b/iu.test(
      agentAutonomousLoopText(field)
    ) && truthyConfigValue(field.value)
  );
}

function hasAgentAutonomousLoopAutoExecuteSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = agentAutonomousLoopText(field);
    if (/\b(manual|dry run|approval required|human review|disabled|off)\b/iu.test(text)) return false;
    if (/(^|\.)(auto_execute|autoExecute|execute|execution|invoke|run|apply|remediate|auto_approve|autoApprove)$/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(auto execute|auto-execute|execute automatically|autonomous execution|run tools automatically|apply automatically|auto remediate|autopilot)\b/iu.test(
      text
    );
  });
}

function hasAgentAutonomousLoopUntrustedGoalSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    !isAgentAutonomousLoopControlField(field.path) &&
    /\b(untrusted|user|customer|client|ticket|support|issue|comment|message|prompt|retrieved|rag|document|email|chat|webhook|external|public|browser|tool output|model selected)\b/iu.test(
      agentAutonomousLoopText(field)
    ) && truthyConfigValue(field.value)
  );
}

function isAgentAutonomousLoopPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "browser_action",
      "database_write",
      "external_response",
      "repo_or_filesystem_write",
      "secret_manager_access",
      "shell_execution"
    ].includes(category)
  );
}

function hasAgentAutonomousLoopWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) =>
    ["database_write", "external_response", "repo_or_filesystem_write", "shell_execution"].includes(category)
  ) || fields.some((field) =>
    !isAgentAutonomousLoopControlField(field.path) &&
    /\b(write|update|create|delete|reply|respond|send|post|publish|comment|commit|push|merge|deploy|refund|remediate|apply)\b/iu.test(
      agentAutonomousLoopText(field)
    )
  );
}

function hasAgentAutonomousLoopExternalAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) =>
      !isAgentAutonomousLoopControlField(field.path) &&
      /\b(slack|email|webhook|send|post|publish|reply|respond|ticket|issue|external|sms)\b/iu.test(agentAutonomousLoopText(field))
    );
}

function hasAgentAutonomousLoopSecretSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    !isAgentAutonomousLoopControlField(field.path) &&
    /\b(secret|token|credential|api key|password|vault|key vault|authorization|bearer)\b/iu.test(agentAutonomousLoopText(field))
  );
}

function hasAgentAutonomousLoopMemoryFeedbackSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("memory_write") ||
    fields.some((field) =>
      /\b(memory|remember|persist|hydrate|scratchpad|conversation state|long term|long-term|feedback memory)\b/iu.test(
        agentAutonomousLoopText(field)
      ) && truthyConfigValue(field.value)
    );
}

function hasAgentAutonomousLoopToolOutputFeedbackSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(tool output|tool result|observation|reflect|reflection|self critique|self-critique|feedback|next action|previous result)\b/iu.test(
      agentAutonomousLoopText(field)
    ) && truthyConfigValue(field.value)
  );
}

function hasAgentAutonomousLoopUnboundedIterationSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = agentAutonomousLoopText(field);
    if (!/\b(iteration|iterations|steps|turns|loops|max|limit|budget|until done|unlimited|infinite|none|zero)\b/iu.test(text)) return false;
    if (typeof field.value === "number") return field.value === 0 || field.value > 25;
    if (typeof field.value === "string") return /\b(unlimited|infinite|none|no limit|unbounded|until done|0)\b/iu.test(field.value);
    return /\b(unlimited|infinite|no limit|unbounded|run until done|continue until done)\b/iu.test(text) && truthyConfigValue(field.value);
  });
}

function hasAgentAutonomousLoopIterationLimitSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /\b(max iterations|max steps|max turns|iteration limit|step budget|tool budget)\b/iu.test(agentAutonomousLoopText(field)));
}

function hasAgentAutonomousLoopHighIterationLimitSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    if (!/\b(max iterations|max steps|max turns|iteration limit|step budget|tool budget)\b/iu.test(agentAutonomousLoopText(field))) {
      return false;
    }
    const numeric = Number(field.value);
    return Number.isFinite(numeric) && numeric > 25;
  });
}

function hasAgentAutonomousLoopRuntimeBudgetMissingSignal(fields: RuntimeField[]): boolean {
  const budgetFields = fields.filter((field) =>
    /\b(timeout|max runtime|runtime budget|time budget|cost budget|token budget|tool budget|step budget|budget required|budget_required)\b/iu.test(
      agentAutonomousLoopText(field)
    )
  );
  if (budgetFields.length === 0) return true;
  return budgetFields.some((field) => disabledConfigValue(field.value) || /\b(none|disabled|off|unlimited|no budget|0)\b/iu.test(agentAutonomousLoopText(field)));
}

function hasAgentAutonomousLoopStopConditionMissingSignal(fields: RuntimeField[]): boolean {
  const stopFields = fields.filter((field) =>
    /\b(stop condition|stop_condition|stop conditions|stop_conditions|termination|exit criteria|halt|done criteria)\b/iu.test(
      agentAutonomousLoopText(field)
    )
  );
  if (stopFields.length === 0) return true;
  return stopFields.some((field) => disabledConfigValue(field.value) || /\b(none|disabled|off|never|until done|model decides)\b/iu.test(agentAutonomousLoopText(field)));
}

function hasAgentAutonomousLoopKillSwitchDisabledSignal(fields: RuntimeField[]): boolean {
  const killSwitchFields = fields.filter((field) =>
    /\b(kill switch|kill_switch|emergency stop|emergency_stop|circuit breaker|circuit_breaker|abort|cancel|halt)\b/iu.test(
      agentAutonomousLoopText(field)
    )
  );
  if (killSwitchFields.length === 0) return true;
  return killSwitchFields.some((field) => disabledConfigValue(field.value) || /\b(disabled|off|false|none|no kill switch|no circuit breaker)\b/iu.test(agentAutonomousLoopText(field)));
}

function hasAgentAutonomousLoopDryRunDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(dry run|dry_run|preview only|preview_only|simulate|simulation)\b/iu.test(agentAutonomousLoopText(field)) &&
    disabledConfigValue(field.value)
  );
}

function hasAgentAutonomousLoopSensitiveContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    !isAgentAutonomousLoopControlField(field.path) &&
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|case|record|profile|incident|remediation)\b/iu.test(
      agentAutonomousLoopText(field)
    )
  );
}

function hasAgentAutonomousLoopPiiContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    !isAgentAutonomousLoopControlField(field.path) &&
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date of birth|customer id|user id|account id|account number)(?:[_\W]|$)/iu.test(
      agentAutonomousLoopText(field)
    )
  );
}

function hasAgentAutonomousLoopApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|security review|manual review|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      agentAutonomousLoopText(field)
    ) && truthyConfigValue(field.value)
  );
}

function isAgentAutonomousLoopControlField(fieldPath: string): boolean {
  return /(?:^|\.)(deny|denied|block|blocked|exclude|excludes|redact|redaction|mask|sanitize|allowlist|trusted_goals|trusted_sources|approval|human_review|kill_switch|circuit_breaker|dry_run|stop_conditions?|termination|budget|max_iterations|max_steps|max_runtime)(?:\.|$)/iu.test(
    fieldPath
  );
}

function isAgentAutonomousLoopSecurityField(fieldPath: string): boolean {
  return /enabled|autonom|loop|planner|executor|runner|control|goal|objective|task|source|input|prompt|message|ticket|issue|comment|external|customer|retriev|rag|browser|tool|function|mcp|capability|database|db|slack|email|webhook|vault|secret|credential|token|auth|env|shell|command|filesystem|repo|memory|scratchpad|reflect|feedback|iteration|steps|turns|budget|runtime|timeout|stop|termination|kill|circuit|dry|approval|review|pii|sensitive|confidential/iu.test(
    fieldPath
  );
}

function agentAutonomousLoopText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function classifyAgentSafetyConfig(value: unknown, filePath: string): AgentSafetyPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const framework = inferAgentSafetyFramework([filePath, ...fields.map((field) => field.path), ...stringValues]);
  const disabledControls = collectAgentSafetyDisabledControls(fields);
  const failOpenCategories = collectAgentSafetyFailOpenCategories(fields);
  const modelOnlyCategories = collectAgentSafetyModelOnlyCategories(fields);
  const toolAuthorityCategories = collectAgentSafetyToolAuthorityCategories(fields);
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    agent_safety_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isAgentSafetySecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    agent_safety_framework: framework,
    agent_safety_controls_declared: disabledControls.length > 0 || hasAgentSafetyControlSignal(fields),
    agent_safety_controls_disabled: disabledControls.length > 0,
    agent_safety_disabled_controls: disabledControls,
    agent_safety_prompt_injection_filter_disabled: disabledControls.includes("prompt_injection_filter"),
    agent_safety_output_validation_disabled: disabledControls.includes("output_validation"),
    agent_safety_tool_result_sanitization_disabled: disabledControls.includes("tool_result_sanitization"),
    agent_safety_content_moderation_disabled: disabledControls.includes("content_moderation"),
    agent_safety_pii_redaction_disabled: disabledControls.includes("pii_redaction"),
    agent_safety_secret_redaction_disabled: disabledControls.includes("secret_redaction"),
    agent_safety_fail_open: failOpenCategories.length > 0,
    agent_safety_fail_open_categories: failOpenCategories,
    agent_safety_default_allow: failOpenCategories.includes("default_allow"),
    agent_safety_timeout_allows: failOpenCategories.includes("timeout_allow"),
    agent_safety_error_allows: failOpenCategories.includes("error_allow"),
    agent_safety_monitor_only: failOpenCategories.includes("monitor_only"),
    agent_safety_model_only_enforcement: modelOnlyCategories.length > 0,
    agent_safety_model_only_categories: modelOnlyCategories,
    agent_safety_pre_tool_enforcement_missing: hasAgentSafetyPreToolEnforcementMissingSignal(fields),
    agent_safety_deterministic_policy_missing: hasAgentSafetyDeterministicPolicyMissingSignal(fields),
    agent_safety_post_hoc_only: hasAgentSafetyPostHocOnlySignal(fields),
    agent_safety_untrusted_input: hasAgentSafetyUntrustedInputSignal(fields),
    agent_safety_privileged_tool_authority: isAgentSafetyPrivileged(toolAuthorityCategories) || hasAgentSafetyToolAuthoritySignal(fields),
    agent_safety_tool_authority_categories: toolAuthorityCategories,
    agent_safety_write_authority: hasAgentSafetyWriteAuthoritySignal(fields, toolAuthorityCategories),
    agent_safety_external_authority: hasAgentSafetyExternalAuthoritySignal(fields, toolAuthorityCategories),
    agent_safety_memory_write_authority: hasAgentSafetyMemoryWriteSignal(fields, toolAuthorityCategories),
    agent_safety_secret_exposure:
      toolAuthorityCategories.includes("secret_manager_access") ||
      hasAgentSafetySecretSignal(fields) ||
      envKeys.some(isCredentialLikeKeyName) ||
      secretRefKeys.length > 0,
    agent_safety_sensitive_data: hasAgentSafetySensitiveDataSignal(fields),
    agent_safety_pii_data: hasAgentSafetyPiiDataSignal(fields),
    agent_safety_approval_required: hasAgentSafetyApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function inferAgentSafetyFramework(candidates: string[]): string | undefined {
  const text = candidates.join(" ").toLowerCase();
  const frameworks: Array<[string, RegExp]> = [
    ["nemo_guardrails", /\b(nemo[-_\s]?guardrails?|guardrails?\.ai)\b/iu],
    ["langchain", /\blangchain\b/iu],
    ["llamaindex", /\b(llama[-_\s]?index|llamaindex)\b/iu],
    ["openai", /\bopenai\b/iu],
    ["anthropic", /\banthropic\b/iu],
    ["pydantic_ai", /\bpydantic[-_\s]?ai\b/iu]
  ];
  return frameworks.find(([, pattern]) => pattern.test(text))?.[0];
}

function collectAgentSafetyDisabledControls(fields: RuntimeField[]): string[] {
  const controls = new Set<string>();
  for (const field of fields) {
    if (isAgentSafetyGlobalDisabledSignal(field)) controls.add("all_controls");
    if (isAgentSafetyControlDisabled(field, /prompt[_\s-]?injection|injection[_\s-]?filter|jailbreak|instruction[_\s-]?override/iu)) {
      controls.add("prompt_injection_filter");
    }
    if (isAgentSafetyControlDisabled(field, /output[_\s-]?validation|response[_\s-]?validation|schema[_\s-]?validation|validator/iu)) {
      controls.add("output_validation");
    }
    if (isAgentSafetyControlDisabled(field, /tool[_\s-]?(result|output|response)|function[_\s-]?(result|output|response)|observation|sanitize|sanitiz/iu)) {
      controls.add("tool_result_sanitization");
    }
    if (isAgentSafetyControlDisabled(field, /content[_\s-]?moderation|moderation|harm[_\s-]?filter|unsafe[_\s-]?content|content[_\s-]?filter/iu)) {
      controls.add("content_moderation");
    }
    if (isAgentSafetyControlDisabled(field, /pii|personal[_\s-]?data|email|phone|ssn|privacy|redact|mask/iu)) {
      controls.add("pii_redaction");
    }
    if (isAgentSafetyControlDisabled(field, /secret|token|credential|api[_\s-]?key|password|redact|mask|scrub/iu)) {
      controls.add("secret_redaction");
    }
  }
  return [...controls].sort((a, b) => a.localeCompare(b));
}

function collectAgentSafetyFailOpenCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (isAgentSafetyDefaultAllowSignal(field)) categories.add("default_allow");
    if (isAgentSafetyTimeoutAllowSignal(field)) categories.add("timeout_allow");
    if (isAgentSafetyErrorAllowSignal(field)) categories.add("error_allow");
    if (isAgentSafetyMonitorOnlySignal(field)) categories.add("monitor_only");
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function collectAgentSafetyModelOnlyCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = agentSafetySignalText(field);
    if (
      /\b(prompt only|prompt-only|system prompt|developer prompt|instruction only|instruction-only|policy prompt)\b/iu.test(text) &&
      truthyConfigValue(field.value)
    ) {
      categories.add("prompt_only_policy");
    }
    if (
      /\b(llm judge|llm-as-judge|model judge|model reviewer|ai reviewer|classifier model|policy model)\b/iu.test(text) &&
      truthyConfigValue(field.value)
    ) {
      categories.add("llm_judge");
    }
    if (
      /\b(self review|self-review|self critique|self-critique|ask the model|model decides|assistant decides|same model)\b/iu.test(text) &&
      truthyConfigValue(field.value)
    ) {
      categories.add("self_review");
    }
    if (
      /\b(post hoc|post-hoc|after tool|after-tool|after execution|after-execution|review after|audit after)\b/iu.test(text) &&
      truthyConfigValue(field.value)
    ) {
      categories.add("post_hoc_review");
    }
    if (hasAgentSafetyPreToolEnforcementMissingSignal([field])) categories.add("pre_tool_enforcement_missing");
    if (hasAgentSafetyDeterministicPolicyMissingSignal([field])) categories.add("deterministic_policy_missing");
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasAgentSafetyPreToolEnforcementMissingSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = agentSafetySignalText(field);
    if (!/\b(pre tool|pre-tool|before tool|before-tool|pre execution|pre-execution|before execution|tool gate|enforcement)\b/iu.test(text)) {
      return false;
    }
    return disabledConfigValue(field.value) || /\b(disabled|off|false|none|missing|not required|not enforced|post hoc|after execution)\b/iu.test(text);
  });
}

function hasAgentSafetyDeterministicPolicyMissingSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = agentSafetySignalText(field);
    if (!/\b(deterministic|schema|allowlist|denylist|policy engine|rule engine|non model|non-model|code enforced|code-enforced)\b/iu.test(text)) {
      return false;
    }
    return disabledConfigValue(field.value) || /\b(disabled|off|false|none|missing|not required|not enforced|model only|prompt only)\b/iu.test(text);
  });
}

function hasAgentSafetyPostHocOnlySignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = agentSafetySignalText(field);
    if (!/\b(post hoc|post-hoc|after tool|after-tool|after execution|after-execution|review after|audit after)\b/iu.test(text)) {
      return false;
    }
    return truthyConfigValue(field.value);
  });
}

function isAgentSafetyDefaultAllowSignal(field: RuntimeField): boolean {
  const text = agentSafetySignalText(field);
  if (!/\b(default|fallback|no match|unknown|policy missing|classification missing)\b/iu.test(text)) return false;
  return agentSafetyAllowValue(field) || /\b(allow|permit|approve|pass|continue)\b/iu.test(text);
}

function isAgentSafetyTimeoutAllowSignal(field: RuntimeField): boolean {
  const text = agentSafetySignalText(field);
  if (!/\b(timeout|deadline|latency|unavailable|guardrail timeout|moderation timeout|validator timeout)\b/iu.test(text)) return false;
  return agentSafetyAllowValue(field) || /\b(allow|permit|approve|pass|continue|fail open)\b/iu.test(text);
}

function isAgentSafetyErrorAllowSignal(field: RuntimeField): boolean {
  const text = agentSafetySignalText(field);
  if (!/\b(error|exception|parse error|policy error|service error|guardrail error|moderation error|validator error|unavailable|fail open)\b/iu.test(text)) return false;
  return agentSafetyAllowValue(field) || /\b(allow|permit|approve|pass|continue|fail open)\b/iu.test(text);
}

function isAgentSafetyMonitorOnlySignal(field: RuntimeField): boolean {
  const text = agentSafetySignalText(field);
  if (!/\b(monitor only|warn only|log only|report only|shadow|dry run|audit only|observe only)\b/iu.test(text)) return false;
  return truthyConfigValue(field.value) || /\b(enabled|true|monitor only|warn only|shadow|dry run)\b/iu.test(text);
}

function agentSafetyAllowValue(field: RuntimeField): boolean {
  const value = fieldValueText(field).trim().toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
  return /^(allow|permit|approve|pass|continue|bypass|skip|warn only|monitor only|log only|report only|shadow|dry run|fail open)$/iu.test(value);
}

function agentSafetySignalText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function isAgentSafetyGlobalDisabledSignal(field: RuntimeField): boolean {
  const text = `${field.path} ${fieldValueText(field)}`;
  const mentionsSafety = /\b(guardrails?|safety|controls?|policy|policies|moderation|validation|filter|sanitiz|redaction)\b/iu.test(text);
  if (!mentionsSafety) return false;
  if (/(^|\.)(enabled|enforced|required|active)$/iu.test(field.path)) return disabledConfigValue(field.value);
  if (/\b(disabled|disable|bypass|skip|passthrough|allow_all|allow-all|raw|warn_only|warn-only|log_only|log-only|report_only|report-only|monitor_only|monitor-only)\b/iu.test(field.path)) {
    return truthyConfigValue(field.value);
  }
  return /\b(disabled|disable|bypass|skip|passthrough|allow_all|allow-all|raw|warn_only|warn-only|log_only|log-only|report_only|report-only|monitor_only|monitor-only)\b/iu.test(
    fieldValueText(field)
  );
}

function isAgentSafetyControlDisabled(field: RuntimeField, controlPattern: RegExp): boolean {
  const text = `${field.path} ${fieldValueText(field)}`;
  if (!controlPattern.test(text)) return false;
  if (/(^|\.)(enabled|enforced|required|active)$/iu.test(field.path)) return disabledConfigValue(field.value);
  if (/\b(disabled|disable|bypass|skip|passthrough|allow_all|allow-all|raw|warn_only|warn-only|log_only|log-only|report_only|report-only|monitor_only|monitor-only)\b/iu.test(field.path)) {
    return truthyConfigValue(field.value);
  }
  return disabledConfigValue(field.value);
}

function disabledConfigValue(value: unknown): boolean {
  if (typeof value === "boolean") return !value;
  if (typeof value === "number") return value === 0;
  if (typeof value === "string") {
    return /^(false|no|off|disabled|disable|none|raw|passthrough|bypass|skip|unchecked|allow_all|allow-all|warn_only|warn-only|log_only|log-only|report_only|report-only|monitor_only|monitor-only|0)$/iu.test(
      value.trim()
    );
  }
  return false;
}

function hasAgentSafetyControlSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(guardrails?|safety|moderation|prompt[_\s-]?injection|jailbreak|validation|validator|sanitize|sanitiz|redaction|mask|filter)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentSafetyUntrustedInputSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(untrusted|user|customer|client|ticket|support|issue|comment|message|prompt|retrieved|rag|document|email|chat|inbound|web[_-]?page|browser[_-]?output|tool[_-]?output|external)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function collectAgentSafetyToolAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase();
    if (/\b(tool|tools|function|function_call|mcp|connector|capability)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(browser|playwright|puppeteer|web[_\s-]?agent|click|form|navigate)\b/iu.test(text)) categories.add("browser_action");
    if (/\b(database|db|sql|query|support_db|warehouse)\b/iu.test(text)) categories.add("database_access");
    if (/(?:^|[_\W])(vault|secret|secrets|secret[_\s-]?manager|key[_\s-]?vault|credential)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/\b(slack|email|webhook|message|ticket|issue|comment|reply|send|post|publish)\b/iu.test(text)) categories.add("external_response");
    if (/(?:^|[_\W])(memory|remember|store|persist|session[_\s-]?state)(?:[_\W]|$)/iu.test(text)) categories.add("memory_write");
    if (/\b(shell|bash|command|exec|terminal|python|node|subprocess)\b/iu.test(text)) categories.add("shell_execution");
    if (/\b(filesystem|file[_\s-]?write|workspace|repo|repository|github|gitlab|pull[_\s-]?request)\b/iu.test(text)) {
      categories.add("repo_or_filesystem_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function hasAgentSafetyToolAuthoritySignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(call[_\s-]?tools?|invoke[_\s-]?tools?|tool[_\s-]?access|function[_\s-]?call|mcp|browser|database|vault|shell|filesystem|write[_\s-]?tool)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function isAgentSafetyPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "browser_action",
      "database_access",
      "external_response",
      "memory_write",
      "repo_or_filesystem_write",
      "secret_manager_access",
      "shell_execution",
      "tool_call"
    ].includes(category)
  );
}

function hasAgentSafetyWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) => ["database_access", "external_response", "repo_or_filesystem_write", "shell_execution"].includes(category)) ||
    fields.some((field) =>
      /\b(write|update|create|delete|reply|respond|send|post|publish|comment|commit|push|merge|deploy|remember|persist|approve|close|assign)\b/iu.test(
        `${field.path} ${fieldValueText(field)}`
      )
    );
}

function hasAgentSafetyExternalAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) => /\b(slack|email|webhook|send|post|publish|reply|respond|ticket|issue|external)\b/iu.test(`${field.path} ${fieldValueText(field)}`));
}

function hasAgentSafetyMemoryWriteSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("memory_write") ||
    fields.some((field) =>
      /(?:^|[_\W])(memory|remember|store|persist|session[_\s-]?state|long[_\s-]?term[_\s-]?memory)(?:[_\W]|$)/iu.test(
        `${field.path} ${fieldValueText(field)}`
      )
    );
}

function hasAgentSafetySecretSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /\b(secret|token|credential|api[_-]?key|password|vault|key[_\s-]?vault)\b/iu.test(`${field.path} ${fieldValueText(field)}`));
}

function hasAgentSafetySensitiveDataSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|order|record|case|profile|note|incident)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentSafetyPiiDataSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date[_\s-]?of[_\s-]?birth|customer[_-]?id|user[_-]?id|account[_-]?id)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    )
  );
}

function hasAgentSafetyApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /approval|required[_-]?approval|human[_-]?approval|confirm|confirmation|human[_-]?review|manual[_-]?review|human[_-]?in[_-]?the[_-]?loop/iu.test(
      field.path
    ) &&
    truthyConfigValue(field.value)
  );
}

function isAgentSafetySecurityField(fieldPath: string): boolean {
  return /framework|provider|guardrail|safety|policy|control|moderation|filter|injection|jailbreak|validation|validator|sanitize|sanitiz|redact|mask|secret|pii|tool|mcp|function|output|input|source|customer|ticket|email|browser|database|memory|write|send|publish|approval|auth|token|credential|env|permission|scope|default|fallback|timeout|error|exception|fail[_-]?open|monitor|warn|shadow|dry[_-]?run|enforcement|deterministic|schema|allowlist|denylist|llm|model|judge|review|pre[_-]?tool|post[_-]?hoc/iu.test(
    fieldPath
  );
}

function isLikelyEnvKeyName(value: string): boolean {
  return /^[A-Z][A-Z0-9_]{2,}$/u.test(value);
}

function classifyAgentIdentityConfig(value: unknown, filePath: string): AgentIdentityPosture {
  const fields = flattenRuntimeFields(value);
  const stringValues = collectFieldStringValues(fields);
  const provider = inferAgentIdentityProvider([filePath, ...fields.map((field) => field.path), ...stringValues]);
  const destinations = classifyAgentIdentityDestinations(fields, provider);
  const scopeCategories = collectAgentIdentityScopeCategories(fields);
  const envKeys = uniqueStrings([
    ...collectEnvKeyNamesFromConfig(value).filter(isLikelyEnvKeyName),
    ...extractEnvironmentReferenceKeys(stringValues)
  ]);
  const secretRefKeys = extractSecretReferenceKeys(stringValues);

  return {
    agent_identity_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isAgentIdentitySecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    agent_identity_provider: provider,
    agent_identity_remote: destinations.remote,
    agent_identity_destination_redacted: destinations.destinationCount > 0,
    agent_identity_destination_count: destinations.destinationCount,
    agent_identity_destination_kinds: destinations.destinationKinds,
    agent_identity_issuer_redacted: hasAgentIdentityIssuerSignal(fields),
    agent_identity_subject_redacted: hasAgentIdentitySubjectSignal(fields),
    agent_identity_scope_redacted: scopeCategories.length > 0,
    agent_identity_scope_categories: scopeCategories,
    agent_identity_broad_scope: isAgentIdentityBroadScope(scopeCategories),
    agent_identity_admin_scope: scopeCategories.some((scope) => scope === "admin_scope" || scope === "iam_admin" || scope === "wildcard_scope"),
    agent_identity_write_scope: scopeCategories.some((scope) =>
      ["cloud_write", "email_modify", "repo_write", "storage_write", "ticket_write", "workspace_write"].includes(scope)
    ),
    agent_identity_credential_issuance_enabled: hasAgentIdentityCredentialIssuanceSignal(fields),
    agent_identity_impersonation_enabled: hasAgentIdentityImpersonationSignal(fields),
    agent_identity_token_refresh_enabled: hasAgentIdentityTokenRefreshSignal(fields),
    agent_identity_tool_injection: hasAgentIdentityToolInjectionSignal(fields),
    agent_identity_external_authority: hasAgentIdentityExternalAuthoritySignal(fields, scopeCategories),
    agent_identity_untrusted_input: hasAgentIdentityUntrustedInputSignal(fields),
    agent_identity_sensitive_data: hasAgentIdentitySensitiveDataSignal(fields),
    agent_identity_pii_data: hasAgentIdentityPiiDataSignal(fields),
    agent_identity_approval_required: hasAgentIdentityApprovalRequiredSignal(fields),
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function inferAgentIdentityProvider(candidates: string[]): string | undefined {
  const text = candidates.join(" ").toLowerCase();
  const providers: Array<[string, RegExp]> = [
    ["google_workload_identity", /\b(google[_\s-]?workload[_\s-]?identity|gcp[_\s-]?workload[_\s-]?identity|sts\.googleapis\.com|iamcredentials\.googleapis\.com)\b/iu],
    ["aws_sts", /\b(aws[_\s-]?sts|assume[_\s-]?role|web[_\s-]?identity|sts\.amazonaws\.com)\b/iu],
    ["azure_entra", /\b(azure[_\s-]?entra|azure[_\s-]?ad|microsoft[_\s-]?identity|login\.microsoftonline\.com)\b/iu],
    ["github_app", /\b(github[_\s-]?app|installation[_\s-]?token|github\.com\/login\/oauth|api\.github\.com\/app)\b/iu],
    ["oauth2", /\b(oauth2?|oidc|openid[_\s-]?connect|authorization[_\s-]?server|token[_\s-]?endpoint)\b/iu],
    ["service_account", /\b(service[_\s-]?account|impersonat|delegat|token[_\s-]?broker|credential[_\s-]?broker)\b/iu]
  ];
  return providers.find(([, pattern]) => pattern.test(text))?.[0];
}

function classifyAgentIdentityDestinations(
  fields: RuntimeField[],
  provider: string | undefined
): { remote: boolean; destinationCount: number; destinationKinds: string[] } {
  const destinationKinds = new Set<string>();
  let destinationCount = 0;
  if (provider && provider !== "service_account") {
    destinationKinds.add("managed_identity_provider");
    destinationCount += 1;
  }

  for (const field of fields) {
    const values = fieldStringValues(field);
    for (const value of values) {
      const destination = parseAgentIdentityDestination(value);
      if (destination) {
        destinationKinds.add(destination.kind);
        destinationCount += 1;
      }
    }
    if (/(^|\.)(issuer|issuer_url|authority|authorization_server|token_endpoint|sts_endpoint|endpoint|url|uri|host|audience)$/iu.test(field.path)) {
      const text = values.join(" ");
      if (looksLikeRemoteIdentityHost(text)) {
        destinationKinds.add("identity_provider_endpoint");
        destinationCount += 1;
      }
    }
  }

  return {
    remote: destinationCount > 0,
    destinationCount,
    destinationKinds: [...destinationKinds].sort((a, b) => a.localeCompare(b))
  };
}

function parseAgentIdentityDestination(value: string): { kind: string } | undefined {
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return undefined;
    if (isLocalHost(parsed.hostname.toLowerCase())) return undefined;
    return { kind: parsed.protocol === "http:" ? "plaintext_identity_endpoint" : "identity_provider_endpoint" };
  } catch {
    return undefined;
  }
}

function looksLikeRemoteIdentityHost(value: string): boolean {
  const trimmed = value.trim().toLowerCase();
  if (!trimmed || trimmed.startsWith("${")) return false;
  if (isLocalHost(trimmed)) return false;
  return /\b(sts|iam|oauth|oidc|login|auth|accounts|identity|token|entra|okta|auth0|googleapis|amazonaws|microsoftonline)\b/iu.test(trimmed) ||
    /^[a-z0-9.-]+\.[a-z]{2,}(?::\d+)?$/iu.test(trimmed);
}

function collectAgentIdentityScopeCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (!/(^|\.)(scopes?|oauth[_-]?scopes?|permissions?|roles?|claims?|capabilities|access|resources?|allowed[_-]?actions?)$/iu.test(field.path)) {
      continue;
    }
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase();
    if (/(^|[\s,])\*(?=[$\s,])|\ball[_\s-]?(scopes?|roles?|permissions?|resources?)\b|full[_\s-]?access|cloud-platform/iu.test(text)) {
      categories.add("wildcard_scope");
    }
    if (/\b(admin|administrator|owner|superuser|root|org[_\s-]?admin|roles\/owner|roles\/editor)\b/iu.test(text)) {
      categories.add("admin_scope");
    }
    if (/iam\.serviceaccount|service[_\s-]?account[_\s-]?token[_\s-]?creator|token[_\s-]?creator|impersonat|assume[_\s-]?role|sts:assumerole|iam:passrole/iu.test(text)) {
      categories.add("iam_admin");
    }
    if (/repo\b|contents:write|pull[_-]?requests?:write|issues?:write|workflow|checks:write|deployments?:write/iu.test(text)) {
      categories.add("repo_write");
    }
    if (/gmail\.modify|gmail\.send|mail\.send|mail\.readwrite|email:send|email:write/iu.test(text)) {
      categories.add("email_modify");
    }
    if (/drive|storage|s3|blob|bucket|objects?:write|storage\.objects|s3:put|s3:delete/iu.test(text)) {
      categories.add("storage_write");
    }
    if (/jira.*write|write:jira|issue:write|tickets?:write|zendesk.*write|linear.*write|servicenow.*write/iu.test(text)) {
      categories.add("ticket_write");
    }
    if (/database|sql|cloudsql|rds|dynamodb|bigquery|datastore|firestore|spanner/iu.test(text)) {
      categories.add("cloud_write");
    }
    if (/workspace|directory|users?:write|groups?:write|admin\.directory/iu.test(text)) {
      categories.add("workspace_write");
    }
    if (/read|list|get|profile|metadata|openid|userinfo|email/iu.test(text)) categories.add("read_scope");
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function isAgentIdentityBroadScope(scopeCategories: string[]): boolean {
  return scopeCategories.some((scope) =>
    [
      "admin_scope",
      "cloud_write",
      "email_modify",
      "iam_admin",
      "repo_write",
      "storage_write",
      "ticket_write",
      "wildcard_scope",
      "workspace_write"
    ].includes(scope)
  );
}

function hasAgentIdentityIssuerSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(^|\.)(issuer|issuer_url|authority|authorization_server|jwks_uri|audience|client_id)$/iu.test(field.path));
}

