function hasVectorPromptInjectionPassthroughSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = `${field.path} ${fieldValueText(field)}`;
    if (/\b(prompt[_\s-]?injection|jailbreak|sanitize|sanitiz|redact|filter)\b/iu.test(field.path)) {
      return disabledConfigValue(field.value) || /\b(disabled|none|raw|passthrough|bypass|skip)\b/iu.test(text);
    }
    if (/\b(inject[_\s-]?into[_\s-]?prompt|system|developer|prompt[_\s-]?context)\b/iu.test(text)) return truthyConfigValue(field.value);
    return false;
  });
}

function hasVectorRawChunkPassthroughSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(raw[_\s-]?chunks?|include[_\s-]?raw|raw[_\s-]?documents?|full[_\s-]?text|chunk[_\s-]?text)(?:[_\W]|$)/iu.test(
      `${field.path} ${fieldValueText(field)}`
    ) &&
    truthyConfigValue(field.value)
  );
}

function hasVectorToolContextInjectionSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(pass[_\s-]?to[_\s-]?tools?|tool[_\s-]?context|tool[_\s-]?arguments?|tool[_\s-]?inputs?|use[_\s-]?for[_\s-]?tools?)\b/iu.test(
      `${field.path} ${fieldValueText(field)}`
    ) && truthyConfigValue(field.value)
  );
}

function hasVectorRetrievalApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required[_-]?approval|human[_-]?approval|confirm|confirmation|review|human[_-]?in[_-]?the[_-]?loop)\b/iu.test(field.path) &&
    truthyConfigValue(field.value)
  );
}

function fieldValueText(field: RuntimeField): string {
  if (Array.isArray(field.value)) return field.value.map(String).join(" ");
  if (typeof field.value === "string" || typeof field.value === "number" || typeof field.value === "boolean") {
    return String(field.value);
  }
  return "";
}

function truthyConfigValue(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  if (typeof value === "string") return !/^(false|no|off|disabled|disable|none|readonly|read_only|read-only|0)$/iu.test(value.trim());
  if (Array.isArray(value)) return value.length > 0;
  return Boolean(value);
}

function isRagConnectorSecurityField(fieldPath: string): boolean {
  return /provider|endpoint|url|uri|host|dsn|connection|secret|token|api[_-]?key|credential|auth|env|collection|namespace|index|table|bucket|corpus|dataset|write|upsert|insert|ingest|sync|source|document|upload|attachment|loader|embedding|vector|retriev|query|filters?|acl|provenance|trust|citation|quarantine|moderation|sanitize|instruction|prompt[_-]?injection|approval|raw[_-]?chunks?|tools?|fetch|crawl|scrape|redirect|allowlist|denylist|private[_-]?network|metadata[_-]?service|imds|ssrf|cookie|header/iu.test(
    fieldPath
  );
}

function isCursorRulePath(lowerPath: string): boolean {
  return lowerPath.includes(".cursor/rules/");
}

function classifyCursorRule(
  file: WalkedFile,
  content: string,
  surfaces: DetectedSurfaces
): CursorRuleClassification {
  const frontmatter = parseCursorRuleFrontmatter(content);
  const parsed = frontmatter?.parsed;
  const globs = parsed ? cursorRuleGlobs(parsed) : [];
  const alwaysApply = parsed ? cursorRuleBoolean(parsed, "alwaysApply") : undefined;
  const descriptionPresent = parsed ? typeof parsed.description === "string" && parsed.description.trim().length > 0 : false;
  const applicationMode = cursorRuleApplicationMode(alwaysApply, globs, descriptionPresent);
  const scopeKinds = cursorRuleScopeKinds(globs);
  const appliesBroadly = alwaysApply === true || scopeKinds.includes("all_files") || scopeKinds.includes("workspace");

  if (frontmatter?.parseFailed) {
    addDiagnostic(surfaces, file, {
      code: "CURSOR_RULE_FRONTMATTER_PARSE_FAILED",
      parser: "cursor-rule",
      reason: "Cursor rule frontmatter could not be parsed and was skipped. Raw rule content was redacted."
    });
  }

  return {
    analyzedContent: frontmatter?.body ?? content,
    metadata: {
      cursor_rule: true,
      cursor_rule_frontmatter_present: frontmatter !== undefined,
      cursor_rule_frontmatter_parsed: Boolean(parsed),
      cursor_rule_body_redacted: true,
      cursor_rule_description_present: descriptionPresent,
      cursor_rule_always_apply: alwaysApply === true,
      cursor_rule_application_mode: applicationMode,
      cursor_rule_glob_count: globs.length,
      cursor_rule_glob_scope_kinds: scopeKinds,
      cursor_rule_applies_broadly: appliesBroadly
    }
  };
}

function parseCursorRuleFrontmatter(
  content: string
): { parsed?: Record<string, unknown>; body: string; parseFailed: boolean } | undefined {
  const normalized = content.replaceAll("\r\n", "\n");
  if (!normalized.startsWith("---\n")) return undefined;
  const endIndex = normalized.indexOf("\n---", 4);
  if (endIndex === -1) return { body: normalized, parseFailed: true };
  const frontmatterText = normalized.slice(4, endIndex).trim();
  const bodyStart = normalized.indexOf("\n", endIndex + 4);
  const body = bodyStart === -1 ? "" : normalized.slice(bodyStart + 1);
  try {
    const parsed = YAML.parse(frontmatterText);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { body, parseFailed: true };
    }
    return { parsed: parsed as Record<string, unknown>, body, parseFailed: false };
  } catch {
    return { body, parseFailed: true };
  }
}

function cursorRuleBoolean(frontmatter: Record<string, unknown>, key: string): boolean | undefined {
  const value = frontmatter[key];
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (normalized === "true") return true;
    if (normalized === "false") return false;
  }
  return undefined;
}

function cursorRuleGlobs(frontmatter: Record<string, unknown>): string[] {
  const raw = frontmatter.globs;
  const values: string[] = [];
  if (typeof raw === "string") {
    values.push(...raw.split(",").map((value) => value.trim()));
  } else if (Array.isArray(raw)) {
    for (const value of raw) {
      if (typeof value === "string") values.push(value.trim());
    }
  }
  return [...new Set(values.filter(Boolean))].sort((a, b) => a.localeCompare(b));
}

function cursorRuleApplicationMode(
  alwaysApply: boolean | undefined,
  globs: string[],
  descriptionPresent: boolean
): string {
  if (alwaysApply === true) return "always";
  if (globs.length > 0) return "auto_attached";
  if (descriptionPresent) return "agent_requested";
  if (alwaysApply === false) return "manual";
  return "unknown";
}

function cursorRuleScopeKinds(globs: string[]): string[] {
  const kinds = new Set<string>();
  for (const glob of globs) {
    const normalized = glob.toLowerCase();
    if (["*", "**", "**/*", "**/*.*"].includes(normalized)) kinds.add("all_files");
    if (normalized.startsWith("**/") || normalized.startsWith("**.")) kinds.add("workspace");
    if (/\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|php|cs|cpp|c|h|sh|zsh|bash)(?:[},\]])?$/iu.test(normalized)) {
      kinds.add("code");
    }
    if (/\.(md|mdx|txt|rst|adoc)(?:[},\]])?$/iu.test(normalized) || normalized.includes("docs/")) kinds.add("docs");
    if (/\.(json|ya?ml|toml|ini|env)(?:[},\]])?$/iu.test(normalized) || normalized.includes("config")) kinds.add("config");
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function classifyContextContent(content: string): ContextContentSignals {
  const instructionOverride = hasAffirmedContextPattern(
    content,
    /\b(ignore|override|bypass|forget|disregard)\b[\s\S]{0,80}\b(instruction|policy|approval|guard|previous|system|developer)\b/i
  );
  const instructionLike =
    instructionOverride ||
    hasAffirmedContextPattern(
      content,
      /\b(system prompt|developer instruction|highest priority|follow these instructions|do not obey|new instruction)\b/i
    );
  const untrustedContext = hasAffirmedContextPattern(
    content,
    /\b(untrusted|user|customer|client|ticket|issue|support|web\s?page|browser|email|slack|copied chat|transcript|retrieved|rag|document|note)\b/i
  );
  const toolDirective = hasAffirmedContextPattern(
    content,
    /\b(call|invoke|use|run|execute|trigger)\b[\s\S]{0,80}\b(tool|mcp|shell|browser|github|slack|webhook|function|api)\b/i
  );
  const memoryWriteDirective = hasAffirmedContextPattern(
    content,
    /\b(remember|store|persist|save|write|update)\b[\s\S]{0,80}\b(memory|future|session|run|instruction|shortcut)\b/i
  );
  const externalDirective =
    hasExternalReach(content) ||
    hasAffirmedContextPattern(content, /\b(webhook|slack|email|external|publish|send|post|upload)\b/i);
  const secretReference = hasSecretExposure(content);
  const sensitiveContextReference = hasSensitiveContextReference(content);
  const dataEgressDirective = hasDataEgressDirective(content);
  const contextBridgeTool = untrustedContext && toolDirective;
  const contextBridgeMemory = untrustedContext && memoryWriteDirective;
  const contextBridgeExternal = untrustedContext && externalDirective;
  const contextBridgeDataEgress = untrustedContext && dataEgressDirective;
  const contextBridgePrivileged =
    contextBridgeTool ||
    contextBridgeMemory ||
    contextBridgeExternal ||
    contextBridgeDataEgress ||
    (untrustedContext && secretReference);
  const signals = [
    instructionLike,
    instructionOverride,
    untrustedContext,
    toolDirective,
    memoryWriteDirective,
    externalDirective,
    secretReference,
    sensitiveContextReference,
    dataEgressDirective
  ].filter(Boolean).length;
  return {
    instruction_like_content: instructionLike,
    instruction_override: instructionOverride,
    untrusted_context_reference: untrustedContext,
    tool_directive: toolDirective,
    memory_write_directive: memoryWriteDirective,
    external_directive: externalDirective,
    secret_reference: secretReference,
    sensitive_context_reference: sensitiveContextReference,
    data_egress_directive: dataEgressDirective,
    context_bridge_tool: contextBridgeTool,
    context_bridge_memory: contextBridgeMemory,
    context_bridge_external: contextBridgeExternal,
    context_bridge_data_egress: contextBridgeDataEgress,
    context_bridge_privileged: contextBridgePrivileged,
    content_signal_count: signals
  };
}

function classifyModelVisibleToolDescription(description: string): Record<string, unknown> {
  const analyzed = description.trim().length > 0;
  const signals = classifyContextContent(description);
  return {
    model_visible_description_analyzed: analyzed,
    model_visible_description_redacted: analyzed,
    model_visible_description_instruction_like_content: signals.instruction_like_content,
    model_visible_description_instruction_override: signals.instruction_override,
    model_visible_description_untrusted_context_reference: signals.untrusted_context_reference,
    model_visible_description_tool_directive: signals.tool_directive,
    model_visible_description_memory_write_directive: signals.memory_write_directive,
    model_visible_description_external_directive: signals.external_directive,
    model_visible_description_secret_reference: signals.secret_reference,
    model_visible_description_sensitive_context_reference: signals.sensitive_context_reference,
    model_visible_description_data_egress_directive: signals.data_egress_directive,
    model_visible_description_context_bridge_tool: signals.context_bridge_tool,
    model_visible_description_context_bridge_memory: signals.context_bridge_memory,
    model_visible_description_context_bridge_external: signals.context_bridge_external,
    model_visible_description_context_bridge_data_egress: signals.context_bridge_data_egress,
    model_visible_description_context_bridge_privileged: signals.context_bridge_privileged,
    model_visible_description_signal_count: signals.content_signal_count
  };
}

function hasSensitiveContextReference(content: string): boolean {
  return hasAffirmedContextPattern(
    content,
    /\b(internal|confidential|proprietary|private|sensitive|customer|client|ticket|support|account|record|summary|report|document|note|pii|credential|secret|token|api[\s_-]?key)\b/i
  );
}

function hasDataEgressDirective(content: string): boolean {
  const verbThenData = hasAffirmedContextPattern(
    content,
    /\b(send|post|upload|publish|forward|share|copy|exfiltrate)\b[\s\S]{0,140}\b(internal|confidential|proprietary|private|sensitive|customer|client|ticket|support|account|record|summary|report|document|note|data|credential|secret|token|api[\s_-]?key)\b/i
  );
  const dataThenVerb = hasAffirmedContextPattern(
    content,
    /\b(internal|confidential|proprietary|private|sensitive|customer|client|ticket|support|account|record|summary|report|document|note|data|credential|secret|token|api[\s_-]?key)\b[\s\S]{0,140}\b(send|post|upload|publish|forward|share|copy|exfiltrate)\b/i
  );
  const externalTarget = hasAffirmedContextPattern(content, /\b(webhook|slack|email|external|remote|url|api|outside|third[-\s]?party)\b/i);
  return externalTarget && (verbThenData || dataThenVerb);
}

function hasAffirmedContextPattern(content: string, pattern: RegExp): boolean {
  const flags = pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`;
  const matcher = new RegExp(pattern.source, flags);
  let match: RegExpExecArray | null;
  while ((match = matcher.exec(content)) !== null) {
    if (!isNegatedContextMatch(content, match.index)) return true;
    if (match[0].length === 0) matcher.lastIndex += 1;
  }
  return false;
}

function isNegatedContextMatch(content: string, index: number): boolean {
  const before = content.slice(Math.max(0, index - 120), index);
  const clauseStart = Math.max(before.lastIndexOf("."), before.lastIndexOf("\n"), before.lastIndexOf(";"));
  const clause = before.slice(clauseStart + 1);
  return /\b(do not|don't|dont|must not|should not|cannot|can't|never|not allowed to|not permitted to|forbid(?:s|den)?|prohibit(?:s|ed)?)\b/i.test(
    clause
  );
}

function classifySkillDataFlow(content: string): SkillDataFlowSignals {
  const sources = new Set<string>();
  const retrievedContextInput = /\b(retrieved|retrieval|rag|document|documents|knowledge|context|customer note|web page|webpage)\b/iu.test(
    content
  );
  const toolOutputInput = /\b(tool output|tool result|tool response|command output|browser output|mcp result)\b/iu.test(content);
  const memoryInput = /\b(memory|memories|remembered|session state|stored context)\b/iu.test(content);
  const promptInput = /\b(prompt|instruction|system message|developer message)\b/iu.test(content);
  const externalOutput =
    hasExternalReach(content) || /\b(publish|post|send|upload|webhook|slack|email|external)\b/iu.test(content);
  const localWriteOutput = /\b(write|update|save|modify|append|release notes|file)\b/iu.test(content);

  if (retrievedContextInput) sources.add("retrieved_context");
  if (toolOutputInput) sources.add("tool_output");
  if (memoryInput) sources.add("memory");
  if (promptInput) sources.add("prompt");

  return {
    retrieved_context_input: retrievedContextInput,
    tool_output_input: toolOutputInput,
    memory_input: memoryInput,
    prompt_input: promptInput,
    context_input_sources: [...sources].sort((a, b) => a.localeCompare(b)),
    context_input_count: sources.size,
    external_output: externalOutput,
    local_write_output: localWriteOutput,
    context_bridge_external_output: sources.size > 0 && externalOutput
  };
}

function classifyPromptTemplate(content: string): PromptTemplateSignals {
  const variableNames = extractTemplateVariableNames(content);
  const untrustedVariables = variableNames.filter(isUntrustedTemplateVariable);
  const roleSignals = classifyPromptTemplateRoleSignals(content, untrustedVariables);
  return {
    prompt_template: variableNames.length > 0,
    template_variable_names: variableNames,
    template_variable_count: variableNames.length,
    untrusted_template_variables: untrustedVariables,
    untrusted_template_input: untrustedVariables.length > 0,
    ...roleSignals
  };
}

function extractTemplateVariableNames(content: string): string[] {
  const variables = new Set<string>();
  for (const match of content.matchAll(/\{\{\s*([a-zA-Z_][a-zA-Z0-9_.-]*)\s*\}\}/g)) {
    if (match[1]) variables.add(normalizeTemplateVariableName(match[1]));
  }
  for (const match of content.matchAll(/\$\{\s*([a-zA-Z_][a-zA-Z0-9_.-]*)\s*\}/g)) {
    if (match[1]) variables.add(normalizeTemplateVariableName(match[1]));
  }
  for (const match of content.matchAll(/(?<!\{)\{([a-zA-Z_][a-zA-Z0-9_.-]*)\}(?!\})/g)) {
    if (match[1]) variables.add(normalizeTemplateVariableName(match[1]));
  }

  return [...variables].sort((a, b) => a.localeCompare(b));
}

function classifyPromptTemplateRoleSignals(
  content: string,
  untrustedVariables: string[]
): Pick<
  PromptTemplateSignals,
  | "privileged_prompt_role"
  | "privileged_template_roles"
  | "privileged_role_untrusted_variables"
  | "privileged_role_untrusted_variable_count"
  | "privileged_role_untrusted_template_input"
> {
  const roleSegments = promptRoleSegments(content);
  const privilegedRoles = new Set<string>();
  const privilegedRoleVariables = new Set<string>();
  const untrustedVariableSet = new Set(untrustedVariables);

  for (const segment of roleSegments) {
    privilegedRoles.add(segment.role);
    for (const variableName of extractTemplateVariableNames(segment.text)) {
      if (untrustedVariableSet.has(variableName)) privilegedRoleVariables.add(variableName);
    }
  }

  const variables = [...privilegedRoleVariables].sort((a, b) => a.localeCompare(b));
  return {
    privileged_prompt_role: privilegedRoles.size > 0,
    privileged_template_roles: [...privilegedRoles].sort((a, b) => a.localeCompare(b)),
    privileged_role_untrusted_variables: variables,
    privileged_role_untrusted_variable_count: variables.length,
    privileged_role_untrusted_template_input: variables.length > 0
  };
}

function promptRoleSegments(content: string): Array<{ role: "developer" | "system"; text: string }> {
  const segments: Array<{ role: "developer" | "system"; text: string }> = [];
  let activeRole: "developer" | "system" | undefined;
  let activeLines: string[] = [];

  const flush = (): void => {
    if (activeRole) segments.push({ role: activeRole, text: activeLines.join("\n") });
    activeRole = undefined;
    activeLines = [];
  };

  for (const line of content.split(/\r?\n/u)) {
    const markdownHeading = line.match(/^\s*#{1,6}\s*(system|developer)\b/iu);
    if (markdownHeading?.[1]) {
      flush();
      activeRole = markdownHeading[1].toLowerCase() as "developer" | "system";
      continue;
    }

    const roleLabel = line.match(/^\s*(?:[-*]\s*)?(system|developer|user|assistant|tool|function)\s*:\s*(.*)$/iu);
    if (roleLabel?.[1]) {
      flush();
      const role = roleLabel[1].toLowerCase();
      activeRole = role === "system" || role === "developer" ? role : undefined;
      if (activeRole && roleLabel[2]) activeLines.push(roleLabel[2]);
      continue;
    }

    const yamlRole = line.match(/^\s*(?:-\s*)?role\s*:\s*["']?(system|developer|user|assistant|tool|function)["']?/iu);
    if (yamlRole?.[1]) {
      flush();
      const role = yamlRole[1].toLowerCase();
      activeRole = role === "system" || role === "developer" ? role : undefined;
      continue;
    }

    if (activeRole) activeLines.push(line);
  }
  flush();

  return segments;
}

function classifyPromptTemplateBridge(
  template: PromptTemplateSignals,
  signals: ContextContentSignals
): PromptTemplateBridgeSignals {
  const untrustedTemplateInput = template.untrusted_template_input;
  const bridgeTool = untrustedTemplateInput && signals.tool_directive;
  const bridgeMemory = untrustedTemplateInput && signals.memory_write_directive;
  const bridgeExternal = untrustedTemplateInput && signals.external_directive;
  const bridgeSecret = untrustedTemplateInput && signals.secret_reference;
  return {
    template_bridge_tool: bridgeTool,
    template_bridge_memory: bridgeMemory,
    template_bridge_external: bridgeExternal,
    template_bridge_secret: bridgeSecret,
    template_bridge_privileged: bridgeTool || bridgeMemory || bridgeExternal || bridgeSecret
  };
}

function normalizeTemplateVariableName(name: string): string {
  return name.replace(/[^a-zA-Z0-9_.-]+/g, "_").replace(/^_+|_+$/g, "").toLowerCase();
}

function isUntrustedTemplateVariable(name: string): boolean {
  return /\b(user|customer|client|ticket|issue|comment|message|input|query|request|web|page|browser|email|slack|review|pr|pull_request|retrieved|rag|document|context|note)\b/iu.test(
    name.replace(/[._-]/g, " ")
  );
}

function classifyGeneratedState(relativePath: string, content: string): GeneratedStateSignals {
  const lowerPath = relativePath.replaceAll("\\", "/").toLowerCase();
  const segments = lowerPath.split("/");
  const kinds = new Set<string>();

  for (const segment of segments.slice(0, -1)) {
    if (GENERATED_STATE_DIR_NAMES.has(segment)) kinds.add(segment.replaceAll("-", "_"));
  }
  if (/transcript|conversation|session|run[-_]?log|tool[-_]?output|cached[-_]?output|summary/i.test(lowerPath)) {
    kinds.add("filename_signal");
  }

  const transcriptLike = /\b(assistant|user|system|developer|tool|function)\s*:/i.test(content);
  const toolOutputLike = /\b(tool|function|mcp|browser|shell|command)\s+(result|output|response|call)\b/i.test(content);
  const cachedOutputLike = /\b(cache|cached|artifact|tool output|run summary|session transcript)\b/i.test(content);

  if (transcriptLike) kinds.add("transcript");
  if (toolOutputLike) kinds.add("tool_output");
  if (cachedOutputLike) kinds.add("cached_output");

  return {
    generated_state: kinds.size > 0,
    generated_state_kinds: [...kinds].sort((a, b) => a.localeCompare(b)),
    transcript_like: transcriptLike,
    tool_output_like: toolOutputLike,
    cached_output_like: cachedOutputLike
  };
}

function contextActions(signals: ContextContentSignals, type: "rag_source" | "memory"): ActionType[] {
  const actions = new Set<ActionType>(["read"]);
  if (type === "memory" || signals.memory_write_directive) actions.add("remember");
  if (signals.tool_directive) actions.add("call");
  if (signals.external_directive) actions.add("send");
  return [...actions].sort((a, b) => a.localeCompare(b));
}

function promptActions(signals: ContextContentSignals): ActionType[] {
  const actions = new Set<ActionType>(["read"]);
  if (signals.memory_write_directive) actions.add("remember");
  if (signals.tool_directive) actions.add("call");
  if (signals.external_directive) actions.add("send");
  return [...actions].sort((a, b) => a.localeCompare(b));
}

function addDiagnostic(
  surfaces: DetectedSurfaces,
  file: WalkedFile,
  diagnostic: Omit<ScanDiagnostic, "id" | "file_path" | "severity" | "content_redacted"> & {
    severity?: ScanDiagnostic["severity"];
  }
): void {
  surfaces.diagnostics.push({
    id: stableId("diagnostic", [diagnostic.code, file.relativePath]),
    severity: diagnostic.severity ?? "warning",
    code: diagnostic.code,
    file_path: file.relativePath,
    parser: diagnostic.parser,
    reason: diagnostic.reason,
    content_redacted: true
  });
}

async function detectMcpConfig(
  file: WalkedFile,
  text: string | undefined,
  surfaces: DetectedSurfaces,
  projectFilePaths: Set<string>
): Promise<void> {
  const raw = text ?? "{}";
  let parsed: unknown;
  let parseFailed = false;
  try {
    parsed = JSON.parse(raw);
  } catch {
    parseFailed = raw.trim().length > 0;
    parsed = {};
  }
  if (parseFailed) {
    addDiagnostic(surfaces, file, {
      parser: "json",
      code: "MCP_CONFIG_PARSE_FAILED",
      reason: "MCP configuration could not be parsed as JSON. Raw content was redacted."
    });
  }
  const servers = extractMcpServers(parsed);
  if (servers.length === 0) {
    surfaces.mcp_servers.push(
      createSurfaceObject({
        type: "mcp_server",
        name: path.basename(file.relativePath),
        path: file.relativePath,
        actions: ["call"],
        side_effect: true,
        reason: "MCP configuration discovered.",
        metadata: { content_redacted: true, server_count: 0, parse_error: parseFailed }
      })
    );
    return;
  }

  for (const server of servers) {
    const signalText = `${server.command ?? ""} ${(server.args ?? []).join(" ")} ${server.transport ?? ""} ${server.remoteHost ?? ""} ${(server.envKeys ?? []).join(" ")} ${server.envExposure.passthroughSourceKinds.join(" ")} ${(server.headerNames ?? []).join(" ")} ${(server.secretRefKeys ?? []).join(" ")}`;
    const actions = detectActions(signalText);
    const externalRemote = Boolean(server.remote && server.remoteHost && !isLocalHost(server.remoteHost));
    const plaintextRemoteTransport = externalRemote && server.remoteScheme === "http";
    const encryptedRemoteTransport = externalRemote && server.remoteScheme === "https";
    const secretKeys = [...(server.envKeys ?? []), ...(server.secretRefKeys ?? []), ...(server.authHeaderNames ?? [])];
    const baseActions: ActionType[] = actions.length > 0 ? actions : ["call"];
    const packageRunner = server.packageRunner;
    const clientContext = server.clientContext;
    const toolCatalog = server.toolCatalog;
    const resourceSubscriptions = server.resourceSubscriptions;
    const localImplementationPaths = server.localCommandPaths ?? [];
    const localImplementationPathsFound = localImplementationPaths.filter((pathRef) => projectFilePaths.has(pathRef));
    const localImplementationPathsMissing = localImplementationPaths.filter((pathRef) => !projectFilePaths.has(pathRef));
    const dataClasses = new Set<SurfaceObject["data_classes"][number]>(
      secretKeys.length > 0 || server.envExposure.passthroughSecretRisk ? ["credential"] : ["unknown"]
    );
    if (clientContext.rootsRedacted || clientContext.samplingIncludesContext) dataClasses.add("confidential");
    if (clientContext.samplingSensitiveContext) {
      if (
        clientContext.samplingContextKinds.includes("credential_context") ||
        clientContext.samplingContextKinds.includes("secret_context")
      ) {
        dataClasses.add("credential");
        dataClasses.add("secret");
      }
      if (clientContext.samplingContextKinds.includes("pii_context")) dataClasses.add("pii");
      dataClasses.add("confidential");
    }
    if (clientContext.elicitationSensitiveFields) {
      if (clientContext.elicitationSensitiveFieldKinds.includes("credential")) {
        dataClasses.add("credential");
        dataClasses.add("secret");
      }
      if (clientContext.elicitationSensitiveFieldKinds.includes("pii")) dataClasses.add("pii");
      dataClasses.add("confidential");
    }
    if (toolCatalog.sensitiveContext) dataClasses.add("confidential");
    if (toolCatalog.piiContext) dataClasses.add("pii");
    if (toolCatalog.secretContext) {
      dataClasses.add("credential");
      dataClasses.add("secret");
    }
    if (resourceSubscriptions.sensitiveContext || resourceSubscriptions.rawContentPassthrough) dataClasses.add("confidential");
    if (resourceSubscriptions.piiContext) dataClasses.add("pii");
    if (resourceSubscriptions.secretContext) {
      dataClasses.add("credential");
      dataClasses.add("secret");
    }
    if (dataClasses.size > 1) dataClasses.delete("unknown");
    const mcpActions: ActionType[] = [
      ...baseActions,
      ...(clientContext.rootsRedacted ? (["read"] as ActionType[]) : []),
      ...(clientContext.contextRequestAuthority ? (["call"] as ActionType[]) : []),
      ...(externalRemote ? (["send"] as ActionType[]) : []),
      ...(packageRunner ? (["execute"] as ActionType[]) : []),
      ...(toolCatalog.detected ? (["read"] as ActionType[]) : []),
      ...(toolCatalog.writeAuthority ? (["write"] as ActionType[]) : []),
      ...(toolCatalog.externalAuthority ? (["send"] as ActionType[]) : []),
      ...(toolCatalog.memoryAuthority ? (["remember"] as ActionType[]) : []),
      ...(toolCatalog.shellAuthority ? (["execute"] as ActionType[]) : []),
      ...(resourceSubscriptions.detected ? (["read"] as ActionType[]) : []),
      ...(resourceSubscriptions.autoIncludeContext || resourceSubscriptions.modelVisibleContext ? (["call"] as ActionType[]) : []),
      ...(resourceSubscriptions.writeAuthority ? (["write"] as ActionType[]) : []),
      ...(resourceSubscriptions.externalAuthority ? (["send"] as ActionType[]) : []),
      ...(resourceSubscriptions.memoryAuthority ? (["remember"] as ActionType[]) : []),
      ...(resourceSubscriptions.shellAuthority ? (["execute"] as ActionType[]) : [])
    ];
    const object = createSurfaceObject({
      type: "mcp_server",
      name: server.name,
      path: file.relativePath,
      trust_level: externalRemote || packageRunner ? "third_party" : inferTrustLevel(file.relativePath),
      data_classes: uniqueDataClasses([...dataClasses] as SurfaceObject["data_classes"]),
      actions: uniqueActions(mcpActions),
      side_effect: true,
      external_reach: externalRemote || Boolean(packageRunner) || hasExternalReach(signalText),
      secret_exposure:
        secretKeys.some(isCredentialLikeKeyName) ||
        server.envExposure.passthroughSecretRisk ||
        toolCatalog.secretContext ||
        resourceSubscriptions.secretContext,
      reversible: !toolCatalog.privilegedToolAuthority && !resourceSubscriptions.privilegedBridge && isReversible(signalText),
      reason: "MCP server configuration exposes agent-callable tools and authority.",
      metadata: {
        command_name: server.command ? path.basename(server.command) : undefined,
        args_count: server.args?.length ?? 0,
        transport: server.transport,
        remote: server.remote,
        remote_host: server.remoteHost,
        remote_scheme: server.remoteScheme,
        plaintext_remote_transport: plaintextRemoteTransport,
        encrypted_remote_transport: encryptedRemoteTransport,
        url_redacted: Boolean(server.remote),
        header_names: server.headerNames ?? [],
        auth_header_names: server.authHeaderNames ?? [],
        env_key_names: server.envKeys ?? [],
        mcp_env_passthrough: server.envExposure.passthrough,
        mcp_env_passthrough_all: server.envExposure.passthroughAll,
        mcp_env_passthrough_secret_risk: server.envExposure.passthroughSecretRisk,
        mcp_env_passthrough_source_kinds: server.envExposure.passthroughSourceKinds,
        mcp_env_passthrough_pattern_count: server.envExposure.passthroughPatternCount,
        secret_ref_key_names: server.secretRefKeys ?? [],
        local_command_paths: localImplementationPaths,
        local_command_path_count: localImplementationPaths.length,
        local_command_paths_found: localImplementationPathsFound,
        local_command_paths_missing: localImplementationPathsMissing,
        local_command_paths_missing_count: localImplementationPathsMissing.length,
        local_command_paths_all_found: localImplementationPaths.length > 0 && localImplementationPathsMissing.length === 0,
        opaque_local_mcp_implementation: localImplementationPaths.length > 0 && localImplementationPathsMissing.length > 0,
        package_runner: Boolean(packageRunner),
        package_runner_name: packageRunner?.runner,
        package_name: packageRunner?.packageName,
        package_version_pinned: packageRunner?.versionPinned,
        package_reference_redacted: packageRunner?.packageReferenceRedacted ?? false,
        mcp_roots_redacted: clientContext.rootsRedacted,
        mcp_root_count: clientContext.rootCount,
        mcp_root_scope_kinds: clientContext.rootScopeKinds,
        mcp_root_broad_scope: clientContext.rootBroadScope,
        mcp_root_credential_scope: clientContext.rootCredentialScope,
        mcp_root_host_scope: clientContext.rootHostScope,
        mcp_root_sensitive_scope: clientContext.rootSensitiveScope,
        mcp_root_approval_required: clientContext.rootApprovalRequired,
        mcp_sampling_enabled: clientContext.samplingEnabled,
        mcp_sampling_includes_context: clientContext.samplingIncludesContext,
        mcp_sampling_context_kinds: clientContext.samplingContextKinds,
        mcp_sampling_sensitive_context: clientContext.samplingSensitiveContext,
        mcp_sampling_redaction_disabled: clientContext.samplingRedactionDisabled,
        mcp_sampling_prompt_injection_filter_disabled: clientContext.samplingPromptInjectionFilterDisabled,
        mcp_sampling_approval_required: clientContext.samplingApprovalRequired,
        mcp_elicitation_enabled: clientContext.elicitationEnabled,
        mcp_elicitation_sensitive_fields: clientContext.elicitationSensitiveFields,
        mcp_elicitation_sensitive_field_count: clientContext.elicitationSensitiveFieldCount,
        mcp_elicitation_sensitive_field_kinds: clientContext.elicitationSensitiveFieldKinds,
        mcp_elicitation_redaction_disabled: clientContext.elicitationRedactionDisabled,
        mcp_elicitation_sanitization_disabled: clientContext.elicitationSanitizationDisabled,
        mcp_elicitation_approval_required: clientContext.elicitationApprovalRequired,
        mcp_context_request_authority: clientContext.contextRequestAuthority,
        mcp_client_context_exposure: clientContext.clientContextExposure,
        mcp_tool_catalog_detected: toolCatalog.detected,
        mcp_tool_catalog_enabled: toolCatalog.enabled,
        mcp_tool_catalog_source_redacted: toolCatalog.sourceRedacted,
        mcp_tool_catalog_source_count: toolCatalog.sourceCount,
        mcp_tool_catalog_source_kinds: toolCatalog.sourceKinds,
        mcp_tool_catalog_dynamic: toolCatalog.dynamicDiscovery,
        mcp_tool_catalog_auto_refresh: toolCatalog.autoRefresh,
        mcp_tool_catalog_model_visible_descriptions: toolCatalog.modelVisibleDescriptions,
        mcp_tool_catalog_remote_schema_trust: toolCatalog.remoteSchemaTrust,
        mcp_tool_catalog_unpinned_tools: toolCatalog.unpinnedTools,
        mcp_tool_catalog_signature_verification_disabled: toolCatalog.signatureVerificationDisabled,
        mcp_tool_catalog_provenance_verification_disabled: toolCatalog.provenanceVerificationDisabled,
        mcp_tool_catalog_unreviewed_tools_allowed: toolCatalog.unreviewedToolsAllowed,
        mcp_tool_catalog_tool_authority_categories: toolCatalog.toolAuthorityCategories,
        mcp_tool_catalog_privileged_tool_authority: toolCatalog.privilegedToolAuthority,
        mcp_tool_catalog_write_authority: toolCatalog.writeAuthority,
        mcp_tool_catalog_external_authority: toolCatalog.externalAuthority,
        mcp_tool_catalog_memory_authority: toolCatalog.memoryAuthority,
        mcp_tool_catalog_secret_context: toolCatalog.secretContext,
        mcp_tool_catalog_shell_authority: toolCatalog.shellAuthority,
        mcp_tool_catalog_sensitive_context: toolCatalog.sensitiveContext,
        mcp_tool_catalog_pii_context: toolCatalog.piiContext,
        mcp_tool_catalog_approval_required: toolCatalog.approvalRequired,
        mcp_resource_subscription_detected: resourceSubscriptions.detected,
        mcp_resource_subscription_enabled: resourceSubscriptions.enabled,
        mcp_resource_subscription_source_redacted: resourceSubscriptions.sourceRedacted,
        mcp_resource_subscription_source_count: resourceSubscriptions.sourceCount,
        mcp_resource_subscription_source_kinds: resourceSubscriptions.sourceKinds,
        mcp_resource_subscription_dynamic_updates: resourceSubscriptions.dynamicUpdates,
        mcp_resource_subscription_auto_refresh: resourceSubscriptions.autoRefresh,
        mcp_resource_subscription_auto_include_context: resourceSubscriptions.autoIncludeContext,
        mcp_resource_subscription_model_visible_context: resourceSubscriptions.modelVisibleContext,
        mcp_resource_subscription_raw_content_passthrough: resourceSubscriptions.rawContentPassthrough,
        mcp_resource_subscription_untrusted_source: resourceSubscriptions.untrustedSource,
        mcp_resource_subscription_sanitization_disabled: resourceSubscriptions.sanitizationDisabled,
        mcp_resource_subscription_redaction_disabled: resourceSubscriptions.redactionDisabled,
        mcp_resource_subscription_prompt_injection_filter_disabled: resourceSubscriptions.promptInjectionFilterDisabled,
        mcp_resource_subscription_provenance_verification_disabled: resourceSubscriptions.provenanceVerificationDisabled,
        mcp_resource_subscription_authority_categories: resourceSubscriptions.authorityCategories,
        mcp_resource_subscription_privileged_bridge: resourceSubscriptions.privilegedBridge,
        mcp_resource_subscription_write_authority: resourceSubscriptions.writeAuthority,
        mcp_resource_subscription_external_authority: resourceSubscriptions.externalAuthority,
        mcp_resource_subscription_memory_authority: resourceSubscriptions.memoryAuthority,
        mcp_resource_subscription_secret_context: resourceSubscriptions.secretContext,
        mcp_resource_subscription_shell_authority: resourceSubscriptions.shellAuthority,
        mcp_resource_subscription_sensitive_context: resourceSubscriptions.sensitiveContext,
        mcp_resource_subscription_pii_context: resourceSubscriptions.piiContext,
        mcp_resource_subscription_approval_required: resourceSubscriptions.approvalRequired,
        values_collected: false,
        content_redacted: true
      }
    });
    const mcpSurface = {
      ...object,
      untrusted_to_privileged:
        (resourceSubscriptions.untrustedSource &&
          resourceSubscriptions.modelVisibleContext &&
          resourceSubscriptions.privilegedBridge &&
          !resourceSubscriptions.approvalRequired) ||
        isUntrustedToPrivileged(object)
    };
    surfaces.mcp_servers.push(mcpSurface);
    detectMcpContextSurfaces(file, server, mcpSurface, surfaces);
  }
}

async function detectPackageScripts(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): Promise<void> {
  if (!text) return;
  try {
    const parsed = JSON.parse(text) as PackageJsonLike;
    const scripts = parsed.scripts ?? {};
    detectAgentPackageManifestConfig(file, parsed, surfaces);
    for (const [scriptName, command] of Object.entries(scripts).sort(([a], [b]) => a.localeCompare(b))) {
      const actions = detectActions(command);
      const object = createSurfaceObject({
        type: "tool",
        name: `package-script:${scriptName}`,
        path: file.relativePath,
        data_classes: inferDataClasses(command, file.relativePath),
        actions: actions.length > 0 ? actions : ["execute"],
        side_effect: true,
        external_reach: hasExternalReach(command),
        secret_exposure: hasSecretExposure(command),
        reversible: isReversible(command),
        reason: "Package script discovered as shell-executable project authority.",
        metadata: {
          package_name: parsed.name,
          script_name: scriptName,
          ...redactedCommandSignals(command)
        }
      });
      surfaces.tools.push({
        ...object,
        untrusted_to_privileged: isUntrustedToPrivileged(object)
      });
    }
  } catch {
    addDiagnostic(surfaces, file, {
      parser: "json",
      code: "PACKAGE_JSON_PARSE_FAILED",
      reason: "package.json could not be parsed as JSON, so package script authority may be incomplete. Raw content was redacted."
    });
    return;
  }
}

interface PackageJsonLike {
  name?: string;
  private?: boolean;
  scripts?: Record<string, string>;
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  optionalDependencies?: Record<string, string>;
  peerDependencies?: Record<string, string>;
}

interface AgentPackageManifestPosture {
  package_manifest_fields: string[];
  package_manifest_dependency_names_redacted: boolean;
  package_manifest_dependency_specs_redacted: boolean;
  package_manifest_dependency_count: number;
  package_manifest_agent_dependency_count: number;
  package_manifest_agent_dependency_categories: string[];
  package_manifest_dependency_reference_kinds: string[];
  package_manifest_risky_dependency_count: number;
  package_manifest_unpinned_dependency: boolean;
  package_manifest_remote_dependency: boolean;
  package_manifest_lifecycle_script: boolean;
  package_manifest_lifecycle_script_names: string[];
  package_manifest_install_script_count: number;
  package_manifest_lifecycle_shell_execution: boolean;
  package_manifest_lifecycle_network_access: boolean;
  package_manifest_lifecycle_secret_env: boolean;
  package_manifest_agent_script_count: number;
  package_manifest_package_private?: boolean;
  env_key_names: string[];
  secret_ref_key_names: string[];
}

function detectAgentPackageManifestConfig(file: WalkedFile, manifest: PackageJsonLike, surfaces: DetectedSurfaces): void {
  const posture = classifyAgentPackageManifest(manifest);
  if (
    posture.package_manifest_agent_dependency_count === 0 &&
    !posture.package_manifest_lifecycle_script &&
    posture.package_manifest_agent_script_count === 0
  ) {
    return;
  }

  const actions = new Set<ActionType>(["read"]);
  if (posture.package_manifest_lifecycle_script) actions.add("execute");
  if (posture.package_manifest_remote_dependency || posture.package_manifest_lifecycle_network_access) actions.add("send");
  if (posture.package_manifest_lifecycle_script) actions.add("write");

  const dataClasses = new Set<SurfaceObject["data_classes"][number]>(["internal"]);
  if (posture.package_manifest_lifecycle_secret_env || posture.secret_ref_key_names.length > 0) {
    dataClasses.add("credential");
    dataClasses.add("secret");
  }

  const object = createSurfaceObject({
    type: "runtime_config",
    name: path.basename(file.relativePath),
    path: file.relativePath,
    trust_level: posture.package_manifest_remote_dependency ? "third_party" : inferTrustLevel(file.relativePath),
    data_classes: uniqueDataClasses([...dataClasses] as SurfaceObject["data_classes"]),
    actions: uniqueActions([...actions]),
    side_effect: posture.package_manifest_lifecycle_script,
    reversible: !posture.package_manifest_lifecycle_script,
    external_reach: posture.package_manifest_remote_dependency || posture.package_manifest_lifecycle_network_access,
    secret_exposure: posture.package_manifest_lifecycle_secret_env || posture.secret_ref_key_names.length > 0,
    reason: "Agent package manifest discovered as install-time dependency and lifecycle-script authority.",
    metadata: {
      content_redacted: true,
      values_collected: false,
      parsed_agent_package_manifest_config: true,
      ...posture
    }
  });
  surfaces.runtime_config.push({
    ...object,
    untrusted_to_privileged:
      (posture.package_manifest_agent_dependency_count > 0 &&
        posture.package_manifest_risky_dependency_count > 0 &&
        posture.package_manifest_lifecycle_script &&
        (posture.package_manifest_remote_dependency || posture.package_manifest_lifecycle_network_access)) ||
      isUntrustedToPrivileged(object)
  });
}

function classifyAgentPackageManifest(manifest: PackageJsonLike): AgentPackageManifestPosture {
  const dependencyEntries = collectPackageDependencyEntries(manifest);
  const agentDependencies = dependencyEntries.filter((entry) => agentDependencyCategories(entry.name).length > 0);
  const dependencyReferenceKinds = uniqueStrings(dependencyEntries.flatMap((entry) => packageDependencyReferenceKinds(entry.spec)));
  const riskyDependencies = agentDependencies.filter((entry) => packageDependencyReferenceKinds(entry.spec).some(isRiskyPackageReferenceKind));
  const scripts = manifest.scripts ?? {};
  const lifecycleScriptNames = Object.keys(scripts)
    .filter(isPackageLifecycleScriptName)
    .sort((a, b) => a.localeCompare(b));
  const lifecycleCommands = lifecycleScriptNames.map((scriptName) => scripts[scriptName] ?? "");
  const envKeys = uniqueStrings(extractEnvironmentReferenceKeys(lifecycleCommands));
  const secretRefKeys = uniqueStrings(extractSecretReferenceKeys(lifecycleCommands));
  const packageFields = new Set<string>();
  for (const section of ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"] as const) {
    if (manifest[section] && Object.keys(manifest[section] ?? {}).length > 0) packageFields.add(section);
  }
  if (manifest.scripts && Object.keys(manifest.scripts).length > 0) packageFields.add("scripts");
  for (const scriptName of lifecycleScriptNames) packageFields.add(`scripts.${scriptName}`);

  return {
    package_manifest_fields: [...packageFields].sort((a, b) => a.localeCompare(b)),
    package_manifest_dependency_names_redacted: dependencyEntries.length > 0,
    package_manifest_dependency_specs_redacted: dependencyEntries.length > 0,
    package_manifest_dependency_count: dependencyEntries.length,
    package_manifest_agent_dependency_count: agentDependencies.length,
    package_manifest_agent_dependency_categories: uniqueStrings(agentDependencies.flatMap((entry) => agentDependencyCategories(entry.name))),
    package_manifest_dependency_reference_kinds: dependencyReferenceKinds,
    package_manifest_risky_dependency_count: riskyDependencies.length,
    package_manifest_unpinned_dependency: dependencyReferenceKinds.some((kind) =>
      ["floating_range", "latest_tag", "workspace_range"].includes(kind)
    ),
    package_manifest_remote_dependency: dependencyReferenceKinds.some((kind) =>
      ["git_dependency", "http_tarball", "github_dependency"].includes(kind)
    ),
    package_manifest_lifecycle_script: lifecycleScriptNames.length > 0,
    package_manifest_lifecycle_script_names: lifecycleScriptNames,
    package_manifest_install_script_count: lifecycleScriptNames.length,
    package_manifest_lifecycle_shell_execution: lifecycleCommands.some(hasExecution),
    package_manifest_lifecycle_network_access: lifecycleCommands.some(hasExternalReach),
    package_manifest_lifecycle_secret_env: secretRefKeys.length > 0,
    package_manifest_agent_script_count: Object.keys(scripts).filter((scriptName) => /agent|mcp|llm|rag|eval|prompt|embed|vector/iu.test(scriptName)).length,
    package_manifest_package_private: manifest.private,
    env_key_names: envKeys,
    secret_ref_key_names: secretRefKeys
  };
}

function collectPackageDependencyEntries(manifest: PackageJsonLike): Array<{ section: string; name: string; spec: string }> {
  const entries: Array<{ section: string; name: string; spec: string }> = [];
  for (const section of ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"] as const) {
    for (const [name, spec] of Object.entries(manifest[section] ?? {})) {
      entries.push({ section, name, spec });
    }
  }
  return entries.sort((a, b) => `${a.section}:${a.name}`.localeCompare(`${b.section}:${b.name}`));
}

function agentDependencyCategories(packageName: string): string[] {
  const normalized = packageName.toLowerCase();
  const categories = new Set<string>();
  if (/modelcontextprotocol|mcp/iu.test(normalized)) categories.add("mcp_sdk");
  if (/langchain|langgraph|llamaindex|autogen|crewai|pydantic-ai|semantic-kernel|copilotkit/iu.test(normalized)) {
    categories.add("agent_framework");
  }
  if (/openai|anthropic|ai-sdk|@ai-sdk|cohere|mistral|groq|gemini|vertex|bedrock/iu.test(normalized)) categories.add("model_sdk");
  if (/pinecone|qdrant|weaviate|chroma|chromadb|milvus|pgvector|vector|rag|retrieval/iu.test(normalized)) {
    categories.add("rag_vector_store");
  }
  if (/playwright|puppeteer|browserbase|stagehand|browser-use/iu.test(normalized)) categories.add("browser_automation");
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function packageDependencyReferenceKinds(spec: string): string[] {
  const trimmed = spec.trim();
  const kinds = new Set<string>();
  if (!trimmed) return ["unknown_spec"];
  if (/^(?:github:|git\+|git:\/\/|ssh:\/\/|git@)/iu.test(trimmed)) kinds.add("git_dependency");
  if (/^https?:\/\//iu.test(trimmed)) kinds.add("http_tarball");
  if (/^[\w.-]+\/[\w.-]+(?:#.+)?$/u.test(trimmed)) kinds.add("github_dependency");
  if (/^(?:file:|\.\.?\/|\/)/iu.test(trimmed)) kinds.add("file_dependency");
  if (/^workspace:/iu.test(trimmed)) kinds.add("workspace_range");
  if (/^(?:latest|\*)$/iu.test(trimmed)) kinds.add("latest_tag");
  if (/[\^~*xX]|\|\||>=|<=|>|</u.test(trimmed)) kinds.add("floating_range");
  if (/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/u.test(trimmed)) kinds.add("exact_semver");
  if (kinds.size === 0) kinds.add("nonstandard_spec");
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function isRiskyPackageReferenceKind(kind: string): boolean {
  return ["floating_range", "git_dependency", "github_dependency", "http_tarball", "latest_tag", "nonstandard_spec", "workspace_range"].includes(kind);
}

function isPackageLifecycleScriptName(scriptName: string): boolean {
  return /^(preinstall|install|postinstall|prepare|prepublish|prepack|postpack)$/iu.test(scriptName);
}

function detectWorkflow(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): void {
  const content = text ?? "";
  let parsed: Record<string, unknown> = {};
  let parseFailed = false;
  try {
    parsed = (YAML.parse(content) ?? {}) as Record<string, unknown>;
  } catch {
    parseFailed = content.trim().length > 0;
    parsed = {};
  }
  if (parseFailed) {
    addDiagnostic(surfaces, file, {
      parser: "yaml",
      code: "WORKFLOW_PARSE_FAILED",
      reason: "GitHub Actions workflow could not be parsed as YAML. Text heuristics still ran with raw content redacted."
    });
  }
  const permissions = parsed.permissions;
  const actions = detectActions(content);
  const triggerNames = extractWorkflowTriggers(parsed.on);
  const writePermissions = hasWritePermissions(permissions);
  const mentionsSecretsContext = /secrets\./i.test(content);
  const runCommands = collectWorkflowRunCommands(parsed);
  const commandSignals = classifyWorkflowRunCommands(runCommands);
  const eventSignals = classifyWorkflowEventInput(triggerNames, parsed, content, commandSignals, runCommands);
  const untrustedEventPrivilegedBridge =
    eventSignals.untrusted_event_agent_input && (writePermissions || mentionsSecretsContext || commandSignals.agent_package_script_names.length > 0);
  const object = createSurfaceObject({
    type: "ci_cd",
    name: path.basename(file.relativePath),
    path: file.relativePath,
    trust_level: "project",
    data_classes: inferDataClasses(content, file.relativePath),
    actions: actions.length > 0 ? actions : ["execute"],
    side_effect: true,
    external_reach: hasExternalReach(content),
    secret_exposure: hasSecretExposure(content),
    reversible: isReversible(content),
    reason: "GitHub Actions workflow discovered as CI/CD authority.",
    metadata: {
      content_redacted: true,
      has_permissions_block: Boolean(permissions),
      trigger_names: triggerNames,
      parse_error: parseFailed,
      pull_request_trigger: triggerNames.some((trigger) => ["pull_request", "pull_request_target"].includes(trigger)),
      write_permissions: writePermissions,
      mentions_secrets_context: mentionsSecretsContext,
      ...commandSignals,
      ...eventSignals
    }
  });
  surfaces.ci_cd.push({
    ...object,
    untrusted_to_privileged: untrustedEventPrivilegedBridge || isUntrustedToPrivileged(object)
  });
  detectWorkflowAutomation(file, content, triggerNames, {
    actions,
    writePermissions,
    mentionsSecretsContext,
    commandSignals,
    eventSignals,
    permissions
  }, surfaces);
}

function detectWorkflowAutomation(
  file: WalkedFile,
  content: string,
  triggerNames: string[],
  workflow: {
    actions: ActionType[];
    writePermissions: boolean;
    mentionsSecretsContext: boolean;
    commandSignals: WorkflowCommandSignals;
    eventSignals: WorkflowEventInputSignals;
    permissions: unknown;
  },
  surfaces: DetectedSurfaces
): void {
  const automationTriggers = triggerNames.filter((trigger) =>
    [
      "discussion_comment",
      "issue_comment",
      "repository_dispatch",
      "schedule",
      "workflow_call",
      "workflow_dispatch",
      "workflow_run"
    ].includes(trigger)
  );
  if (automationTriggers.length === 0) return;

  const actions = uniqueActions([
    ...(workflow.actions.length > 0 ? workflow.actions : (["execute"] as ActionType[])),
    ...(workflow.writePermissions ? (["write"] as ActionType[]) : []),
    ...(workflow.mentionsSecretsContext ? (["call"] as ActionType[]) : [])
  ]);
  const object = createSurfaceObject({
    type: "automation",
    name: `workflow:${path.basename(file.relativePath)}`,
    path: file.relativePath,
    trust_level: "project",
    data_classes: workflow.mentionsSecretsContext ? ["credential"] : inferDataClasses(content, file.relativePath),
    actions,
    side_effect: true,
    external_reach: hasExternalReach(content) || automationTriggers.includes("repository_dispatch"),
    secret_exposure: workflow.mentionsSecretsContext,
    reversible: isReversible(content),
    reason: "GitHub Actions workflow trigger discovered as agent-relevant automation.",
    metadata: {
      content_redacted: true,
      trigger_names: triggerNames,
      automation_triggers: automationTriggers,
      scheduled: automationTriggers.includes("schedule"),
      manual_dispatch: automationTriggers.includes("workflow_dispatch"),
      external_dispatch: automationTriggers.includes("repository_dispatch"),
      workflow_run_trigger: automationTriggers.includes("workflow_run"),
      write_permissions: workflow.writePermissions,
      mentions_secrets_context: workflow.mentionsSecretsContext,
      ...workflow.commandSignals,
      ...workflow.eventSignals,
      has_permissions_block: Boolean(workflow.permissions)
    }
  });
  const untrustedEventPrivilegedBridge =
    workflow.eventSignals.untrusted_event_agent_input &&
    (workflow.writePermissions ||
      workflow.mentionsSecretsContext ||
      workflow.commandSignals.agent_package_script_names.length > 0 ||
      actions.some((action) => ["write", "execute", "publish", "send", "delete", "call"].includes(action)));
  surfaces.automations.push({
    ...object,
    untrusted_to_privileged: untrustedEventPrivilegedBridge || isUntrustedToPrivileged(object)
  });
}

function detectOpenApiToolSpec(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): boolean {
  const hasNamingSignal = hasOpenApiNamingSignal(file.relativePath, path.basename(file.relativePath));
  const parsed = parseStructuredConfig(text ?? "", file.relativePath);
  if (parsed.parseFailed) {
    if (!hasNamingSignal) return false;
    addDiagnostic(surfaces, file, {
      parser: parsed.parser ?? "structured_config",
      code: "OPENAPI_TOOL_SPEC_PARSE_FAILED",
      reason: "OpenAPI or Swagger tool specification could not be parsed. Raw content was redacted."
    });
    return true;
  }

  if (!isOpenApiDocument(parsed.value)) return false;

  const operations = extractOpenApiOperations(parsed.value, file.relativePath);
  if (operations.length === 0 && parsed.value !== undefined) {
    addDiagnostic(surfaces, file, {
      parser: parsed.parser ?? "structured_config",
      code: "OPENAPI_TOOL_SPEC_NO_OPERATIONS",
      reason: "OpenAPI or Swagger file did not contain agent-callable operations. Raw content was redacted.",
      severity: "info"
    });
    return true;
  }

  for (const operation of operations) {
    const actions = new Set<ActionType>(["call", "read"]);
    if (operation.openapi_external_operation) actions.add("send");
    if (operation.openapi_write_operation) actions.add("write");
    if (operation.openapi_destructive_operation) actions.add("delete");

    const dataClasses = new Set<SurfaceObject["data_classes"][number]>(["unknown"]);
    if (operation.openapi_authenticated_operation || operation.env_key_names.some(isCredentialLikeKeyName)) {
      dataClasses.add("credential");
    }
    if (operation.openapi_accepts_customer_data_input || operation.openapi_sensitive_input) dataClasses.add("confidential");
    if (operation.openapi_accepts_pii_like_input) dataClasses.add("pii");
    if (dataClasses.size > 1) dataClasses.delete("unknown");

    const object = createSurfaceObject({
      type: "tool",
      name: `openapi:${operation.openapi_method}:${operation.openapi_operation_index}`,
      path: file.relativePath,
      trust_level: operation.openapi_remote_server ? "third_party" : inferTrustLevel(file.relativePath),
      data_classes: uniqueDataClasses([...dataClasses] as SurfaceObject["data_classes"]),
      actions: uniqueActions([...actions]),
      side_effect: operation.openapi_write_operation || operation.openapi_destructive_operation,
      reversible: !operation.openapi_destructive_operation,
      external_reach: operation.openapi_external_operation,
      secret_exposure: operation.openapi_authenticated_operation || operation.env_key_names.some(isCredentialLikeKeyName),
      reason: "OpenAPI or Swagger specification discovered as an agent-importable API tool surface.",
      metadata: {
        content_redacted: true,
        values_collected: false,
        parsed_openapi_tool_spec: true,
        ...operation
      }
    });
    surfaces.tools.push({
      ...object,
      untrusted_to_privileged:
        (operation.openapi_agent_tool_import &&
          operation.openapi_user_controlled_input &&
          operation.openapi_authenticated_operation &&
          operation.openapi_write_operation &&
          operation.openapi_broad_or_sensitive_scope &&
          !operation.openapi_approval_required) ||
        isUntrustedToPrivileged(object)
    });
  }
  return true;
}

function detectToolDefinition(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): void {
  const content = text ?? "";
  const extraction = extractToolDefinitions(content);
  const toolDefinitions = extraction.definitions;
  if (extraction.parseFailed) {
    addDiagnostic(surfaces, file, {
      parser: "json_or_yaml",
      code: "TOOL_DEFINITION_PARSE_FAILED",
      reason: "Tool definition file could not be parsed as JSON or YAML. Text heuristics still ran with raw content redacted."
    });
  }
  if (toolDefinitions.length === 0) {
    const actions = detectActions(content);
    const object = createSurfaceObject({
      type: "tool",
      name: path.basename(file.relativePath),
      path: file.relativePath,
      data_classes: inferDataClasses(content, file.relativePath),
      actions: actions.length > 0 ? actions : ["call"],
      side_effect: true,
      external_reach: hasExternalReach(content),
      secret_exposure: hasSecretExposure(content),
      reversible: isReversible(content),
      reason: "Tool definition file discovered as agent-callable capability metadata.",
      metadata: { content_redacted: true, parsed_tool_schema: false, parse_error: extraction.parseFailed }
    });
    surfaces.tools.push({
      ...object,
      untrusted_to_privileged: isUntrustedToPrivileged(object)
    });
    return;
  }

  for (const definition of toolDefinitions) {
    addToolDefinitionSurface(file, surfaces, definition, "Tool schema discovered as agent-callable capability metadata.");
  }
}

function detectMcpSourceToolDefinitions(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): boolean {
  const content = text ?? "";
  if (!content.trim()) return false;

  const extraction = extractMcpSourceToolDefinitions(content, file.relativePath);
  if (!extraction.sourceDetected) return false;

  if (extraction.definitions.length === 0) {
    addDiagnostic(surfaces, file, {
      parser: "mcp_source",
      code: "MCP_SOURCE_TOOL_REGISTRATION_UNPARSED",
      reason: "MCP SDK source file contained tool registration signals, but no bounded registration shape could be normalized. Raw source was redacted.",
      severity: "info"
    });
    return true;
  }

  for (const definition of extraction.definitions) {
    addToolDefinitionSurface(
      file,
      surfaces,
      definition,
      "MCP SDK source-defined tool registration discovered as agent-callable capability metadata.",
      {
        parsed_mcp_source_tool: true,
        mcp_source_tool_registration: true,
        mcp_source_tool_registration_kind: definition.registrationKind,
        mcp_source_tool_argument_count: definition.argumentCount,
        mcp_source_tool_schema_styles: definition.schemaStyles,
        source_tool_schema_redacted: true,
        source_tool_handler_redacted: true,
        values_collected: false
      }
    );
  }

  return true;
}

function detectAgentFrameworkSourceToolDefinitions(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): boolean {
  const content = text ?? "";
  if (!content.trim()) return false;

  const extraction = extractAgentFrameworkSourceToolDefinitions(content, file.relativePath);
  if (!extraction.sourceDetected) return false;

  if (extraction.definitions.length === 0) {
    addDiagnostic(surfaces, file, {
      parser: "agent_framework_source",
      code: "AGENT_FRAMEWORK_SOURCE_TOOL_UNPARSED",
      reason: "Agent framework source file contained tool registration signals, but no bounded registration shape could be normalized. Raw source was redacted.",
      severity: "info"
    });
    return true;
  }

  for (const definition of extraction.definitions) {
    addToolDefinitionSurface(
      file,
      surfaces,
      definition,
      "Agent framework source-defined tool registration discovered as agent-callable capability metadata.",
      {
        parsed_agent_framework_source_tool: true,
        agent_framework_source_tool: true,
        agent_framework_source_tool_framework: definition.framework,
        agent_framework_source_tool_registration_kind: definition.registrationKind,
        agent_framework_source_tool_argument_count: definition.argumentCount,
        agent_framework_source_tool_schema_styles: definition.schemaStyles,
        source_tool_schema_redacted: true,
        source_tool_handler_redacted: true,
        values_collected: false
      }
    );
  }

  return true;
}

function addToolDefinitionSurface(
  file: WalkedFile,
  surfaces: DetectedSurfaces,
  definition: ExtractedToolDefinition,
  reason: string,
  metadata: Record<string, unknown> = {}
): void {
  const authority = classifyToolAuthority(definition);
  const modelVisibleDescription = classifyModelVisibleToolDescription(definition.description);
  const dataClasses: SurfaceObject["data_classes"] = authority.accepted_data_classes.length > 0
    ? uniqueDataClasses([
        ...(authority.secret_exposure ? ["credential"] : []),
        ...authority.accepted_data_classes
      ] as SurfaceObject["data_classes"])
    : authority.secret_exposure
      ? (["credential"] as SurfaceObject["data_classes"])
      : (["unknown"] as SurfaceObject["data_classes"]);
  const object = createSurfaceObject({
    type: "tool",
    name: definition.name,
    path: file.relativePath,
    data_classes: dataClasses,
    actions: authority.actions,
    side_effect: authority.side_effect,
    external_reach: authority.external_reach,
    secret_exposure: authority.secret_exposure,
    reversible:
      !authority.destructive_action &&
      !authority.external_write &&
      !authority.database_write &&
      !authority.memory_write &&
      !authority.agent_config_write &&
      !authority.credential_issuance &&
      !authority.nested_tool_invocation &&
      !authority.browser_automation &&
      !authority.secret_manager_access &&
      !authority.external_service_write &&
      !authority.model_provider_call &&
      !authority.embedding_provider_call &&
      !authority.tainted_network_destination &&
      !authority.tainted_shell_argument &&
      !authority.dynamic_code_execution &&
      !authority.tainted_dynamic_code_argument &&
      !authority.unsafe_deserialization &&
      !authority.tainted_deserialization_argument,
    reason,
    metadata: {
      tool_name: definition.name,
      description_redacted: true,
      parsed_tool_schema: true,
      authority_classes: authority.authority_classes,
      schema_properties: definition.schemaProperties,
      required_properties: definition.requiredProperties,
      accepts_secret_like_input: authority.accepts_secret_like_input,
      accepts_content_like_input: authority.accepts_content_like_input,
      accepts_path_input: authority.accepts_path_input,
      accepts_url_input: authority.accepts_url_input,
      accepts_pii_like_input: authority.accepts_pii_like_input,
      accepts_customer_data_input: authority.accepts_customer_data_input,
      accepted_data_classes: authority.accepted_data_classes,
      database_access: authority.database_access,
      database_write: authority.database_write,
      tainted_network_destination: authority.tainted_network_destination,
      tainted_database_query_argument: authority.tainted_database_query_argument,
      memory_write: authority.memory_write,
      tainted_memory_scope: authority.tainted_memory_scope,
      agent_config_write: authority.agent_config_write,
      credential_issuance: authority.credential_issuance,
      tainted_credential_issuance_input: authority.tainted_credential_issuance_input,
      nested_tool_invocation: authority.nested_tool_invocation,
      browser_automation: authority.browser_automation,
      tainted_browser_automation_target: authority.tainted_browser_automation_target,
      secret_manager_access: authority.secret_manager_access,
      tainted_secret_manager_path: authority.tainted_secret_manager_path,
      external_service_write: authority.external_service_write,
      tainted_external_service_recipient: authority.tainted_external_service_recipient,
      model_provider_call: authority.model_provider_call,
      tainted_model_selection: authority.tainted_model_selection,
      embedding_provider_call: authority.embedding_provider_call,
      tainted_embedding_input: authority.tainted_embedding_input,
      privileged_prompt_composition: authority.privileged_prompt_composition,
      tainted_shell_argument: authority.tainted_shell_argument,
      tainted_filesystem_path: authority.tainted_filesystem_path,
      network_response_capture: authority.network_response_capture,
      dynamic_code_execution: authority.dynamic_code_execution,
      tainted_dynamic_code_argument: authority.tainted_dynamic_code_argument,
      unsafe_deserialization: authority.unsafe_deserialization,
      tainted_deserialization_argument: authority.tainted_deserialization_argument,
      local_file_disclosure: authority.local_file_disclosure,
      external_write: authority.external_write,
      destructive_action: authority.destructive_action,
      read_only_hint: definition.annotations?.readOnlyHint,
      idempotent_hint: definition.annotations?.idempotentHint,
      read_only_hint_conflict: authority.read_only_hint_conflict,
      open_world_authority: authority.open_world_authority,
      open_world_schema: definition.openWorldSchema,
      ...sourceToolHandlerSignalMetadata(definition.handlerSignals),
      ...modelVisibleDescription,
      ...metadata
    }
  });
  surfaces.tools.push({
    ...object,
    untrusted_to_privileged: isUntrustedToPrivileged(object)
  });
}

function annotateToolNameCollisions(surfaces: DetectedSurfaces): void {
  const groups = new Map<string, SurfaceObject[]>();
  for (const tool of surfaces.tools) {
    const name = normalizeCallableName(tool.name);
    if (!name) continue;
    const existing = groups.get(name) ?? [];
    existing.push(tool);
    groups.set(name, existing);
  }

  surfaces.tools = surfaces.tools.map((tool) => {
    const collisionName = normalizeCallableName(tool.name);
    const peers = groups.get(collisionName) ?? [];
    if (peers.length < 2) return tool;

    const authoritySignatures = new Set(peers.map(authoritySignature));
    const hasPrivilegedPeer = peers.some(isPrivilegedToolSurface);
    return {
      ...tool,
      metadata: {
        ...tool.metadata,
        name_collision: true,
        collision_name: collisionName,
        collision_count: peers.length,
        collision_paths: peers.map((peer) => peer.path).sort((a, b) => a.localeCompare(b)),
        collision_trust_levels: [...new Set(peers.map((peer) => peer.trust_level))].sort((a, b) => a.localeCompare(b)),
        collision_authority_mismatch: authoritySignatures.size > 1,
        collision_has_privileged_peer: hasPrivilegedPeer
      }
    };
  });
}

function annotateRuntimeCapabilityReferences(surfaces: DetectedSurfaces): void {
  if (surfaces.runtime_config.length === 0 || surfaces.mcp_servers.length === 0) return;

  surfaces.runtime_config = surfaces.runtime_config.map((runtime) => {
    const allowedTools = stringMetadataArray(runtime.metadata.allowed_tools);
    const referencedMcpServers = referencedMcpServersForRuntime(allowedTools, surfaces.mcp_servers);
    if (referencedMcpServers.length === 0) return runtime;

    const privilegedMcpServers = referencedMcpServers.filter(isPrivilegedMcpServer);
    const secretBackedMcpServers = referencedMcpServers.filter(isSecretBackedMcpServer);
    const hasSecretBackedMcp = secretBackedMcpServers.length > 0;
    const hasPrivilegedMcp = privilegedMcpServers.length > 0;
    const approvalBypass = runtime.metadata.approval_bypass === true;
    const dataClasses = hasSecretBackedMcp ? uniqueDataClasses([...runtime.data_classes, "credential"]) : runtime.data_classes;

    return {
      ...runtime,
      data_classes: dataClasses,
      secret_exposure: runtime.secret_exposure || hasSecretBackedMcp,
      metadata: {
        ...runtime.metadata,
        referenced_mcp_servers: surfaceNames(referencedMcpServers),
        referenced_mcp_count: referencedMcpServers.length,
        referenced_privileged_mcp_servers: surfaceNames(privilegedMcpServers),
        referenced_privileged_mcp_count: privilegedMcpServers.length,
        referenced_secret_backed_mcp_servers: surfaceNames(secretBackedMcpServers),
        referenced_secret_backed_mcp_count: secretBackedMcpServers.length,
        mcp_runtime_bridge: referencedMcpServers.length > 0,
        privileged_mcp_runtime_bridge: hasPrivilegedMcp,
        secret_backed_mcp_runtime_bridge: hasSecretBackedMcp,
        approvalless_privileged_mcp_bridge: approvalBypass && hasPrivilegedMcp,
        approvalless_secret_mcp_bridge: approvalBypass && hasSecretBackedMcp
      }
    };
  });
}

function annotateWorkflowPackageScriptReferences(surfaces: DetectedSurfaces): void {
  const packageScriptTools = surfaces.tools
    .filter((tool) => typeof tool.metadata.script_name === "string")
    .sort((a, b) => a.name.localeCompare(b.name) || a.path.localeCompare(b.path));
  if (packageScriptTools.length === 0) return;

  const annotate = (surface: SurfaceObject): SurfaceObject => {
    const agentScriptNames = stringMetadataArray(surface.metadata.agent_package_script_names);
    if (agentScriptNames.length === 0) return surface;

    const agentScriptNameSet = new Set(agentScriptNames);
    const referencedPackageScripts = packageScriptTools.filter((tool) => agentScriptNameSet.has(String(tool.metadata.script_name)));
    if (referencedPackageScripts.length === 0) return surface;

    const agentPackageScripts = referencedPackageScripts.filter((tool) => isAgentPackageScriptName(String(tool.metadata.script_name)));
    return {
      ...surface,
      metadata: {
        ...surface.metadata,
        referenced_package_scripts: surfaceNames(referencedPackageScripts),
        referenced_package_script_count: referencedPackageScripts.length,
        referenced_agent_package_scripts: surfaceNames(agentPackageScripts),
        referenced_agent_package_script_count: agentPackageScripts.length,
        package_script_bridge: referencedPackageScripts.length > 0,
        agent_package_script_bridge: agentPackageScripts.length > 0
      }
    };
  };

  surfaces.ci_cd = surfaces.ci_cd.map(annotate);
  surfaces.automations = surfaces.automations.map(annotate);
}

function annotateRuntimePackageScriptReferences(surfaces: DetectedSurfaces): void {
  const packageScriptTools = surfaces.tools
    .filter((tool) => typeof tool.metadata.script_name === "string")
    .sort((a, b) => a.name.localeCompare(b.name) || a.path.localeCompare(b.path));
  if (packageScriptTools.length === 0 || surfaces.runtime_config.length === 0) return;

  surfaces.runtime_config = surfaces.runtime_config.map((runtime) => {
    const autoApprovedScriptNames = stringMetadataArray(runtime.metadata.auto_approved_package_script_names);
    if (autoApprovedScriptNames.length === 0) return runtime;

    const autoApprovedScriptNameSet = new Set(autoApprovedScriptNames);
    const referencedPackageScripts = packageScriptTools.filter((tool) =>
      autoApprovedScriptNameSet.has(String(tool.metadata.script_name))
    );
    if (referencedPackageScripts.length === 0) return runtime;

    const releasePackageScripts = referencedPackageScripts.filter((tool) => tool.metadata.release_or_publish === true);
    return {
      ...runtime,
      metadata: {
        ...runtime.metadata,
        referenced_package_scripts: surfaceNames(referencedPackageScripts),
        referenced_package_script_count: referencedPackageScripts.length,
        referenced_auto_approved_package_scripts: surfaceNames(referencedPackageScripts),
        referenced_auto_approved_package_script_count: referencedPackageScripts.length,
        referenced_release_package_scripts: surfaceNames(releasePackageScripts),
        referenced_release_package_script_count: releasePackageScripts.length,
        auto_approved_package_script_bridge: referencedPackageScripts.length > 0,
        auto_approved_release_package_script_bridge: releasePackageScripts.length > 0
      }
    };
  });
}

function annotateContextCallableReferences(
  surfaces: DetectedSurfaces,
  contextContentByPath: Map<string, string>
): void {
  if (contextContentByPath.size === 0) return;

  const toolCandidates = callableCandidates(surfaces.tools, toolAliases);
  const mcpCandidates = callableCandidates(surfaces.mcp_servers, (server) => [server.name]);
  if (toolCandidates.length === 0 && mcpCandidates.length === 0) return;

  const annotate = (surface: SurfaceObject): SurfaceObject => {
    if (isHeuristicSurface(surface)) return surface;
    const content = contextContentByPath.get(surface.path);
    if (!content) return surface;

    const referencedTools = referencedCallableSurfaces(content, toolCandidates);
    const referencedMcpServers = referencedCallableSurfaces(content, mcpCandidates);
    if (referencedTools.length === 0 && referencedMcpServers.length === 0) return surface;

    const privilegedTools = referencedTools.filter(isPrivilegedToolSurface);
    const privilegedMcpServers = referencedMcpServers.filter(isPrivilegedMcpServer);
    const hasPrivilegedReference = privilegedTools.length > 0 || privilegedMcpServers.length > 0;
    return {
      ...surface,
      untrusted_to_privileged: surface.untrusted_to_privileged || hasPrivilegedReference,
      metadata: {
        ...surface.metadata,
        referenced_tools: surfaceNames(referencedTools),
        referenced_tool_count: referencedTools.length,
        referenced_privileged_tools: surfaceNames(privilegedTools),
        referenced_privileged_tool_count: privilegedTools.length,
        referenced_mcp_servers: surfaceNames(referencedMcpServers),
        referenced_mcp_count: referencedMcpServers.length,
        referenced_privileged_mcp_servers: surfaceNames(privilegedMcpServers),
        referenced_privileged_mcp_count: privilegedMcpServers.length,
        explicit_tool_reference: referencedTools.length > 0,
        explicit_mcp_reference: referencedMcpServers.length > 0,
        explicit_callable_reference: referencedTools.length > 0 || referencedMcpServers.length > 0,
        privileged_callable_reference: hasPrivilegedReference
      }
    };
  };

  surfaces.instructions = surfaces.instructions.map(annotate);
  surfaces.skills = surfaces.skills.map(annotate);
  surfaces.prompts = surfaces.prompts.map(annotate);
  surfaces.rag_sources = surfaces.rag_sources.map(annotate);
  surfaces.memory = surfaces.memory.map(annotate);
}

interface CallableCandidate {
  surface: SurfaceObject;
  aliases: string[];
}

function callableCandidates(
  surfaces: SurfaceObject[],
  aliasesForSurface: (surface: SurfaceObject) => Array<string | undefined>
): CallableCandidate[] {
  return surfaces
    .map((surface) => ({
      surface,
      aliases: uniqueStrings(
        aliasesForSurface(surface)
          .filter((value): value is string => typeof value === "string" && value.trim().length > 0)
          .map(normalizeCallableName)
          .filter((value) => value.length >= 4)
      )
    }))
    .filter((candidate) => candidate.aliases.length > 0)
    .sort((a, b) => a.surface.name.localeCompare(b.surface.name) || a.surface.path.localeCompare(b.surface.path));
}

function toolAliases(tool: SurfaceObject): Array<string | undefined> {
  return [
    tool.name,
    typeof tool.metadata.tool_name === "string" ? tool.metadata.tool_name : undefined,
    typeof tool.metadata.script_name === "string" ? tool.metadata.script_name : undefined
  ];
}

function referencedCallableSurfaces(content: string, candidates: CallableCandidate[]): SurfaceObject[] {
  const normalizedContent = `_${normalizeCallableName(content)}_`;
  return candidates
    .filter((candidate) => candidate.aliases.some((alias) => normalizedContent.includes(`_${alias}_`)))
    .map((candidate) => candidate.surface)
    .sort((a, b) => a.name.localeCompare(b.name) || a.path.localeCompare(b.path));
}

function referencedMcpServersForRuntime(allowedTools: string[], mcpServers: SurfaceObject[]): SurfaceObject[] {
  const allowAllTools = allowedTools.some((tool) => /(^|\s|\*)\*(\s|$)|all_tools|all-tools|all tools/iu.test(tool));
  const mcpReferences = new Set<string>();

  for (const tool of allowedTools) {
    const normalized = tool.trim().toLowerCase();
    const match = normalized.match(/^mcp[:/](.+)$/iu);
    if (match?.[1]) mcpReferences.add(normalizeCallableName(match[1]));
  }

  return mcpServers
    .filter((server) => allowAllTools || mcpReferences.has(normalizeCallableName(server.name)))
    .sort((a, b) => a.name.localeCompare(b.name) || a.path.localeCompare(b.path));
}

function isPrivilegedMcpServer(server: SurfaceObject): boolean {
  return (
    server.side_effect ||
    server.external_reach ||
    server.secret_exposure ||
    !server.reversible ||
    server.actions.some((action) => ["write", "execute", "publish", "send", "delete", "remember", "call"].includes(action))
  );
}

function isSecretBackedMcpServer(server: SurfaceObject): boolean {
  return (
    server.secret_exposure ||
    server.data_classes.some((dataClass) => dataClass === "credential" || dataClass === "secret") ||
    stringMetadataArray(server.metadata.env_key_names).length > 0 ||
    stringMetadataArray(server.metadata.secret_ref_key_names).length > 0 ||
    stringMetadataArray(server.metadata.auth_header_names).length > 0
  );
}

function stringMetadataArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is string => typeof item === "string").sort((a, b) => a.localeCompare(b));
}

function isHeuristicSurface(surface: SurfaceObject): boolean {
  return surface.metadata.heuristic === true;
}

function surfaceNames(surfaces: SurfaceObject[]): string[] {
  return [...new Set(surfaces.map((surface) => surface.name))].sort((a, b) => a.localeCompare(b));
}

function uniqueDataClasses(values: SurfaceObject["data_classes"]): SurfaceObject["data_classes"] {
  return [...new Set(values)].sort((a, b) => a.localeCompare(b));
}

function contextualDataClasses(
  baseClasses: SurfaceObject["data_classes"],
  signals: ContextContentSignals
): SurfaceObject["data_classes"] {
  const classes = new Set(baseClasses);
  if (signals.secret_reference) classes.add("credential");
  if (signals.sensitive_context_reference || signals.data_egress_directive) classes.add("confidential");
  if (classes.size > 1) classes.delete("unknown");
  return uniqueDataClasses([...classes] as SurfaceObject["data_classes"]);
}

interface WorkflowCommandSignals {
  run_commands_redacted: boolean;
  run_command_count: number;
  package_manager_run: boolean;
  agent_run_command: boolean;
  agent_package_script_names: string[];
  command_redacted: boolean;
  command_signals?: unknown;
  network_to_shell?: unknown;
  release_or_publish?: unknown;
  destructive_command?: unknown;
}

interface WorkflowEventInputSignals {
  untrusted_event_trigger: boolean;
  untrusted_event_triggers: string[];
  untrusted_event_payload_used: boolean;
  untrusted_event_payload_sources: string[];
  untrusted_event_payload_source_count: number;
  untrusted_event_payload_redacted: boolean;
  untrusted_event_context_env_keys: string[];
  untrusted_event_context_env_key_count: number;
  untrusted_event_agent_input: boolean;
  untrusted_event_shell_argument: boolean;
  untrusted_event_shell_argument_env_keys: string[];
  untrusted_event_shell_argument_env_key_count: number;
}

function collectWorkflowRunCommands(value: unknown): string[] {
  const commands: string[] = [];
  collectWorkflowRunCommandsInto(value, commands);
  return commands;
}

function collectWorkflowRunCommandsInto(value: unknown, commands: string[]): void {
  if (Array.isArray(value)) {
    for (const item of value) collectWorkflowRunCommandsInto(item, commands);
    return;
  }
  if (!value || typeof value !== "object") return;

  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (key === "run" && typeof item === "string") {
      commands.push(item);
      continue;
    }
    collectWorkflowRunCommandsInto(item, commands);
  }
}

function classifyWorkflowRunCommands(commands: string[]): WorkflowCommandSignals {
  const joined = commands.join("\n");
  const commandSignals = redactedCommandSignals(joined);
  const agentScriptNames = extractAgentPackageScriptNames(joined);
  return {
    run_commands_redacted: true,
    run_command_count: commands.length,
    package_manager_run: /\b(npm|pnpm|yarn|bun)\b/iu.test(joined),
    agent_run_command: agentScriptNames.length > 0 || /\b(agent|codex|claude|mcp|assistant|bot)\b/iu.test(joined),
    agent_package_script_names: agentScriptNames,
    command_redacted: true,
    ...commandSignals
  };
}

function classifyWorkflowEventInput(
  triggerNames: string[],
  parsedWorkflow: unknown,
  content: string,
  commandSignals: WorkflowCommandSignals,
  runCommands: string[]
): WorkflowEventInputSignals {
  const eventTriggers = triggerNames.filter(isUntrustedWorkflowEventTrigger);
  const payloadSources = classifyWorkflowEventPayloadSources(content);
  const untrustedPayloadSources = payloadSources.filter((source) => source !== "workflow_dispatch_input");
  const eventEnvKeys = collectWorkflowEventInputEnvKeys(parsedWorkflow);
  const shellArgumentEnvKeys = collectWorkflowEventShellArgumentEnvKeys(runCommands, eventEnvKeys);
  const payloadUsed = untrustedPayloadSources.length > 0;
  return {
    untrusted_event_trigger: eventTriggers.length > 0,
    untrusted_event_triggers: eventTriggers,
    untrusted_event_payload_used: payloadUsed,
    untrusted_event_payload_sources: untrustedPayloadSources,
    untrusted_event_payload_source_count: untrustedPayloadSources.length,
    untrusted_event_payload_redacted: payloadUsed,
    untrusted_event_context_env_keys: eventEnvKeys,
    untrusted_event_context_env_key_count: eventEnvKeys.length,
    untrusted_event_agent_input: payloadUsed && commandSignals.agent_run_command,
    untrusted_event_shell_argument: shellArgumentEnvKeys.length > 0,
    untrusted_event_shell_argument_env_keys: shellArgumentEnvKeys,
    untrusted_event_shell_argument_env_key_count: shellArgumentEnvKeys.length
  };
}

function isUntrustedWorkflowEventTrigger(triggerName: string): boolean {
  return [
    "discussion",
    "discussion_comment",
    "issue_comment",
    "issues",
    "pull_request",
    "pull_request_review",
    "pull_request_target",
    "repository_dispatch"
  ].includes(triggerName);
}

function classifyWorkflowEventPayloadSources(content: string): string[] {
  const sources = new Set<string>();
  if (/github\.event\.comment\.body/iu.test(content)) sources.add("issue_comment_body");
  if (/github\.event\.issue\.(body|title)/iu.test(content)) sources.add("issue_text");
  if (/github\.event\.pull_request\.(body|title)/iu.test(content)) sources.add("pull_request_text");
  if (/github\.event\.review\.body/iu.test(content)) sources.add("pull_request_review_body");
  if (/github\.event\.discussion\.(body|title)/iu.test(content)) sources.add("discussion_text");
  if (/github\.event\.client_payload(?:\.|[\s}])|github\.event\.client_payload$/iu.test(content)) {
    sources.add("repository_dispatch_payload");
  }
  if (/github\.event\.inputs(?:\.|[\s}])|\binputs\.[A-Za-z_][\w-]*/u.test(content)) sources.add("workflow_dispatch_input");
  return [...sources].sort((a, b) => a.localeCompare(b));
}

function collectWorkflowEventInputEnvKeys(value: unknown): string[] {
  const keys = new Set<string>();
  collectWorkflowEventInputEnvKeysInto(value, keys);
  return [...keys].sort((a, b) => a.localeCompare(b));
}

function collectWorkflowEventShellArgumentEnvKeys(runCommands: string[], envKeys: string[]): string[] {
  if (runCommands.length === 0 || envKeys.length === 0) return [];
  const commandText = runCommands.join("\n");
  const matched = envKeys.filter((envKey) => {
    const escaped = escapeRegExp(envKey);
    return new RegExp(String.raw`(?:^|[\s"'=])--?[A-Za-z0-9][\w-]*(?:[=\s]+["']?\$\{?${escaped}\}?|\s+["']?\$\{?${escaped}\}?)`, "u").test(
      commandText
    ) || new RegExp(String.raw`(?:^|[\s"'])\$\{?${escaped}\}?(?:[\s"']|$)`, "u").test(commandText);
  });
  return matched.sort((a, b) => a.localeCompare(b));
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

function collectWorkflowEventInputEnvKeysInto(value: unknown, keys: Set<string>): void {
  if (Array.isArray(value)) {
    for (const item of value) collectWorkflowEventInputEnvKeysInto(item, keys);
    return;
  }
  if (!value || typeof value !== "object") return;

  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (key === "env" && item && typeof item === "object" && !Array.isArray(item)) {
      for (const [envKey, envValue] of Object.entries(item as Record<string, unknown>)) {
        if (typeof envValue === "string" && classifyWorkflowEventPayloadSources(envValue).length > 0) {
          keys.add(envKey);
        }
      }
    }
    collectWorkflowEventInputEnvKeysInto(item, keys);
  }
}

function extractAgentPackageScriptNames(commandText: string): string[] {
  return extractPackageScriptNames(commandText).filter(isAgentPackageScriptName);
}

function extractPackageScriptNames(commandText: string): string[] {
  const names = new Set<string>();
  const patterns = [
    /\bnpm\s+run\s+([a-zA-Z0-9][\w:.-]*)/giu,
    /\b(?:pnpm|yarn|bun)\s+(?:run\s+)?([a-zA-Z0-9][\w:.-]*)/giu
  ];

  for (const pattern of patterns) {
    for (const match of commandText.matchAll(pattern)) {
      if (match[1]) names.add(match[1]);
    }
  }

  return [...names].sort((a, b) => a.localeCompare(b));
}

function isAgentPackageScriptName(name: string): boolean {
  return /\b(agent|codex|claude|mcp|assistant|bot|autogen|crew|langgraph)\b/iu.test(name.replace(/[:._-]/g, " "));
}

function detectRuntimeConfig(file: WalkedFile, text: string | undefined, surfaces: DetectedSurfaces): void {
  const parseResult = parseRuntimeConfig(text ?? "", file.relativePath);
  if (parseResult.parseFailed) {
    addDiagnostic(surfaces, file, {
      parser: parseResult.parser ?? "runtime_config",
      code: "RUNTIME_CONFIG_PARSE_FAILED",
      reason: "Agent runtime configuration could not be parsed. Raw content was redacted."
    });
  }
  if (!parseResult.value) {
    const object = createSurfaceObject({
      type: "runtime_config",
      name: path.basename(file.relativePath),
      path: file.relativePath,
      actions: ["call"],
      reason: "Agent runtime configuration file discovered but not parsed.",
      metadata: {
        content_redacted: true,
        parsed_runtime_config: false,
        parse_error: parseResult.parseFailed,
        skipped_for_size: file.skippedForSize
      }
    });
    surfaces.runtime_config.push(object);
    return;
  }

  const posture = classifyRuntimeConfig(parseResult.value);
  const actions = new Set<"read" | "write" | "execute" | "publish" | "send" | "delete" | "remember" | "call">(["call"]);
  if (posture.privileged_tool_signals.some((signal) => ["shell", "terminal", "exec"].includes(signal))) actions.add("execute");
  if (posture.network_enabled) actions.add("send");
  if (posture.sandbox_disabled || posture.workspace_write) actions.add("write");

  const object = createSurfaceObject({
    type: "runtime_config",
    name: path.basename(file.relativePath),
    path: file.relativePath,
    data_classes: posture.secret_env_exposure ? ["credential"] : ["unknown"],
    actions: [...actions].sort((a, b) => a.localeCompare(b)),
    side_effect:
      posture.sandbox_disabled ||
      posture.approval_bypass ||
      posture.network_enabled ||
      posture.privileged_tools_allowed ||
      posture.secret_env_exposure,
    external_reach: posture.network_enabled || posture.privileged_tool_signals.some((signal) => ["browser", "github", "slack", "email"].includes(signal)),
    secret_exposure: posture.secret_env_exposure,
    reason: "Agent runtime configuration discovered as policy-relevant execution posture.",
    metadata: {
      content_redacted: true,
      parsed_runtime_config: true,
      runtime_fields: posture.runtime_fields,
      sandbox_mode: posture.sandbox_mode,
      sandbox_disabled: posture.sandbox_disabled,
      workspace_write: posture.workspace_write,
      approval_policy: posture.approval_policy,
      approval_bypass: posture.approval_bypass,
      network_access: posture.network_access,
      network_enabled: posture.network_enabled,
      allowed_tools: posture.allowed_tools,
      disabled_tools: posture.disabled_tools,
      permission_allowlist: posture.permission_allowlist,
      permission_denylist: posture.permission_denylist,
      auto_approved_package_script_names: posture.auto_approved_package_script_names,
      auto_approved_mcp_servers: posture.auto_approved_mcp_servers,
      auto_approved_mcp_tool_refs: posture.auto_approved_mcp_tool_refs,
      auto_approved_mcp_tool_count: posture.auto_approved_mcp_tool_count,
      auto_approved_destructive_mcp_servers: posture.auto_approved_destructive_mcp_servers,
      auto_approved_destructive_mcp_tool_refs: posture.auto_approved_destructive_mcp_tool_refs,
      auto_approved_destructive_mcp_tool_count: posture.auto_approved_destructive_mcp_tool_count,
      auto_approved_destructive_mcp_tools: posture.auto_approved_destructive_mcp_tools,
      auto_approved_network_tools: posture.auto_approved_network_tools,
      auto_approved_network_scope_kinds: posture.auto_approved_network_scope_kinds,
      auto_approved_network_scope_count: posture.auto_approved_network_scope_count,
      auto_approved_wildcard_network_scope: posture.auto_approved_wildcard_network_scope,
      auto_approved_unscoped_network_tool: posture.auto_approved_unscoped_network_tool,
      auto_approved_broad_network_scope: posture.auto_approved_broad_network_scope,
      auto_approved_tools_redacted: posture.auto_approved_tools_redacted,
      auto_approved_tool_count: posture.auto_approved_tool_count,
      auto_approved_privileged_tool_count: posture.auto_approved_privileged_tool_count,
      auto_approved_privileged_tool_signal_count: posture.auto_approved_privileged_tool_signal_count,
      auto_approved_privileged_tools: posture.auto_approved_privileged_tools,
      auto_approved_privileged_tool_signals: posture.auto_approved_privileged_tool_signals,
      privileged_tools_allowed: posture.privileged_tools_allowed,
      privileged_tool_signals: posture.privileged_tool_signals,
      env_key_names: posture.env_key_names,
      secret_env_exposure: posture.secret_env_exposure,
      secret_values_collected: false
    }
  });
  surfaces.runtime_config.push({
    ...object,
    untrusted_to_privileged: isUntrustedToPrivileged(object)
  });
}

interface ExtractedMcpServer {
  name: string;
  command?: string;
  args?: string[];
  envKeys?: string[];
  envExposure: McpEnvironmentExposure;
  transport?: string;
  remote: boolean;
  remoteHost?: string;
  remoteScheme?: string;
  headerNames?: string[];
  authHeaderNames?: string[];
  secretRefKeys?: string[];
  packageRunner?: McpPackageRunnerSignal;
  localCommandPaths?: string[];
  clientContext: McpClientContextPosture;
  toolCatalog: McpToolCatalogPosture;
  resourceSubscriptions: McpResourceSubscriptionPosture;
  contextSurfaces: McpContextDefinition[];
}

interface McpEnvironmentExposure {
  explicitEnvKeys: string[];
  passthrough: boolean;
  passthroughAll: boolean;
  passthroughSecretRisk: boolean;
  passthroughSourceKinds: string[];
  passthroughPatternCount: number;
}

interface McpClientContextPosture {
  rootsRedacted: boolean;
  rootCount: number;
  rootScopeKinds: string[];
  rootBroadScope: boolean;
  rootCredentialScope: boolean;
  rootHostScope: boolean;
  rootSensitiveScope: boolean;
  rootApprovalRequired: boolean;
  samplingEnabled: boolean;
  samplingIncludesContext: boolean;
  samplingContextKinds: string[];
  samplingSensitiveContext: boolean;
  samplingRedactionDisabled: boolean;
  samplingPromptInjectionFilterDisabled: boolean;
  samplingApprovalRequired: boolean;
  elicitationEnabled: boolean;
  elicitationSensitiveFields: boolean;
  elicitationSensitiveFieldCount: number;
  elicitationSensitiveFieldKinds: string[];
  elicitationRedactionDisabled: boolean;
  elicitationSanitizationDisabled: boolean;
  elicitationApprovalRequired: boolean;
  contextRequestAuthority: boolean;
  clientContextExposure: boolean;
}

interface McpToolCatalogPosture {
  detected: boolean;
  enabled: boolean;
  sourceRedacted: boolean;
  sourceCount: number;
  sourceKinds: string[];
  dynamicDiscovery: boolean;
  autoRefresh: boolean;
  modelVisibleDescriptions: boolean;
  remoteSchemaTrust: boolean;
  unpinnedTools: boolean;
  signatureVerificationDisabled: boolean;
  provenanceVerificationDisabled: boolean;
  unreviewedToolsAllowed: boolean;
  toolAuthorityCategories: string[];
  privilegedToolAuthority: boolean;
  writeAuthority: boolean;
  externalAuthority: boolean;
  memoryAuthority: boolean;
  secretContext: boolean;
  shellAuthority: boolean;
  sensitiveContext: boolean;
  piiContext: boolean;
  approvalRequired: boolean;
}

interface McpResourceSubscriptionPosture {
  detected: boolean;
  enabled: boolean;
  sourceRedacted: boolean;
  sourceCount: number;
  sourceKinds: string[];
  dynamicUpdates: boolean;
  autoRefresh: boolean;
  autoIncludeContext: boolean;
  modelVisibleContext: boolean;
  rawContentPassthrough: boolean;
  untrustedSource: boolean;
  sanitizationDisabled: boolean;
  redactionDisabled: boolean;
  promptInjectionFilterDisabled: boolean;
  provenanceVerificationDisabled: boolean;
  authorityCategories: string[];
  privilegedBridge: boolean;
  writeAuthority: boolean;
  externalAuthority: boolean;
  memoryAuthority: boolean;
  secretContext: boolean;
  shellAuthority: boolean;
  sensitiveContext: boolean;
  piiContext: boolean;
  approvalRequired: boolean;
}

interface McpContextDefinition {
  kind: "prompt" | "resource";
  index: number;
  sourceField: string;
  content: string;
  uriRedacted: boolean;
  nameRedacted: boolean;
  envKeys: string[];
  secretRefKeys: string[];
}

function detectMcpContextSurfaces(
  file: WalkedFile,
  server: ExtractedMcpServer,
  serverSurface: SurfaceObject,
  surfaces: DetectedSurfaces
): void {
  if (server.contextSurfaces.length === 0) return;

  for (const context of server.contextSurfaces) {
    const signals = classifyContextContent(context.content);
    const serverPrivileged = isPrivilegedMcpServer(serverSurface);
    const serverSecretBacked = isSecretBackedMcpServer(serverSurface);
    const actions = new Set<ActionType>(promptActions(signals));
    if (serverPrivileged && signals.tool_directive) actions.add("call");
    if (signals.external_directive || serverSurface.external_reach) actions.add("send");

    const dataClasses = new Set<SurfaceObject["data_classes"][number]>(
      contextualDataClasses(inferDataClasses(context.content, file.relativePath), signals)
    );
    if (serverSecretBacked || context.secretRefKeys.length > 0) {
      dataClasses.add("credential");
      dataClasses.add("secret");
    }
    if (signals.sensitive_context_reference || signals.data_egress_directive) dataClasses.add("confidential");

    const object = createSurfaceObject({
      type: "prompt",
      name: `mcp-context:${server.name}:${context.kind}:${context.index + 1}`,
      path: file.relativePath,
      trust_level: serverSurface.trust_level,
      data_classes: uniqueDataClasses([...dataClasses] as SurfaceObject["data_classes"]),
      actions: uniqueActions([...actions]),
      side_effect: serverPrivileged && signals.context_bridge_privileged,
      reversible: isReversible(context.content),
      external_reach: serverSurface.external_reach || signals.external_directive,
      secret_exposure: serverSecretBacked || context.secretRefKeys.length > 0 || signals.secret_reference,
      reason: "MCP prompt or resource content discovered as model-visible context.",
      metadata: {
        content_redacted: true,
        values_collected: false,
        mcp_context_surface: true,
        mcp_context_kind: context.kind,
        mcp_context_source_field: context.sourceField,
        mcp_context_server_name: server.name,
        mcp_context_server_remote: serverSurface.metadata.remote === true,
        mcp_context_server_plaintext_remote: serverSurface.metadata.plaintext_remote_transport === true,
        mcp_context_server_privileged: serverPrivileged,
        mcp_context_server_secret_backed: serverSecretBacked,
        mcp_context_uri_redacted: context.uriRedacted,
        mcp_context_name_redacted: context.nameRedacted,
        mcp_context_content_analyzed: context.content.trim().length > 0,
        env_key_names: uniqueStrings([
          ...context.envKeys,
          ...stringMetadataArray(serverSurface.metadata.env_key_names)
        ]),
        secret_ref_key_names: uniqueStrings([
          ...context.secretRefKeys,
          ...stringMetadataArray(serverSurface.metadata.secret_ref_key_names)
        ]),
        ...signals
      }
    });

    surfaces.prompts.push({
      ...object,
      untrusted_to_privileged:
        (serverPrivileged && signals.untrusted_context_reference && signals.context_bridge_privileged) ||
        isUntrustedToPrivileged(object)
    });
  }
}

function extractMcpServers(value: unknown): ExtractedMcpServer[] {
  if (!value || typeof value !== "object") return [];
  const root = value as Record<string, unknown>;
  const container = (root.mcpServers ?? root.servers) as Record<string, unknown> | undefined;
  if (!container || typeof container !== "object") return [];
  return Object.entries(container).map(([name, config]) => {
    const serverConfig = (config ?? {}) as Record<string, unknown>;
    const envExposure = classifyMcpEnvironmentExposure(serverConfig);
    const args = Array.isArray(serverConfig.args) ? serverConfig.args.filter((arg): arg is string => typeof arg === "string") : [];
    const command = typeof serverConfig.command === "string" ? serverConfig.command : undefined;
    const url = typeof serverConfig.url === "string" ? serverConfig.url : typeof serverConfig.endpoint === "string" ? serverConfig.endpoint : undefined;
    const remoteUrl = parseMcpRemoteUrl(url);
    const transport = typeof serverConfig.transport === "string" ? serverConfig.transport : remoteUrl ? "http" : undefined;
    const headers = serverConfig.headers && typeof serverConfig.headers === "object" ? (serverConfig.headers as Record<string, unknown>) : {};
    const headerNames = Object.keys(headers).sort((a, b) => a.localeCompare(b));
    const authHeaderNames = headerNames.filter((header) => /authorization|api[-_]?key|token|secret|credential|cookie/i.test(header));
    const packageRunner = classifyMcpPackageRunner(command, args);
    const localCommandPaths = extractLocalMcpCommandPathRefs(command, args);
    const secretRefKeys = [
      ...extractSecretReferenceKeys(Object.values(headers)),
      ...extractSecretReferenceKeys([url, ...args])
    ].sort((a, b) => a.localeCompare(b));
    return {
      name,
      command,
      args,
      envKeys: envExposure.explicitEnvKeys,
      envExposure,
      transport,
      remote: Boolean(remoteUrl),
      remoteHost: remoteUrl?.host,
      remoteScheme: remoteUrl?.scheme,
      headerNames,
      authHeaderNames,
      secretRefKeys,
      packageRunner,
      localCommandPaths,
      clientContext: classifyMcpClientContext(serverConfig),
      toolCatalog: classifyMcpToolCatalog(serverConfig),
      resourceSubscriptions: classifyMcpResourceSubscriptions(serverConfig),
      contextSurfaces: extractMcpContextDefinitions(serverConfig)
    };
  });
}

function classifyMcpEnvironmentExposure(serverConfig: Record<string, unknown>): McpEnvironmentExposure {
  const explicitEnvKeys = collectExplicitMcpEnvKeys(serverConfig.env);
  const fields = flattenRuntimeFields(serverConfig);
  const sourceKinds = new Set<string>();
  let passthroughPatternCount = 0;

  for (const field of fields) {
    const pathText = field.path.toLowerCase();
    const valueText = fieldValueText(field).toLowerCase();
    const combined = `${pathText} ${valueText}`;
    const patternCount = countEnvPassthroughPatterns(field.value);
    const envPath =
      /(?:^|\.)(env|environment|env_vars|envvars|environment_variables|allowed_env|allow_env|include_env|forward_env|pass_env|inherit_env|env_passthrough|environment_passthrough|pass_environment|all_env)$/iu.test(
        field.path
      ) || /env|environment/iu.test(field.path);
    if (!envPath) continue;

    if (/(?:^|[_\W])(process\.env|all[_\s-]?env|all[_\s-]?environment|inherit[_\s-]?env|pass[_\s-]?env|env[_\s-]?passthrough|environment[_\s-]?passthrough|pass[_\s-]?environment)(?:[_\W]|$)/iu.test(combined)) {
      sourceKinds.add("process_env");
    }
    if (/(?:^|[_\W])\*(?:[_\W]|$)|all/iu.test(valueText)) sourceKinds.add("wildcard");
    if (/inherit|passthrough|forward|include|pass/iu.test(pathText) && truthyConfigValue(field.value)) sourceKinds.add("inherit_env");
    if (patternCount > 0 && hasSensitiveEnvPattern(valueText)) sourceKinds.add("sensitive_prefix");
    passthroughPatternCount += patternCount;
  }

  const passthroughAll = sourceKinds.has("process_env") || sourceKinds.has("wildcard");
  const passthrough = passthroughAll || sourceKinds.has("inherit_env") || sourceKinds.has("sensitive_prefix");
  const passthroughSecretRisk = passthroughAll || sourceKinds.has("sensitive_prefix");

  return {
    explicitEnvKeys,
    passthrough,
    passthroughAll,
    passthroughSecretRisk,
    passthroughSourceKinds: [...sourceKinds].sort((a, b) => a.localeCompare(b)),
    passthroughPatternCount
  };
}

function collectExplicitMcpEnvKeys(env: unknown): string[] {
  if (!env || typeof env !== "object" || Array.isArray(env)) return [];
  return Object.keys(env as Record<string, unknown>)
    .filter((key) => !isMcpBroadEnvPattern(key))
    .sort((a, b) => a.localeCompare(b));
}

function hasEnvPassthroughPattern(value: string): boolean {
  return /(?:^|[_\W])(\*|process\.env|all[_\s-]?env|all[_\s-]?environment|inherit[_\s-]?env|pass[_\s-]?env|env[_\s-]?passthrough|environment[_\s-]?passthrough|pass[_\s-]?environment|[A-Z0-9_]*\*[A-Z0-9_]*)(?:[_\W]|$)/iu.test(
    value
  );
}

function countEnvPassthroughPatterns(value: unknown): number {
  if (Array.isArray(value)) return value.filter((item) => typeof item === "string" && hasEnvPassthroughPattern(item.toLowerCase())).length;
  if (typeof value === "string") return hasEnvPassthroughPattern(value.toLowerCase()) ? 1 : 0;
  return 0;
}

function hasSensitiveEnvPattern(value: string): boolean {
  return /\b(token|secret|api[_\s-]?key|password|credential|auth|bearer|cookie|session|aws_|gcp_|azure_|github_|openai_|anthropic_|slack_|vault_|npm_)\b|\*_?(token|secret|key|credential|auth|password)/iu.test(
    value
  );
}

function isMcpBroadEnvPattern(value: string): boolean {
  return value === "*" || /process\.env|all[_-]?env|inherit[_-]?env|pass[_-]?env|env[_-]?passthrough/iu.test(value);
}

function classifyMcpClientContext(serverConfig: Record<string, unknown>): McpClientContextPosture {
  const fields = flattenRuntimeFields(serverConfig);
  const rootFields = fields.filter(isMcpRootField);
  const rootScopeKinds = collectMcpRootScopeKinds(rootFields);
  const samplingFields = fields.filter(isMcpSamplingField);
  const samplingContextKinds = collectMcpSamplingContextKinds(samplingFields);
  const elicitationFields = fields.filter(isMcpElicitationField);
  const elicitationSensitiveFieldKinds = collectMcpElicitationSensitiveFieldKinds(elicitationFields);
  const samplingEnabled = hasMcpCapabilityEnabled(fields, /(^|\.)sampling(\.|$)|sample[_-]?request|llm[_-]?request|model[_-]?request/iu);
  const samplingIncludesContext =
    samplingEnabled &&
    samplingContextKinds.length > 0;
  const samplingSensitiveContext =
    samplingEnabled &&
    samplingContextKinds.some((kind) =>
      ["credential_context", "pii_context", "secret_context", "tool_output", "workspace"].includes(kind)
    );
  const elicitationEnabled = hasMcpCapabilityEnabled(fields, /(^|\.)elicitation(\.|$)|elicit|ask[_-]?user|user[_-]?input/iu);
  const elicitationSensitiveFields =
    elicitationEnabled &&
    elicitationSensitiveFieldKinds.length > 0;
  const contextRequestAuthority = samplingEnabled || elicitationEnabled;
  return {
    rootsRedacted: rootFields.length > 0,
    rootCount: countMcpRootEntries(rootFields),
    rootScopeKinds,
    rootBroadScope: rootScopeKinds.some((kind) =>
      ["absolute_path", "credential_path", "file_uri", "home", "host_root", "workspace", "wildcard"].includes(kind)
    ),
    rootCredentialScope: rootScopeKinds.includes("credential_path"),
    rootHostScope: rootScopeKinds.includes("host_root"),
    rootSensitiveScope: rootScopeKinds.some((kind) => ["credential_path", "home", "host_root"].includes(kind)),
    rootApprovalRequired: hasMcpRootApprovalRequiredSignal(fields),
    samplingEnabled,
    samplingIncludesContext,
    samplingContextKinds,
    samplingSensitiveContext,
    samplingRedactionDisabled: samplingEnabled && hasMcpSamplingControlDisabledSignal(samplingFields, /redact|redaction|mask/iu),
    samplingPromptInjectionFilterDisabled: samplingEnabled && hasMcpSamplingControlDisabledSignal(
      samplingFields,
      /prompt[_\s-]?injection|instruction[_\s-]?(?:strip|filter)|jailbreak|sanitize|sanitization/iu
    ),
    samplingApprovalRequired: samplingEnabled && hasMcpSamplingApprovalRequiredSignal(samplingFields),
    elicitationEnabled,
    elicitationSensitiveFields,
    elicitationSensitiveFieldCount: countMcpElicitationSensitiveFields(elicitationFields),
    elicitationSensitiveFieldKinds,
    elicitationRedactionDisabled: elicitationEnabled && hasMcpElicitationControlDisabledSignal(elicitationFields, /redact|redaction|mask/iu),
    elicitationSanitizationDisabled: elicitationEnabled && hasMcpElicitationControlDisabledSignal(
      elicitationFields,
      /sanitize|sanitization|validation|validate|schema/iu
    ),
    elicitationApprovalRequired: elicitationEnabled && hasMcpElicitationApprovalRequiredSignal(elicitationFields),
    contextRequestAuthority,
    clientContextExposure: rootFields.length > 0 || contextRequestAuthority
  };
}

function isMcpSamplingField(field: RuntimeField): boolean {
  return /(?:^|\.)(sampling|sample_request|sampleRequest|llm_request|llmRequest|model_request|modelRequest)(?:\.|$)/u.test(
    field.path
  ) || /\b(sampling|sample request|llm request|model request)\b/iu.test(`${field.path} ${fieldValueText(field)}`);
}

function collectMcpSamplingContextKinds(fields: RuntimeField[]): string[] {
  const kinds = new Set<string>();
  for (const field of fields) {
    const text = mcpSamplingText(field);
    if (/\b(workspace|repo|repository|project|files?|file system|filesystem|directory)\b/iu.test(text)) kinds.add("workspace");
    if (/\b(root|roots?|client root|file uri|file:\/\/|home|host root)\b/iu.test(text)) kinds.add("root_context");
    if (/\b(messages?|conversation|chat history|prompt|prompts?|system prompt|developer prompt)\b/iu.test(text)) {
      kinds.add("prompt_context");
    }
    if (/\b(tool output|tool result|mcp output|command output|shell output|browser output|api response)\b/iu.test(text)) {
      kinds.add("tool_output");
    }
    if (/\b(memory|conversation state|session state|long term|long-term|summary|remembered)\b/iu.test(text)) {
      kinds.add("memory_context");
    }
    if (/(?:^|[_\W])(secret|token|api key|api token|credential|password|bearer|cookie|session)(?:[_\W]|$)/iu.test(text)) {
      kinds.add("credential_context");
      kinds.add("secret_context");
    }
    if (/(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date of birth|customer|account|user id|account id|account number)(?:[_\W]|$)/iu.test(text)) {
      kinds.add("pii_context");
    }
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function hasMcpSamplingControlDisabledSignal(fields: RuntimeField[], controlPattern: RegExp): boolean {
  return fields.some((field) => {
    const text = mcpSamplingText(field);
    if (!controlPattern.test(text)) return false;
    if (/(?:^|\.)(enabled|enforced|required|verification|verify|validation|validate|filter|sanitize|redact)(?:\.|$)/iu.test(field.path)) {
      return disabledConfigValue(field.value);
    }
    return /\b(disabled|off|false|none|skip|bypass|not required|no redaction|no sanitization|unfiltered|raw)\b/iu.test(text);
  });
}

function hasMcpSamplingApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|manual review|review required|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      mcpSamplingText(field)
    ) && truthyConfigValue(field.value)
  );
}

function mcpSamplingText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function isMcpElicitationField(field: RuntimeField): boolean {
  return /(?:^|\.)(elicitation|elicit|ask_user|askUser|user_input|userInput|input_request|inputRequest)(?:\.|$)/u.test(
    field.path
  ) || /\b(elicitation|elicit|ask user|user input|input request)\b/iu.test(`${field.path} ${fieldValueText(field)}`);
}

function collectMcpElicitationSensitiveFieldKinds(fields: RuntimeField[]): string[] {
  const kinds = new Set<string>();
  for (const field of fields) {
    const text = mcpElicitationText(field);
    if (/(?:^|[_\W])(api[_\s-]?key|api[_\s-]?token|token|secret|password|credential|bearer|cookie|session)(?:[_\W]|$)/iu.test(text)) {
      kinds.add("credential");
    }
    if (/(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date of birth|customer|account|user id|account id|account number)(?:[_\W]|$)/iu.test(text)) {
      kinds.add("pii");
    }
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function countMcpElicitationSensitiveFields(fields: RuntimeField[]): number {
  let count = 0;
  for (const field of fields) {
    if (!/(?:^|\.)(fields?|schema|properties|inputs?|requested_fields?|requestedFields?)(?:\.|$)/u.test(field.path)) continue;
    if (Array.isArray(field.value)) {
      count += field.value.filter((value) =>
        typeof value === "string" &&
        collectMcpElicitationSensitiveFieldKinds([{ ...field, value }]).length > 0
      ).length;
      continue;
    }
    if (collectMcpElicitationSensitiveFieldKinds([field]).length > 0) count += 1;
  }
  return count;
}

function hasMcpElicitationControlDisabledSignal(fields: RuntimeField[], controlPattern: RegExp): boolean {
  return fields.some((field) => {
    const text = mcpElicitationText(field);
    if (!controlPattern.test(text)) return false;
    if (/(?:^|\.)(enabled|enforced|required|verification|verify|validation|validate|filter|sanitize|redact)(?:\.|$)/iu.test(field.path)) {
      return disabledConfigValue(field.value);
    }
    return /\b(disabled|off|false|none|skip|bypass|not required|no redaction|no sanitization|unvalidated|raw)\b/iu.test(text);
  });
}

function hasMcpElicitationApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|manual review|review required|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      mcpElicitationText(field)
    ) && truthyConfigValue(field.value)
  );
}

function mcpElicitationText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function classifyMcpToolCatalog(serverConfig: Record<string, unknown>): McpToolCatalogPosture {
  const fields = flattenRuntimeFields(serverConfig);
  const catalogFields = fields.filter(isMcpToolCatalogField);
  const detected = catalogFields.length > 0;
  const authorityCategories = collectMcpToolCatalogAuthorityCategories(catalogFields);

  return {
    detected,
    enabled: detected && !hasMcpToolCatalogDisabledSignal(catalogFields),
    sourceRedacted: hasMcpToolCatalogSourceSignal(catalogFields),
    sourceCount: countMcpToolCatalogSources(catalogFields),
    sourceKinds: collectMcpToolCatalogSourceKinds(catalogFields),
    dynamicDiscovery: hasMcpToolCatalogDynamicSignal(catalogFields),
    autoRefresh: hasMcpToolCatalogAutoRefreshSignal(catalogFields),
    modelVisibleDescriptions: hasMcpToolCatalogModelVisibleDescriptionSignal(catalogFields),
    remoteSchemaTrust: hasMcpToolCatalogRemoteSchemaTrustSignal(catalogFields),
    unpinnedTools: hasMcpToolCatalogUnpinnedSignal(catalogFields),
    signatureVerificationDisabled: hasMcpToolCatalogVerificationDisabledSignal(catalogFields, /signature|signing|signed|checksum|digest|hash/iu),
    provenanceVerificationDisabled: hasMcpToolCatalogVerificationDisabledSignal(catalogFields, /provenance|attestation|source|origin/iu),
    unreviewedToolsAllowed: hasMcpToolCatalogUnreviewedAllowedSignal(catalogFields),
    toolAuthorityCategories: authorityCategories,
    privilegedToolAuthority: isMcpToolCatalogPrivileged(authorityCategories),
    writeAuthority: hasMcpToolCatalogWriteAuthoritySignal(catalogFields, authorityCategories),
    externalAuthority: hasMcpToolCatalogExternalAuthoritySignal(catalogFields, authorityCategories),
    memoryAuthority: hasMcpToolCatalogMemoryAuthoritySignal(catalogFields, authorityCategories),
    secretContext: hasMcpToolCatalogSecretSignal(catalogFields, authorityCategories),
    shellAuthority: hasMcpToolCatalogShellSignal(catalogFields, authorityCategories),
    sensitiveContext: hasMcpToolCatalogSensitiveContextSignal(catalogFields),
    piiContext: hasMcpToolCatalogPiiContextSignal(catalogFields),
    approvalRequired: hasMcpToolCatalogApprovalRequiredSignal(catalogFields)
  };
}

function isMcpToolCatalogField(field: RuntimeField): boolean {
  return /(?:^|\.)(tool_catalog|toolCatalog|tools_catalog|toolsCatalog|tool_registry|toolRegistry|tools_registry|toolsRegistry|tool_discovery|toolDiscovery|catalog|registry|marketplace|list_tools|listTools|discover_tools|discoverTools|remote_tools|remoteTools|model_visible_descriptions|modelVisibleDescriptions|trust_remote_descriptions|trustRemoteDescriptions|allow_unreviewed_tools|allowUnreviewedTools|tool_manifest|toolManifest)(?:\.|$)/u.test(
    field.path
  );
}

function hasMcpToolCatalogDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(enabled|active)(?:\.|$)/iu.test(field.path) && disabledConfigValue(field.value));
}

function hasMcpToolCatalogSourceSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|\.)(source|sources?|url|uri|endpoint|registry|marketplace|manifest)(?:\.|$)/iu.test(field.path) ||
    /\b(remote|registry|catalog|marketplace|manifest|mcp server|tool source|tool catalog)\b/iu.test(mcpToolCatalogText(field))
  );
}

function countMcpToolCatalogSources(fields: RuntimeField[]): number {
  return fields.filter((field) =>
    /(?:^|\.)(source|sources?|url|uri|endpoint|registry|marketplace|manifest)(?:\.|$)/iu.test(field.path)
  ).length;
}

function collectMcpToolCatalogSourceKinds(fields: RuntimeField[]): string[] {
  const kinds = new Set<string>();
  for (const field of fields) {
    if (!/(?:^|\.)(source|sources?|url|uri|endpoint|registry|marketplace|manifest)(?:\.|$)/iu.test(field.path)) continue;
    const text = mcpToolCatalogText(field);
    if (/\b(remote|http|https|server|mcp server)\b/iu.test(text)) kinds.add("remote_registry");
    if (/\b(dynamic|discover|list tools|list_tools|tool discovery)\b/iu.test(text)) kinds.add("dynamic_discovery");
    if (/\b(catalog|registry|tool catalog|tool registry)\b/iu.test(text)) kinds.add("tool_catalog");
    if (/\b(marketplace|hub|store)\b/iu.test(text)) kinds.add("marketplace");
    if (/\b(static|local|manifest|pinned)\b/iu.test(text)) kinds.add("static_manifest");
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function hasMcpToolCatalogDynamicSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(dynamic|discover|discovery|list tools|list_tools|refresh tools|remote dynamic|runtime catalog|server supplied tools)\b/iu.test(
      mcpToolCatalogText(field)
    ) && !disabledConfigValue(field.value)
  );
}

function hasMcpToolCatalogAutoRefreshSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (/(?:^|\.)(auto_refresh|autoRefresh|refresh_interval|refreshInterval|sync|auto_sync|autoSync|poll|update_interval|updateInterval)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(auto refresh|auto-refresh|auto sync|auto-sync|poll catalog|refresh interval|refresh tools automatically|runtime refresh)\b/iu.test(text);
  });
}

function hasMcpToolCatalogModelVisibleDescriptionSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (/(?:^|\.)(model_visible_descriptions|modelVisibleDescriptions|tool_descriptions|toolDescriptions|descriptions_to_model|descriptionsToModel|expose_to_model|exposeToModel)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(model visible|visible to model|tool descriptions? to model|expose descriptions?|model reads descriptions?)\b/iu.test(text);
  });
}

function hasMcpToolCatalogRemoteSchemaTrustSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (/(?:^|\.)(trust_remote_descriptions|trustRemoteDescriptions|trust_remote_schema|trustRemoteSchema|trust_server_tools|trustServerTools|trust_catalog|trustCatalog)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(trust remote descriptions?|trust remote schemas?|trust server tools?|trust catalog|trusted from server|server supplied descriptions trusted)\b/iu.test(
      text
    );
  });
}

function hasMcpToolCatalogUnpinnedSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (/(?:^|\.)(pinning|pinned|pinned_tools|pinnedTools|version_pinned|versionPinned|digest_pinned|digestPinned|lockfile|tool_hashes|toolHashes)(?:\.|$)/u.test(field.path)) {
      return disabledConfigValue(field.value);
    }
    return /\b(unpinned|floating|latest|mutable|no pinning|pinning disabled|without digest|no digest|no lockfile)\b/iu.test(text);
  });
}

function hasMcpToolCatalogVerificationDisabledSignal(fields: RuntimeField[], verificationPattern: RegExp): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (!verificationPattern.test(text)) return false;
    if (/(?:^|\.)(enabled|enforced|required|verification|verify|validation|validate)(?:\.|$)/iu.test(field.path)) {
      return disabledConfigValue(field.value);
    }
    return /\b(disabled|off|false|none|skip|bypass|not required|unsigned|unverified|no verification|no validation)\b/iu.test(text);
  });
}

function hasMcpToolCatalogUnreviewedAllowedSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpToolCatalogText(field);
    if (/(?:^|\.)(allow_unreviewed_tools|allowUnreviewedTools|allow_unapproved_tools|allowUnapprovedTools|review_required|reviewRequired|approval_required|approvalRequired)(?:\.|$)/u.test(field.path)) {
      if (/(?:review_required|reviewRequired|approval_required|approvalRequired)$/u.test(field.path)) return disabledConfigValue(field.value);
      return truthyConfigValue(field.value);
    }
    return /\b(allow unreviewed tools|allow unapproved tools|auto accept tools|trust new tools|no review required|review disabled)\b/iu.test(text);
  });
}

function collectMcpToolCatalogAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (!isMcpToolCatalogAuthorityField(field.path)) continue;
    const text = mcpToolCatalogText(field);
    if (disabledConfigValue(field.value)) continue;
    if (!/\b(tool|tools|function|capability|action|command|database|db|sql|slack|email|webhook|secret|vault|memory|shell|filesystem|browser|customer|reply)\b/iu.test(text)) {
      continue;
    }
    if (/\b(tool|tools|function|capability|action|command)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(database|db|sql|query|crm|support db|warehouse|record|update customer|customer record)\b/iu.test(text)) {
      categories.add("database_write");
    }
    if (/\b(slack|email|sms|message|webhook|ticket|jira|zendesk|reply|respond|send|post|publish|customer reply)\b/iu.test(text)) {
      categories.add("external_response");
    }
    if (/\b(browser|playwright|puppeteer|click|form|navigate|submit)\b/iu.test(text)) categories.add("browser_action");
    if (/(?:^|[_\W])(vault|secret|secrets|secret manager|key vault|credential|api key|token)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/(?:^|[_\W])(memory|remember|store|persist|summary|session state|conversation state)(?:[_\W]|$)/iu.test(text)) {
      categories.add("memory_write");
    }
    if (/\b(shell|bash|command|exec|terminal|python|node|subprocess|code interpreter|remediation)\b/iu.test(text)) {
      categories.add("shell_execution");
    }
    if (/\b(filesystem|file write|workspace|repo|repository|github|gitlab|commit|push|merge)\b/iu.test(text)) {
      categories.add("filesystem_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function isMcpToolCatalogPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "browser_action",
      "database_write",
      "external_response",
      "filesystem_write",
      "memory_write",
      "secret_manager_access",
      "shell_execution"
    ].includes(category)
  );
}

function hasMcpToolCatalogWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) =>
    ["browser_action", "database_write", "external_response", "filesystem_write", "memory_write", "shell_execution"].includes(category)
  ) || fields.some((field) =>
    isMcpToolCatalogAuthorityField(field.path) &&
    /\b(write|update|create|delete|reply|respond|send|post|publish|comment|commit|push|merge|submit|remember|persist|execute|run)\b/iu.test(
      mcpToolCatalogText(field)
    )
  );
}

function hasMcpToolCatalogExternalAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) =>
      isMcpToolCatalogAuthorityField(field.path) &&
      /\b(reply|respond|send|post|publish|slack|email|sms|webhook|ticket|external response|customer reply)\b/iu.test(mcpToolCatalogText(field))
    );
}

function hasMcpToolCatalogMemoryAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("memory_write") ||
    fields.some((field) =>
      isMcpToolCatalogAuthorityField(field.path) &&
      /\b(memory|remember|persist|store|conversation state|session state|long term|long-term|summary)\b/iu.test(mcpToolCatalogText(field))
    );
}

function hasMcpToolCatalogSecretSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("secret_manager_access") ||
    fields.some((field) =>
      isMcpToolCatalogAuthorityField(field.path) &&
      /\b(secret|token|credential|api key|password|vault|key vault|authorization|bearer)\b/iu.test(mcpToolCatalogText(field))
    );
}

function hasMcpToolCatalogShellSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("shell_execution") ||
    fields.some((field) =>
      isMcpToolCatalogAuthorityField(field.path) &&
      /\b(shell|bash|command|exec|terminal|subprocess|python|node|remediation)\b/iu.test(mcpToolCatalogText(field))
    );
}

function isMcpToolCatalogAuthorityField(fieldPath: string): boolean {
  return /(?:^|\.)(tools?|allowed_tools|allowedTools|tool_names|toolNames|actions?|commands?|capabilities?|functions?|permissions?|routes?|handlers?)(?:\.|$)/iu.test(
    fieldPath
  );
}

function hasMcpToolCatalogSensitiveContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|case|record|profile|incident|notes?)\b/iu.test(
      mcpToolCatalogText(field)
    )
  );
}

function hasMcpToolCatalogPiiContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date of birth|customer id|user id|account id|account number)(?:[_\W]|$)/iu.test(
      mcpToolCatalogText(field)
    )
  );
}

function hasMcpToolCatalogApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|manual review|review required|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      mcpToolCatalogText(field)
    ) && truthyConfigValue(field.value)
  );
}

function mcpToolCatalogText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function classifyMcpResourceSubscriptions(serverConfig: Record<string, unknown>): McpResourceSubscriptionPosture {
  const fields = flattenRuntimeFields(serverConfig).filter(isMcpResourceSubscriptionField);
  const detected = fields.length > 0;
  const authorityCategories = collectMcpResourceSubscriptionAuthorityCategories(fields);

  return {
    detected,
    enabled: detected && !hasMcpResourceSubscriptionDisabledSignal(fields),
    sourceRedacted: hasMcpResourceSubscriptionSourceSignal(fields),
    sourceCount: countMcpResourceSubscriptionSources(fields),
    sourceKinds: collectMcpResourceSubscriptionSourceKinds(fields),
    dynamicUpdates: hasMcpResourceSubscriptionDynamicUpdateSignal(fields),
    autoRefresh: hasMcpResourceSubscriptionAutoRefreshSignal(fields),
    autoIncludeContext: hasMcpResourceSubscriptionAutoIncludeSignal(fields),
    modelVisibleContext: hasMcpResourceSubscriptionModelVisibleSignal(fields),
    rawContentPassthrough: hasMcpResourceSubscriptionRawContentSignal(fields),
    untrustedSource: hasMcpResourceSubscriptionUntrustedSourceSignal(fields),
    sanitizationDisabled: hasMcpResourceSubscriptionControlDisabledSignal(fields, /sanitize|sanitization|clean|strip/i),
    redactionDisabled: hasMcpResourceSubscriptionControlDisabledSignal(fields, /redact|redaction|mask/i),
    promptInjectionFilterDisabled: hasMcpResourceSubscriptionControlDisabledSignal(
      fields,
      /prompt[_\s-]?injection|instruction[_\s-]?(?:strip|filter)|jailbreak/i
    ),
    provenanceVerificationDisabled: hasMcpResourceSubscriptionControlDisabledSignal(
      fields,
      /provenance|attestation|source[_\s-]?verification|origin|verify|verification/i
    ),
    authorityCategories,
    privilegedBridge: isMcpResourceSubscriptionPrivileged(authorityCategories),
    writeAuthority: hasMcpResourceSubscriptionWriteAuthoritySignal(fields, authorityCategories),
    externalAuthority: hasMcpResourceSubscriptionExternalAuthoritySignal(fields, authorityCategories),
    memoryAuthority: hasMcpResourceSubscriptionMemoryAuthoritySignal(fields, authorityCategories),
    secretContext: hasMcpResourceSubscriptionSecretSignal(fields, authorityCategories),
    shellAuthority: hasMcpResourceSubscriptionShellSignal(fields, authorityCategories),
    sensitiveContext: hasMcpResourceSubscriptionSensitiveContextSignal(fields),
    piiContext: hasMcpResourceSubscriptionPiiContextSignal(fields),
    approvalRequired: hasMcpResourceSubscriptionApprovalRequiredSignal(fields)
  };
}

function isMcpResourceSubscriptionField(field: RuntimeField): boolean {
  const text = mcpResourceSubscriptionText(field);
  return /(?:^|\.)(resource_subscriptions?|resourceSubscriptions?|resource_watches?|resourceWatches?|resource_sync|resourceSync|resource_updates?|resourceUpdates?|resource_notifications?|resourceNotifications?|subscribe_resources?|subscribeResources?|watch_resources?|watchResources?|subscriptions?)(?:\.|$)/u.test(
    field.path
  ) || (/\b(resource|resources)\b/iu.test(text) && /\b(subscribe|subscription|watch|stream|sync|notification|notify|update feed|live update)\b/iu.test(text));
}

function hasMcpResourceSubscriptionDisabledSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => /(?:^|\.)(enabled|active)(?:\.|$)/iu.test(field.path) && disabledConfigValue(field.value));
}

function hasMcpResourceSubscriptionSourceSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|\.)(source|sources?|url|uri|endpoint|stream|feed|channel|resources?|resource_uris|resourceUris)(?:\.|$)/iu.test(field.path) ||
    /\b(remote|resource|subscription|stream|feed|channel|webhook|ticket|browser|tool output|memory|retrieval|vector)\b/iu.test(
      mcpResourceSubscriptionText(field)
    )
  );
}

function countMcpResourceSubscriptionSources(fields: RuntimeField[]): number {
  const entries = new Set<string>();
  for (const field of fields) {
    if (!/(?:^|\.)(source|sources?|url|uri|endpoint|stream|feed|channel|resources?|resource_uris|resourceUris)(?:\.|$)/iu.test(field.path)) {
      continue;
    }
    const sourceEntry = field.path.match(/((?:^|\.)(?:source|sources)\.(?:\d+|[^.]+))/iu);
    entries.add(sourceEntry?.[1]?.replace(/^\./u, "") ?? field.path);
  }
  return entries.size;
}

function collectMcpResourceSubscriptionSourceKinds(fields: RuntimeField[]): string[] {
  const kinds = new Set<string>();
  for (const field of fields) {
    if (isMcpResourceSubscriptionAuthorityField(field.path)) continue;
    const text = mcpResourceSubscriptionText(field);
    const valueText = fieldValueText(field).toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
    if (/\b(remote|http|https|server|mcp server)\b/iu.test(text)) kinds.add("remote_resource");
    if (
      (/(?:^|\.)(dynamic|live|watch|stream|sync|subscribe|notifications?|updates?|auto_update|autoUpdate)(?:\.|$)/iu.test(field.path) &&
        !disabledConfigValue(field.value)) ||
      /\b(subscribe|watch|stream|sync|notification|notify|dynamic|live update|auto update)\b/iu.test(valueText)
    ) {
      kinds.add("dynamic_subscription");
    }
    if (/\b(customer|ticket|case|email|chat|slack|message|webhook|attachment|upload|user supplied|user-supplied|untrusted)\b/iu.test(text)) {
      kinds.add("customer_stream");
    }
    if (/\b(browser|screenshot|ocr|dom|page content|navigation|web page)\b/iu.test(text)) kinds.add("browser_output");
    if (/\b(tool output|tool result|mcp output|api response|command output|shell output)\b/iu.test(text)) kinds.add("tool_output");
    if (/\b(memory|conversation state|session state|long term|long-term|summary)\b/iu.test(text)) kinds.add("memory_resource");
    if (/\b(retrieval|rag|vector|embedding|document chunk|knowledge base)\b/iu.test(text)) kinds.add("retrieval_resource");
    if (/\b(public web|external web|internet|crawler|rss|feed)\b/iu.test(text)) kinds.add("public_web");
    if (/\b(filesystem|file system|file:\/\/|workspace|repo|repository|path|directory)\b/iu.test(text)) kinds.add("filesystem_resource");
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function hasMcpResourceSubscriptionDynamicUpdateSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const valueText = fieldValueText(field).toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
    if (/(?:^|\.)(dynamic|live|watch|stream|sync|notifications?|updates?|auto_update|autoUpdate)(?:\.|$)/iu.test(field.path)) {
      return !disabledConfigValue(field.value);
    }
    return /\b(dynamic|live update|subscribe|watch|stream|sync|notification|server push|resource update)\b/iu.test(valueText);
  });
}

function hasMcpResourceSubscriptionAutoRefreshSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpResourceSubscriptionText(field);
    if (/(?:^|\.)(auto_refresh|autoRefresh|refresh_interval|refreshInterval|auto_sync|autoSync|poll|poll_interval|pollInterval|sync_interval|syncInterval)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(auto refresh|auto-refresh|auto sync|auto-sync|poll|polling|refresh interval|sync interval|continuous refresh)\b/iu.test(text);
  });
}

function hasMcpResourceSubscriptionAutoIncludeSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpResourceSubscriptionText(field);
    if (/(?:^|\.)(auto_include_context|autoIncludeContext|auto_inject|autoInject|inject_into_context|injectIntoContext|append_to_messages|appendToMessages|include_in_prompt|includeInPrompt)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(auto include|auto-includ|auto inject|inject into context|append to messages|include in prompt|promote to context)\b/iu.test(text);
  });
}

function hasMcpResourceSubscriptionModelVisibleSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpResourceSubscriptionText(field);
    if (/(?:^|\.)(model_visible|modelVisible|visible_to_model|visibleToModel|expose_to_model|exposeToModel|context_visible|contextVisible)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(model visible|visible to model|model reads|expose to model|context visible|prompt context)\b/iu.test(text);
  });
}

function hasMcpResourceSubscriptionRawContentSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = mcpResourceSubscriptionText(field);
    if (/(?:^|\.)(include_raw_content|includeRawContent|raw_content|rawContent|raw_chunks|rawChunks|passthrough|pass_through|raw_passthrough|rawPassthrough)(?:\.|$)/u.test(field.path)) {
      return truthyConfigValue(field.value);
    }
    return /\b(raw content|raw chunks|raw output|passthrough|pass-through|unfiltered content|unmodified content)\b/iu.test(text);
  });
}

function hasMcpResourceSubscriptionUntrustedSourceSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(untrusted|customer|user supplied|user-supplied|user upload|external|public|internet|ticket|case|email|chat|slack|webhook|browser|tool output|api response|attachment)\b/iu.test(
      mcpResourceSubscriptionText(field)
    )
  );
}

function hasMcpResourceSubscriptionControlDisabledSignal(fields: RuntimeField[], controlPattern: RegExp): boolean {
  return fields.some((field) => {
    const text = mcpResourceSubscriptionText(field);
    if (!controlPattern.test(text)) return false;
    if (/(?:^|\.)(enabled|enforced|required|verification|verify|validation|validate|filter|sanitize|redact)(?:\.|$)/iu.test(field.path)) {
      return disabledConfigValue(field.value);
    }
    return /\b(disabled|off|false|none|skip|bypass|not required|unverified|no verification|no validation|no redaction|no sanitization|unfiltered)\b/iu.test(
      text
    );
  });
}

function collectMcpResourceSubscriptionAuthorityCategories(fields: RuntimeField[]): string[] {
  const categories = new Set<string>();
  for (const field of fields) {
    if (!isMcpResourceSubscriptionAuthorityField(field.path)) continue;
    if (disabledConfigValue(field.value)) continue;
    const text = mcpResourceSubscriptionText(field);
    if (!/\b(tool|tools|function|capability|action|command|database|db|sql|slack|email|webhook|secret|vault|memory|shell|filesystem|browser|customer|reply)\b/iu.test(text)) {
      continue;
    }
    if (/\b(tool|tools|function|capability|action|command)\b/iu.test(text)) categories.add("tool_call");
    if (/\b(database|db|sql|query|crm|support db|warehouse|record|update customer|customer record)\b/iu.test(text)) {
      categories.add("database_write");
    }
    if (/\b(slack|email|sms|message|webhook|ticket|jira|zendesk|reply|respond|send|post|publish|customer reply)\b/iu.test(text)) {
      categories.add("external_response");
    }
    if (/\b(browser|playwright|puppeteer|click|form|navigate|submit)\b/iu.test(text)) categories.add("browser_action");
    if (/(?:^|[_\W])(vault|secret|secrets|secret manager|key vault|credential|api key|token)(?:[_\W]|$)/iu.test(text)) {
      categories.add("secret_manager_access");
    }
    if (/(?:^|[_\W])(memory|remember|store|persist|summary|session state|conversation state)(?:[_\W]|$)/iu.test(text)) {
      categories.add("memory_write");
    }
    if (/\b(shell|bash|command|exec|terminal|python|node|subprocess|code interpreter|remediation)\b/iu.test(text)) {
      categories.add("shell_execution");
    }
    if (/\b(filesystem|file write|workspace|repo|repository|github|gitlab|commit|push|merge)\b/iu.test(text)) {
      categories.add("filesystem_write");
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b));
}

function isMcpResourceSubscriptionAuthorityField(fieldPath: string): boolean {
  return /(?:^|\.)(tools?|allowed_tools|allowedTools|target_tools|targetTools|followup_tools|followupTools|downstream_tools|downstreamTools|tool_names|toolNames|actions?|commands?|capabilities?|functions?|permissions?|routes?|handlers?|on_update|onUpdate|on_notification|onNotification|authority|privileged_authority|privilegedAuthority)(?:\.|$)/iu.test(
    fieldPath
  );
}

function isMcpResourceSubscriptionPrivileged(categories: string[]): boolean {
  return categories.some((category) =>
    [
      "browser_action",
      "database_write",
      "external_response",
      "filesystem_write",
      "memory_write",
      "secret_manager_access",
      "shell_execution"
    ].includes(category)
  );
}

function hasMcpResourceSubscriptionWriteAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.some((category) =>
    ["browser_action", "database_write", "external_response", "filesystem_write", "memory_write", "shell_execution"].includes(category)
  ) || fields.some((field) =>
    isMcpResourceSubscriptionAuthorityField(field.path) &&
    /\b(write|update|create|delete|reply|respond|send|post|publish|comment|commit|push|merge|submit|remember|persist|execute|run)\b/iu.test(
      mcpResourceSubscriptionText(field)
    )
  );
}

function hasMcpResourceSubscriptionExternalAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("external_response") ||
    fields.some((field) =>
      isMcpResourceSubscriptionAuthorityField(field.path) &&
      /\b(reply|respond|send|post|publish|slack|email|sms|webhook|ticket|external response|customer reply)\b/iu.test(
        mcpResourceSubscriptionText(field)
      )
    );
}

function hasMcpResourceSubscriptionMemoryAuthoritySignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("memory_write") ||
    fields.some((field) =>
      isMcpResourceSubscriptionAuthorityField(field.path) &&
      /\b(memory|remember|persist|store|conversation state|session state|long term|long-term|summary)\b/iu.test(
        mcpResourceSubscriptionText(field)
      )
    );
}

function hasMcpResourceSubscriptionSecretSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("secret_manager_access") ||
    fields.some((field) =>
      /\b(secret|token|credential|api key|password|vault|key vault|authorization|bearer)\b/iu.test(mcpResourceSubscriptionText(field))
    );
}

function hasMcpResourceSubscriptionShellSignal(fields: RuntimeField[], categories: string[]): boolean {
  return categories.includes("shell_execution") ||
    fields.some((field) =>
      isMcpResourceSubscriptionAuthorityField(field.path) &&
      /\b(shell|bash|command|exec|terminal|subprocess|python|node|remediation)\b/iu.test(mcpResourceSubscriptionText(field))
    );
}

function hasMcpResourceSubscriptionSensitiveContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(customer|client|ticket|support|internal|confidential|private|proprietary|sensitive|account|billing|payment|case|record|profile|incident|notes?)\b/iu.test(
      mcpResourceSubscriptionText(field)
    )
  );
}

function hasMcpResourceSubscriptionPiiContextSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /(?:^|[_\W])(pii|email|phone|address|ssn|passport|dob|date of birth|customer id|user id|account id|account number)(?:[_\W]|$)/iu.test(
      mcpResourceSubscriptionText(field)
    )
  );
}

function hasMcpResourceSubscriptionApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) =>
    /\b(approval|required approval|human approval|manual review|review required|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      mcpResourceSubscriptionText(field)
    ) && truthyConfigValue(field.value)
  );
}

function mcpResourceSubscriptionText(field: RuntimeField): string {
  return `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
}

function isMcpRootField(field: RuntimeField): boolean {
  return /(^|\.)(roots?|root_uris|rootUris|client_roots|clientRoots|workspace_roots|workspaceRoots|allowed_paths|allowedPaths|filesystem|fs_roots|mounts?)(\.|$)/iu.test(
    field.path
  );
}

function collectMcpRootScopeKinds(fields: RuntimeField[]): string[] {
  const kinds = new Set<string>();
  for (const field of fields) {
    const text = `${field.path} ${fieldValueText(field)}`;
    if (/\*/u.test(text)) kinds.add("wildcard");
    if (/\bfile:\/\//iu.test(text)) kinds.add("file_uri");
    if (/\bfile:\/\/\/(?:\s|$)|(^|[\s,])\/(?:\s|$)|host[_-]?root|rootfs/iu.test(text)) kinds.add("host_root");
    if (/(^|[\s,])~\/|\/home\/|\/Users\/|\/root\//u.test(text)) kinds.add("home");
    if (/\/workspace|\/workspaces|\/repo|\/project|workspace|repository|project/iu.test(text)) kinds.add("workspace");
    if (/\.ssh|\.aws|\.kube|credentials?|secrets?|tokens?|private[_-]?key/iu.test(text)) kinds.add("credential_path");
    if (/\bfile:\/\/\/[^/\s]|(^|[\s,])\/[A-Za-z0-9_.-]/u.test(text)) kinds.add("absolute_path");
  }
  return [...kinds].sort((a, b) => a.localeCompare(b));
}

function countMcpRootEntries(fields: RuntimeField[]): number {
  const entries = new Set<string>();
  for (const field of fields) {
    const match = field.path.match(
      /((?:^|\.)(?:roots?|root_uris|rootUris|client_roots|clientRoots|workspace_roots|workspaceRoots|allowed_paths|allowedPaths|fs_roots|mounts?)\.(?:\d+|[^.]+))/u
    );
    entries.add(match?.[1]?.replace(/^\./u, "") ?? field.path);
  }
  return entries.size;
}

function hasMcpRootApprovalRequiredSignal(fields: RuntimeField[]): boolean {
  return fields.some((field) => {
    const text = `${field.path} ${fieldValueText(field)}`.toLowerCase().replaceAll("_", " ").replaceAll("-", " ");
    if (!/\b(root|roots|client root|filesystem|file system|workspace|mount|allowed path)\b/iu.test(text)) return false;
    return /\b(approval|required approval|human approval|manual review|review required|confirm|confirmation|human in the loop|human-in-the-loop)\b/iu.test(
      text
    ) && truthyConfigValue(field.value);
  });
}

function hasMcpCapabilityEnabled(fields: RuntimeField[], pathPattern: RegExp): boolean {
  return fields.some((field) => pathPattern.test(field.path) && truthyConfigValue(field.value));
}

function extractMcpContextDefinitions(serverConfig: Record<string, unknown>): McpContextDefinition[] {
  const definitions: McpContextDefinition[] = [];
  collectMcpContextDefinitions(definitions, "prompt", "prompts", serverConfig.prompts);
  collectMcpContextDefinitions(definitions, "prompt", "promptTemplates", serverConfig.promptTemplates);
  collectMcpContextDefinitions(definitions, "prompt", "prompt_templates", serverConfig.prompt_templates);
  collectMcpContextDefinitions(definitions, "prompt", "exposedPrompts", serverConfig.exposedPrompts);
  collectMcpContextDefinitions(definitions, "resource", "resources", serverConfig.resources);
  collectMcpContextDefinitions(definitions, "resource", "resourceTemplates", serverConfig.resourceTemplates);
  collectMcpContextDefinitions(definitions, "resource", "resource_templates", serverConfig.resource_templates);

  const capabilities = serverConfig.capabilities && typeof serverConfig.capabilities === "object"
    ? (serverConfig.capabilities as Record<string, unknown>)
    : undefined;
  if (capabilities) {
    collectMcpContextDefinitions(definitions, "prompt", "capabilities.prompts", capabilities.prompts);
    collectMcpContextDefinitions(definitions, "resource", "capabilities.resources", capabilities.resources);
  }

  return definitions.slice(0, 20).map((definition, index) => ({ ...definition, index }));
}

function collectMcpContextDefinitions(
  definitions: McpContextDefinition[],
  kind: McpContextDefinition["kind"],
  sourceField: string,
  value: unknown
): void {
  if (value === undefined || value === null || typeof value === "boolean" || typeof value === "number") return;
  const entries = mcpContextEntries(value);
  for (const entry of entries) {
    const fields = flattenRuntimeFields(entry);
    const fieldTexts = collectFieldStringValues(fields);
    const pathTexts = fields.map((field) => field.path);
    const content = uniqueStrings([sourceField, ...pathTexts, ...fieldTexts]).join("\n");
    if (!content.trim()) continue;
    definitions.push({
      kind,
      index: definitions.length,
      sourceField,
      content,
      uriRedacted: fields.some((field) => /(^|\.)(uri|url|endpoint|href)$/iu.test(field.path) && fieldValueText(field).trim().length > 0),
      nameRedacted: fields.some((field) => /(^|\.)(name|title|id|description)$/iu.test(field.path) && fieldValueText(field).trim().length > 0),
      envKeys: extractEnvironmentReferenceKeys(fieldTexts).filter(isLikelyEnvKeyName),
      secretRefKeys: extractSecretReferenceKeys(fieldTexts)
    });
  }
}

function mcpContextEntries(value: unknown): unknown[] {
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== "object") return [];
  return Object.entries(value as Record<string, unknown>).map(([key, item]) => {
    if (item && typeof item === "object" && !Array.isArray(item)) {
      return { name: key, ...(item as Record<string, unknown>) };
    }
    return { name: key, value: item };
  });
}

function extractLocalMcpCommandPathRefs(command: string | undefined, args: string[]): string[] {
  return uniqueStrings([command, ...args].flatMap((value) => normalizeLocalImplementationPath(value)));
}

function isCredentialLikeKeyName(keyName: string): boolean {
  return /authorization|token|secret|key|password|credential|auth|webhook|cookie|bearer/i.test(keyName);
}

function normalizeLocalImplementationPath(value: string | undefined): string[] {
  if (!value) return [];
  const normalizedValue = value.trim().replaceAll("\\", "/");
  if (!normalizedValue) return [];
  if (normalizedValue.startsWith("-")) return [];
  if (normalizedValue.startsWith("${") || normalizedValue.includes("${")) return [];
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(normalizedValue)) return [];
  if (path.posix.isAbsolute(normalizedValue) || path.win32.isAbsolute(value)) return [];
  if (!looksLikeImplementationPath(normalizedValue)) return [];

  const normalizedPath = normalizeProjectPath(normalizedValue);
  if (normalizedPath === "." || normalizedPath === ".." || normalizedPath.startsWith("../")) return [];
  return [normalizedPath];
}

function looksLikeImplementationPath(value: string): boolean {
  if (!value.includes("/") && !value.startsWith("./")) return false;
  return /\.(?:cjs|mjs|js|cts|mts|ts|jsx|tsx|py|sh|rb|go|rs|jar|php|pl|ps1)$/i.test(value);
}

function normalizeProjectPath(value: string): string {
  const normalized = path.posix.normalize(value.replaceAll("\\", "/"));
  return normalized.startsWith("./") ? normalized.slice(2) : normalized;
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)].sort((a, b) => a.localeCompare(b));
}

interface McpPackageRunnerSignal {
  runner: string;
  packageName?: string;
  versionPinned: boolean;
  packageReferenceRedacted: boolean;
}

function classifyMcpPackageRunner(command: string | undefined, args: string[]): McpPackageRunnerSignal | undefined {
  if (!command) return undefined;
  const runner = path.basename(command).toLowerCase();
  let packageSpec: string | undefined;

  if (["npx", "bunx", "uvx"].includes(runner)) {
    packageSpec = firstPackageLikeArg(args);
  }
  if (runner === "pnpm" && args[0] === "dlx") {
    packageSpec = firstPackageLikeArg(args.slice(1));
  }
  if (runner === "yarn" && args[0] === "dlx") {
    packageSpec = firstPackageLikeArg(args.slice(1));
  }
  if (runner === "npm" && ["exec", "x"].includes(args[0] ?? "")) {
    packageSpec = firstPackageLikeArg(args.slice(1));
  }
  if (runner === "pipx" && args[0] === "run") {
    packageSpec = firstPackageLikeArg(args.slice(1));
  }

  if (!packageSpec) return undefined;
  const normalized = normalizePackageReference(packageSpec);
  return {
    runner,
    packageName: normalized.name,
    versionPinned: normalized.versionPinned,
    packageReferenceRedacted: true
  };
}

function firstPackageLikeArg(args: string[]): string | undefined {
  const skipNextValueFor = new Set(["--package", "--from", "-p"]);
  let skipNext = false;
  for (const arg of args) {
    if (skipNext) {
      skipNext = false;
      continue;
    }
    if (arg === "--") continue;
    if (skipNextValueFor.has(arg)) {
      skipNext = true;
      continue;
    }
    if (arg.startsWith("-")) continue;
    return arg;
  }
  return undefined;
}

function normalizePackageReference(spec: string): { name?: string; versionPinned: boolean } {
  const trimmed = spec.trim();
  if (!trimmed) return { versionPinned: false };

  const pythonExactVersionIndex = trimmed.indexOf("==");
  if (pythonExactVersionIndex > 0) {
    const version = trimmed.slice(pythonExactVersionIndex + 2);
    return {
      name: trimmed.slice(0, pythonExactVersionIndex),
      versionPinned: Boolean(version && !/^latest$/iu.test(version))
    };
  }

  const versionMarker = npmVersionMarkerIndex(trimmed);
  if (versionMarker > 0) {
    const version = trimmed.slice(versionMarker + 1);
    return {
      name: trimmed.slice(0, versionMarker),
      versionPinned: Boolean(version && !/^latest$/iu.test(version))
    };
  }

  return {
    name: trimmed,
    versionPinned: false
  };
}

function npmVersionMarkerIndex(spec: string): number {
  if (spec.startsWith("@")) {
    const slashIndex = spec.indexOf("/");
    if (slashIndex === -1) return -1;
    return spec.indexOf("@", slashIndex + 1);
  }
  return spec.indexOf("@");
}

function parseMcpRemoteUrl(value: string | undefined): { host: string; scheme: string } | undefined {
  if (!value) return undefined;
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return undefined;
    return { host: parsed.hostname.toLowerCase(), scheme: parsed.protocol.replace(":", "") };
  } catch {
    return undefined;
  }
}

function extractSecretReferenceKeys(values: unknown[]): string[] {
  return extractEnvironmentReferenceKeys(values).filter((key) => isCredentialLikeKeyName(key));
}

function extractEnvironmentReferenceKeys(values: unknown[]): string[] {
  const keys = new Set<string>();
  for (const value of values) {
    if (typeof value !== "string") continue;
    for (const match of value.matchAll(/\$\{?([A-Z_][A-Z0-9_]*)\}?/g)) {
      if (match[1]) keys.add(match[1]);
    }
  }
  return [...keys].sort((a, b) => a.localeCompare(b));
}

function isLocalHost(host: string): boolean {
  return ["localhost", "127.0.0.1", "::1", "0.0.0.0"].includes(host);
}

function uniqueActions(actions: ActionType[]): ActionType[] {
  return [...new Set(actions)].sort((a, b) => a.localeCompare(b));
}

function isEnvFile(basename: string): boolean {
  return basename === ".env" || basename.startsWith(".env.");
}

function isOpenApiToolSpecPath(relativePath: string, basename: string): boolean {
  const normalized = relativePath.replaceAll("\\", "/").toLowerCase();
  const lowerBase = basename.toLowerCase();
  if (!/\.(json|ya?ml)$/iu.test(lowerBase)) return false;
  if (normalized.startsWith(".github/workflows/")) return false;
  if (normalized.startsWith("rules/")) return false;
  if (hasOpenApiNamingSignal(relativePath, basename)) return true;
  const segments = normalized.split("/").slice(0, -1);
  const apiDirectory = segments.some((segment) =>
    /^(tools?|actions?|functions?|openapi|swagger|api|api-tools?|api_tools?|agent-tools?|agent_tools?)$/iu.test(segment)
  );
  const apiName = /(?:api[-_]?tools?|tool[-_]?api|actions?[-_]?api|agent[-_]?api|agent[-_]?tools?)/iu.test(lowerBase);
  return apiDirectory || apiName;
}

function hasOpenApiNamingSignal(relativePath: string, basename: string): boolean {
  const normalized = relativePath.replaceAll("\\", "/").toLowerCase();
  const lowerBase = basename.toLowerCase();
  const segments = normalized.split("/").slice(0, -1);
  return (
    /(?:openapi|swagger)/iu.test(lowerBase) ||
    segments.some((segment) => /^(openapi|swagger|openapi-specs?|swagger-specs?)$/iu.test(segment))
  );
}

function extractWorkflowTriggers(value: unknown): string[] {
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) {
    return value.filter((item): item is string => typeof item === "string").sort((a, b) => a.localeCompare(b));
  }
  if (value && typeof value === "object") {
    return Object.keys(value as Record<string, unknown>).sort((a, b) => a.localeCompare(b));
  }
  return [];
}

function hasWritePermissions(value: unknown): boolean {
  if (typeof value === "string") return value === "write-all";
  if (!value || typeof value !== "object") return false;
  return Object.values(value as Record<string, unknown>).some((permission) => permission === "write");
}

const RUNTIME_CONFIG_BASENAMES = new Set([
  "config.json",
  "config.yaml",
  "config.yml",
  "config.toml",
  "settings.json",
  "settings.yaml",
  "settings.yml",
  "settings.toml",
  "runtime.json",
  "runtime.yaml",
  "runtime.yml",
  "runtime.toml"
]);

const TOP_LEVEL_RUNTIME_CONFIG_NAMES = new Set([
  "agent.config.json",
  "agent.config.yaml",
  "agent.config.yml",
  "agent.config.toml",
  "agents.config.json",
  "agents.config.yaml",
  "agents.config.yml",
  "agents.config.toml",
  "agent-runtime.json",
  "agent-runtime.yaml",
  "agent-runtime.yml",
  "agent-runtime.toml",
  "runtime.config.json",
  "runtime.config.yaml",
  "runtime.config.yml",
  "runtime.config.toml",
  "codex.toml",
  "codex.json",
  "codex.yaml",
  "codex.yml"
]);

interface RuntimeField {
  path: string;
  value: unknown;
}

interface RuntimePosture {
  runtime_fields: string[];
  sandbox_mode?: string;
  sandbox_disabled: boolean;
  workspace_write: boolean;
  approval_policy?: string;
  approval_bypass: boolean;
  network_access?: string;
  network_enabled: boolean;
  allowed_tools: string[];
  disabled_tools: string[];
  permission_allowlist: string[];
  permission_denylist: string[];
  auto_approved_package_script_names: string[];
  auto_approved_mcp_servers: string[];
  auto_approved_mcp_tool_refs: string[];
  auto_approved_mcp_tool_count: number;
  auto_approved_destructive_mcp_servers: string[];
  auto_approved_destructive_mcp_tool_refs: string[];
  auto_approved_destructive_mcp_tool_count: number;
  auto_approved_destructive_mcp_tools: boolean;
  auto_approved_network_tools: string[];
  auto_approved_network_scope_kinds: string[];
  auto_approved_network_scope_count: number;
  auto_approved_wildcard_network_scope: boolean;
  auto_approved_unscoped_network_tool: boolean;
  auto_approved_broad_network_scope: boolean;
  auto_approved_tools_redacted: boolean;
  auto_approved_tool_count: number;
  auto_approved_privileged_tool_count: number;
  auto_approved_privileged_tool_signal_count: number;
  auto_approved_privileged_tools: boolean;
  auto_approved_privileged_tool_signals: string[];
  privileged_tools_allowed: boolean;
  privileged_tool_signals: string[];
  env_key_names: string[];
  secret_env_exposure: boolean;
}

function isRuntimeConfigPath(relativePath: string, basename: string): boolean {
  const normalized = relativePath.replaceAll("\\", "/").toLowerCase();
  const lowerBase = basename.toLowerCase();
  if (TOP_LEVEL_RUNTIME_CONFIG_NAMES.has(lowerBase) && !normalized.includes("/")) return true;
  if (normalized.startsWith(".codex/") && RUNTIME_CONFIG_BASENAMES.has(lowerBase)) return true;
  if (normalized.startsWith(".agents/") && RUNTIME_CONFIG_BASENAMES.has(lowerBase)) return true;
  if (normalized.startsWith(".claude/") && RUNTIME_CONFIG_BASENAMES.has(lowerBase)) return true;
  if (normalized.startsWith(".cursor/") && RUNTIME_CONFIG_BASENAMES.has(lowerBase)) return true;
  return false;
}

function parseStructuredConfig(content: string, filePath: string): { value?: unknown; parseFailed: boolean; parser?: string } {
  if (!content.trim()) return { parseFailed: false };
  const lowerPath = filePath.toLowerCase();
  const parser = lowerPath.endsWith(".json")
    ? "json"
    : lowerPath.endsWith(".toml")
      ? "toml"
      : lowerPath.endsWith(".yaml") || lowerPath.endsWith(".yml")
        ? "yaml"
        : undefined;
  try {
    if (parser === "json") return { value: JSON.parse(content), parseFailed: false, parser };
    if (parser === "toml") return { value: parseToml(content), parseFailed: false, parser };
    if (parser === "yaml") return { value: YAML.parse(content), parseFailed: false, parser };
  } catch {
    return { parseFailed: true, parser };
  }
  return { parseFailed: false, parser };
}

function parseRuntimeConfig(content: string, filePath: string): { value?: unknown; parseFailed: boolean; parser?: string } {
  return parseStructuredConfig(content, filePath);
}

function classifyRuntimeConfig(value: unknown): RuntimePosture {
  const fields = flattenRuntimeFields(value);
  const sandboxMode = normalizeRuntimeScalar(findFirstField(fields, /(^|\.)sandbox(_mode|mode)?$|isolation|container/iu)?.value);
  const approvalPolicy = normalizeRuntimeScalar(
    findFirstField(fields, /approval|require_approval|tool_approval|human_approval|confirmation|confirm/iu)?.value
  );
  const networkAccess = normalizeRuntimeScalar(findFirstField(fields, /network|internet|web_access|allow_network|net_access/iu)?.value);
  const rawPermissionAllowlist = collectStringArrayFields(fields, /(^|\.)permissions\.(allow|allowed|allowlist)$/iu);
  const rawPermissionDenylist = collectStringArrayFields(fields, /(^|\.)permissions\.(deny|denied|denylist|block|blocked)$/iu);
  const permissionAllowlist = normalizeRuntimePermissionEntries(rawPermissionAllowlist);
  const permissionDenylist = normalizeRuntimePermissionEntries(rawPermissionDenylist);
  const configuredAllowedTools = collectStringArrayFields(fields, /(^|\.)(allowed_tools|allow_tools|enabled_tools|tools_allowlist|tools)$/iu);
  const configuredDisabledTools = collectStringArrayFields(fields, /(^|\.)(disabled_tools|deny_tools|blocked_tools|tools_denylist)$/iu);
  const allowedTools = uniqueStrings([
    ...configuredAllowedTools,
    ...permissionAllowlist
  ]);
  const disabledTools = uniqueStrings([
    ...configuredDisabledTools,
    ...permissionDenylist
  ]);
  const envKeys = collectEnvKeyNamesFromConfig(value);
  const privilegedSignals = classifyPrivilegedToolSignals([...configuredAllowedTools, ...rawPermissionAllowlist]);
  const autoApprovedPrivilegedSignals = classifyPrivilegedToolSignals(rawPermissionAllowlist);
  const autoApprovedPrivilegedToolCount = rawPermissionAllowlist.filter(
    (entry) => classifyPrivilegedToolSignals([entry]).length > 0
  ).length;
  const autoApprovedPackageScriptNames = extractPackageScriptNames(rawPermissionAllowlist.join("\n"));
  const autoApprovedMcpToolRefs = extractRuntimeMcpToolRefs(rawPermissionAllowlist);
  const autoApprovedDestructiveMcpToolRefs = autoApprovedMcpToolRefs.filter((ref) => isDestructiveMcpToolRef(ref.toolName));
  const autoApprovedNetworkScopes = extractRuntimeNetworkScopes(rawPermissionAllowlist);
  const networkEnabled = Boolean(
    (networkAccess && /true|yes|enabled|enable|on|full|unrestricted|allow/iu.test(networkAccess)) ||
      privilegedSignals.some((signal) => ["browser", "external_messaging", "github"].includes(signal)) ||
      autoApprovedNetworkScopes.length > 0
  );
  const autoApprovedNetworkScopeKinds = uniqueStrings(autoApprovedNetworkScopes.map((scope) => scope.scopeKind));

  return {
    runtime_fields: fields
      .map((field) => field.path)
      .filter((fieldPath) => isRuntimeSecurityField(fieldPath))
      .sort((a, b) => a.localeCompare(b)),
    sandbox_mode: sandboxMode,
    sandbox_disabled: Boolean(sandboxMode && /danger|disable|none|off|false|unrestricted|full|host/iu.test(sandboxMode)),
    workspace_write: Boolean(sandboxMode && /workspace.*write|write.*workspace|project.*write/iu.test(sandboxMode)),
    approval_policy: approvalPolicy,
    approval_bypass: Boolean(
      (approvalPolicy && /never|none|auto|always_allow|disabled|disable|off|false|unrestricted|no_approval|without/iu.test(approvalPolicy)) ||
        autoApprovedPrivilegedSignals.length > 0
    ),
    network_access: networkAccess,
    network_enabled: networkEnabled,
    allowed_tools: allowedTools,
    disabled_tools: disabledTools,
    permission_allowlist: permissionAllowlist,
    permission_denylist: permissionDenylist,
    auto_approved_package_script_names: autoApprovedPackageScriptNames,
    auto_approved_mcp_servers: uniqueStrings(autoApprovedMcpToolRefs.map((ref) => ref.serverName)),
    auto_approved_mcp_tool_refs: uniqueStrings(autoApprovedMcpToolRefs.map((ref) => ref.ref)),
    auto_approved_mcp_tool_count: autoApprovedMcpToolRefs.length,
    auto_approved_destructive_mcp_servers: uniqueStrings(autoApprovedDestructiveMcpToolRefs.map((ref) => ref.serverName)),
    auto_approved_destructive_mcp_tool_refs: uniqueStrings(autoApprovedDestructiveMcpToolRefs.map((ref) => ref.ref)),
    auto_approved_destructive_mcp_tool_count: autoApprovedDestructiveMcpToolRefs.length,
    auto_approved_destructive_mcp_tools: autoApprovedDestructiveMcpToolRefs.length > 0,
    auto_approved_network_tools: uniqueStrings(autoApprovedNetworkScopes.map((scope) => scope.toolName)),
    auto_approved_network_scope_kinds: autoApprovedNetworkScopeKinds,
    auto_approved_network_scope_count: autoApprovedNetworkScopes.length,
    auto_approved_wildcard_network_scope: autoApprovedNetworkScopeKinds.some(
      (scopeKind) => scopeKind.startsWith("wildcard_") || scopeKind === "all_tools"
    ),
    auto_approved_unscoped_network_tool: autoApprovedNetworkScopeKinds.includes("unscoped_network_tool"),
    auto_approved_broad_network_scope: autoApprovedNetworkScopeKinds.some(
      (scopeKind) => scopeKind.startsWith("wildcard_") || scopeKind === "all_tools" || scopeKind === "unscoped_network_tool"
    ),
    auto_approved_tools_redacted: permissionAllowlist.length > 0,
    auto_approved_tool_count: rawPermissionAllowlist.length,
    auto_approved_privileged_tool_count: autoApprovedPrivilegedToolCount,
    auto_approved_privileged_tool_signal_count: autoApprovedPrivilegedSignals.length,
    auto_approved_privileged_tools: autoApprovedPrivilegedSignals.length > 0,
    auto_approved_privileged_tool_signals: autoApprovedPrivilegedSignals,
    privileged_tools_allowed: privilegedSignals.length > 0,
    privileged_tool_signals: privilegedSignals,
    env_key_names: envKeys,
    secret_env_exposure: envKeys.some((key) => /token|secret|key|password|credential|auth/iu.test(key))
  };
}

function flattenRuntimeFields(value: unknown, prefix: string[] = []): RuntimeField[] {
  if (Array.isArray(value)) {
    const primitiveValues = value.filter((item) => ["string", "number", "boolean"].includes(typeof item));
    const nestedValues = value.flatMap((item, index) =>
      item && typeof item === "object" ? flattenRuntimeFields(item, [...prefix, String(index)]) : []
    );
    return primitiveValues.length > 0
      ? [{ path: prefix.join("."), value: primitiveValues.map((item) => String(item)) }, ...nestedValues]
      : nestedValues;
  }
  if (value && typeof value === "object") {
    return Object.entries(value as Record<string, unknown>).flatMap(([key, item]) =>
      flattenRuntimeFields(item, [...prefix, key])
    );
  }
  if (prefix.length === 0) return [];
  return [{ path: prefix.join("."), value }];
}

function findFirstField(fields: RuntimeField[], pathPattern: RegExp): RuntimeField | undefined {
  return fields.find((field) => pathPattern.test(field.path));
}

function normalizeRuntimeScalar(value: unknown): string | undefined {
  if (typeof value === "string") return value.toLowerCase();
  if (typeof value === "boolean" || typeof value === "number") return String(value).toLowerCase();
  if (Array.isArray(value)) return value.map((item) => String(item).toLowerCase()).join(",");
  return undefined;
}

function collectStringArrayFields(fields: RuntimeField[], pathPattern: RegExp): string[] {
  const values = new Set<string>();
  for (const field of fields) {
    if (!pathPattern.test(field.path)) continue;
    if (Array.isArray(field.value)) {
      for (const value of field.value) values.add(String(value));
      continue;
    }
    if (typeof field.value === "string") values.add(field.value);
  }
  return [...values].sort((a, b) => a.localeCompare(b));
}

function normalizeRuntimePermissionEntries(entries: string[]): string[] {
  return uniqueStrings(entries.map(normalizeRuntimePermissionEntry));
}

function normalizeRuntimePermissionEntry(entry: string): string {
  const trimmed = entry.trim();
  if (!trimmed) return "redacted_permission";
  if (trimmed === "*") return "*";

  const mcpMatch = trimmed.match(/^mcp__([^_\s()]+)__[^()\s]+/iu);
  if (mcpMatch?.[1]) return `mcp:${mcpMatch[1]}`;

  const toolCallMatch = trimmed.match(/^([a-zA-Z][\w-]*)\s*\(/u);
  if (toolCallMatch?.[1]) return toolCallMatch[1];

  const mcpRuntimeMatch = trimmed.match(/^mcp[:/]([^()\s]+)/iu);
  if (mcpRuntimeMatch?.[1]) return `mcp:${normalizeCallableName(mcpRuntimeMatch[1])}`;

  if (/^[a-zA-Z][\w:.-]{0,79}$/u.test(trimmed)) return trimmed;
  return "redacted_permission";
}

interface RuntimeMcpToolRef {
  serverName: string;
  toolName: string;
  ref: string;
}

function extractRuntimeMcpToolRefs(entries: string[]): RuntimeMcpToolRef[] {
  const refs = new Map<string, RuntimeMcpToolRef>();
  for (const entry of entries) {
    const trimmed = entry.trim();
    const claudeMatch = trimmed.match(/^mcp__([^_\s()]+)__([^()\s]+)$/iu);
    if (claudeMatch?.[1] && claudeMatch[2]) {
      const serverName = normalizeCallableName(claudeMatch[1]);
      const toolName = normalizeCallableName(claudeMatch[2]);
      const ref = `mcp:${serverName}/${toolName}`;
      refs.set(ref, { serverName, toolName, ref });
      continue;
    }

    const runtimeMatch = trimmed.match(/^mcp[:/]([^/\s()]+)[/:]([^()\s]+)$/iu);
    if (runtimeMatch?.[1] && runtimeMatch[2]) {
      const serverName = normalizeCallableName(runtimeMatch[1]);
      const toolName = normalizeCallableName(runtimeMatch[2]);
      const ref = `mcp:${serverName}/${toolName}`;
      refs.set(ref, { serverName, toolName, ref });
    }
  }
  return [...refs.values()].sort((a, b) => a.ref.localeCompare(b.ref));
}

function isDestructiveMcpToolRef(toolName: string): boolean {
  return /\b(delete|remove|drop|truncate|destroy|purge|wipe|write|update|modify|publish|release|deploy|send|post)\b/iu.test(
    toolName.replace(/[_-]/g, " ")
  );
}

interface RuntimeNetworkScope {
  toolName: string;
  scopeKind: string;
}

function extractRuntimeNetworkScopes(entries: string[]): RuntimeNetworkScope[] {
  const scopes = new Map<string, RuntimeNetworkScope>();
  for (const entry of entries) {
    const trimmed = entry.trim();
    if (!trimmed) continue;
    if (trimmed === "*" || /^all[-_\s]?tools$/iu.test(trimmed)) {
      addRuntimeNetworkScope(scopes, "all_tools", "all_tools");
      continue;
    }

    const toolCallMatch = trimmed.match(/^([a-zA-Z][\w-]*)\s*(?:\((.*)\))?$/u);
    if (!toolCallMatch?.[1]) continue;

    const toolName = canonicalRuntimeNetworkToolName(toolCallMatch[1]);
    if (!toolName) continue;

    addRuntimeNetworkScope(scopes, toolName, runtimeNetworkScopeKind(toolName, toolCallMatch[2]));
  }
  return [...scopes.values()].sort((a, b) => `${a.toolName}:${a.scopeKind}`.localeCompare(`${b.toolName}:${b.scopeKind}`));
}

function addRuntimeNetworkScope(scopes: Map<string, RuntimeNetworkScope>, toolName: string, scopeKind: string): void {
  const key = `${toolName}:${scopeKind}`;
  scopes.set(key, { toolName, scopeKind });
}

function canonicalRuntimeNetworkToolName(toolName: string): string | undefined {
  const normalized = normalizeCallableName(toolName);
  if (/^web_?fetch$/iu.test(normalized)) return "WebFetch";
  if (/^web_?search$/iu.test(normalized)) return "WebSearch";
  if (/^browser$/iu.test(normalized)) return "Browser";
  if (/^fetch$/iu.test(normalized)) return "fetch";
  if (/^request$/iu.test(normalized)) return "request";
  if (/^http$/iu.test(normalized)) return "http";
  if (/^curl$/iu.test(normalized)) return "curl";
  if (/^playwright$/iu.test(normalized)) return "playwright";
  if (/^puppeteer$/iu.test(normalized)) return "puppeteer";
  return undefined;
}

function runtimeNetworkScopeKind(toolName: string, scopeText: string | undefined): string {
  if (!scopeText || !scopeText.trim()) return "unscoped_network_tool";

  const normalized = scopeText.toLowerCase();
  if (/domain\s*[:=]\s*\*/iu.test(normalized)) return "wildcard_domain";
  if (/url\s*[:=]\s*\*|https?:\/\/\*/iu.test(normalized)) return "wildcard_url";
  if (/^\s*\*\s*$/u.test(scopeText)) return toolName === "WebSearch" ? "wildcard_search" : "wildcard_network";
  if (/(^|[,:=\s])\*(?:[,)\s]|$)/u.test(scopeText)) return "wildcard_network";
  if (/domain|host/iu.test(normalized)) return "scoped_domain";
  if (/url|https?:\/\//iu.test(normalized)) return "scoped_url";
  if (toolName === "WebSearch") return "scoped_search";
  return "scoped_network";
}

function collectEnvKeyNamesFromConfig(value: unknown, prefix: string[] = []): string[] {
  const keys = new Set<string>();
  if (!value || typeof value !== "object" || Array.isArray(value)) return [];
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    const nextPrefix = [...prefix, key];
    const pathText = nextPrefix.join(".").toLowerCase();
    if (item && typeof item === "object" && !Array.isArray(item)) {
      if (/(^|\.)(env|environment|env_vars|secrets?)$/iu.test(pathText)) {
        for (const envKey of Object.keys(item as Record<string, unknown>)) keys.add(envKey);
      }
      for (const nestedKey of collectEnvKeyNamesFromConfig(item, nextPrefix)) keys.add(nestedKey);
      continue;
    }
    if (/token|secret|api[_-]?key|password|credential|auth/iu.test(key)) keys.add(key);
  }
  return [...keys].sort((a, b) => a.localeCompare(b));
}

function classifyPrivilegedToolSignals(tools: string[]): string[] {
  const signals = new Set<string>();
  const joined = tools.join(" ").toLowerCase();
  if (/(^|\s|\*)\*(\s|$)|all_tools|all-tools|all tools/iu.test(joined)) signals.add("all_tools");
  if (/shell|bash|zsh|terminal|command|exec|process/iu.test(joined)) signals.add("shell");
  if (/browser|web|webfetch|websearch|playwright|puppeteer/iu.test(joined)) signals.add("browser");
  if (/mcp:|mcp__/iu.test(joined)) signals.add("mcp");
  if (/filesystem|file|workspace|fs|edit|multiedit|write|delete|notebookedit/iu.test(joined)) signals.add("filesystem");
  if (/github|gitlab|repo|pull|issue/iu.test(joined)) signals.add("github");
  if (/slack|email|smtp|webhook/iu.test(joined)) signals.add("external_messaging");
  return [...signals].sort((a, b) => a.localeCompare(b));
}

function isRuntimeSecurityField(fieldPath: string): boolean {
  return /sandbox|approval|confirm|network|internet|web_access|tool|permission|allow|deny|env|environment|secret|token|credential/iu.test(fieldPath);
}

