  const pattern = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:await\s*)?(?:fetch\s*\(|axios\s*\.\s*(?:get|request)\s*\(|got\s*\(|request\s*\(|(?:http|https)\s*\.\s*(?:request|get)\s*\()/gu;
